    "categoryKey": "rashidun",
    "categoryBn": "খোলাফায়ে রাশেদীন (#২)",
    "birthAndDeathBn": "জন্ম: ৫৮৩ খ্রি. মক্কা | শাহাদাত: ২৬ জিলহজ, ২৩ হিজরি (৬৪৪ খ্রি.)",
    "summaryBn": "ন্যায়বিচার, নির্ভীকতা, অসাধারণ দূরদর্শিতা ও আধুনিক প্রশাসনিক সংস্কারের কালজয়ী প্রতীক; যাঁর পদশব্দ শুনলে শয়তানও পথ পরিবর্তন করত এবং যাঁর শাসনামলে পারস্য ও রোমান সাম্রাজ্যের পতন ঘটে বিশ্বমঞ্চে ইনসাফের রাজত্ব প্রতিষ্ঠিত হয়েছিল।",
    "detailedBiographyBn": "হযরত উমর ইবনুল খাত্তাব (রা.) ছিলেন কুরাইশ বংশের বনু আদি গোত্রের এক তেজস্বী ও প্রভাবশালী ব্যক্তিত্ব। তিনি ছিলেন বীর যোদ্ধা, কুস্তিগীর ও আরবের অন্যতম শীর্ষ কূটনীতিবিদ। রাসুলুল্লাহ (সা.) দোয়া করেছিলেন: \"হে আল্লাহ! আবু জাহেল অথবা উমরের মাধ্যমে ইসলামকে শক্তিশালী করো।\" আল্লাহ তাআলা উমর (রা.)-এর মাধ্যমে সেই দোয়া কবুল করেন।\n\nনবুওয়াতের ষষ্ঠ বর্ষে রাসুল (সা.)-কে হত্যার উদ্দেশ্যে তরবারি হাতে বের হয়ে নিজের বোন ফাতিমা ও ভগ্নিপতি সাঈদের ঘরে কুরআনের তিলাওয়াত শুনে তাঁর হৃদয় বিগলিত হয়। দারুল আরকামে উপস্থিত হয়ে রাসুল (সা.)-এর হাতে ইসলাম গ্রহণ করেন। তাঁর ইসলাম গ্রহণের সাথে সাথেই মুসলমানগণ গোপনে সালাত আদায়ের ভয় কাটিয়ে কাবার সামনে প্রকাশ্যে সালাত আদায় শুরু করেন। হিজরতের সময় অন্য সাহাবিরা গোপনে গেলেও উমর (রা.) কাবা তাওয়াফ করে প্রকাশ্যে কাফেরদের চ্যালেঞ্জ ছুড়ে মদিনার উদ্দেশ্যে যাত্রা করেন।\n\nআবু বকর (রা.)-এর ওফাতের পর তিনি দ্বিতীয় খলিফা হিসেবে দায়িত্বভার গ্রহণ করেন। তাঁর ১০ বছরের শাসনামলে ইসলামি ভূখণ্ডে এক যুগান্তকারী বিপ্লব ঘটে। তিনি বাইতুল মাল, পুলিশ বাহিনী, ডাক বিভাগ, স্থায়ী সেনাবাহিনী, আদালত এবং বিচার ব্যবস্থার ভিত্তি স্থাপন করেন। তিনিই হিজরি সনের প্রবর্তন করেন। ইয়ারমুক ও কাদিসিয়ার ঐতিহাসিক বিজয়ের মাধ্যমে তাঁর সময়ে পারস্য ও বাইজেন্টাইন পরাশক্তির পতন ঘটে। জেরুসালেম বিজয়ের পর তিনি একটি মাত্র উট নিয়ে ভৃত্যকে চড়িয়ে নিজে হেঁটে পবিত্র মসজিদে আকসায় প্রবেশ করেন।",
    "islamAcceptanceBn": "নবুওয়াতের ষষ্ঠ বছরে রাসুল (সা.)-এর দোয়ার ফসল হিসেবে উমর (রা.) ইসলাম গ্রহণ করেন। তাঁর বোন ফাতিমার ঘরে সূরা ত্বা-হার আয়াত শুনে তাঁর চোখ দিয়ে অশ্রুধারা বইতে থাকে। এরপর আরকাম (রা.)-এর ঘরে গিয়ে রাসুল (সা.)-এর কদমে লুটিয়ে পড়ে কালিমায়ে শাহাদাত পাঠ করেন। তাঁর ইসলাম গ্রহণে জিবরাইল (আ.) এসে রাসুলকে সুসংবাদ দেন যে আসমানের ফেরেশতারাও উমরের ইসলামে আনন্দিত হয়েছে।",
