        "story": "এক রাতে উমর (রা.) ছদ্মবেশে মদিনার উপকণ্ঠে ঘুরছিলেন। দেখলেন এক তাঁবুতে কিছু বাচ্চা কান্নাকাটি করছে আর তাদের মা চুলায় হাঁড়িতে পানি ফোটাচ্ছে। উমর কারণ জানতে চাইলে মহিলা বললেন, বাচ্চারা ক্ষুধায় কাঁদছে, তাই পাতিল চাপিয়ে রেখেছি যেন সান্ত্বনা পেয়ে ঘুমিয়ে পড়ে। আর বললেন: \"উমর আমাদের কোনো খবর রাখে না, আল্লাহর দরবারে আমি উমরের বিচার চাইব!\" এ কথা শুনে উমর (রা.) কেঁপে উঠলেন। নিজের পরিচয় না দিয়ে দ্রুত বাইতুল মালে ছুটে গেলেন। নিজের কাঁধে আটা, তেল ও খেজুরের বস্তা তুলে নিলেন। ভৃত্য আসলাম বহন করতে চাইলে বললেন: \"কেয়ামতের দিন কি তুমি আমার পাপের বোঝা বইবে?\" এরপর নিজ হাতে রুটি ও হালুয়া রান্না করে শিশুদের পেট ভরে খাওয়ালেন।"
