        "story": "জেরুসালেমের খ্রিস্টান পাদ্রিরা শর্ত দিল যে খলিফা নিজে এলে চাবি হস্তান্তর করা হবে। উমর (রা.) তাঁর ভৃত্যসহ মাত্র একটি উট নিয়ে যাত্রা করলেন। নিয়ম করলেন এক মাইল উমর চড়বেন, এক মাইল ভৃত্য চড়বে আর এক মাইল উটকে বিশ্রাম দিয়ে দুজনে হেঁটে যাবেন। শহরের কাছাকাছি পৌঁছার সময় ভৃত্যের চড়ার পালা আসল। ভৃত্য অনুরোধ করল: \"হে আমিরুল মুমিনীন, আপনি চড়ুন, রোমানরা দেখবে!\" উমর দৃঢ়ভাবে প্রত্যাখ্যান করে বললেন: \"ইনসাফ কখনো ভঙ্গ হতে পারে না।\" তিনি উটের রশি ধরে কাদা মাড়িয়ে জেরুসালেমে প্রবেশ করলেন। এই দৃশ্য দেখে পাদ্রিরা কান্নায় ভেঙে পড়ল এবং স্বেচ্ছায় চাবি সমর্পণ করল।"
