    "nameAr": "عثمان بن عفان رضي الله عنه",
    "titleBn": "জুন-নুরাইন (দুই জ্যোতির অধিকারী), জামিউল কুরআন, গনি (মহাদানবীর)",
    "categoryKey": "rashidun",
    "categoryBn": "খোলাফায়ে রাশেদীন (#৩)",
    "birthAndDeathBn": "জন্ম: ৫৭৬ খ্রি. তায়েফ | শাহাদাত: ১৮ জিলহজ, ৩৫ হিজরি (৬৫৬ খ্রি.)",
    "summaryBn": "চরম লজ্জা, নম্রতা ও আত্মত্যাগের মূর্ত প্রতীক, যাঁর চরিত্র ও লজ্জাশীলতার সামনে আসমানের ফেরেশতারাও লজ্জা পেতেন; সমগ্র মুসলিম উম্মাহকে একই মুসহাফে একত্রিতকারী এবং অকাতরে ইসলামে অর্থ ঢেলে দেওয়া তৃতীয় খলিফা।",
    "detailedBiographyBn": "হযরত উসমান ইবনে আফফান (রা.) ছিলেন কুরাইশ বংশের বনু উমাইয়া শাখার অত্যন্ত সুদর্শন, সুশিক্ষিত ও বিপুল ধনসম্পদের অধিকারী বিশিষ্ট ব্যবসায়ী। জাহেলি যুগেও তিনি ছিলেন মদ ও অন্যায় থেকে মুক্ত নির্মল চরিত্রের মানুষ।\n\nআবু বকর (রা.)-এর মাধ্যমে তিনি প্রাথমিক পর্যায়েই ইসলাম গ্রহণ করেন। তাঁর চাচা হাকাম তাঁকে রশিতে বেঁধে খেজুরের পাতার মাদুরে পেঁচিয়ে নিচে ধোঁয়া দিয়ে নির্যাতন করত যেন তিনি ইসলাম ত্যাগ করেন, কিন্তু উসমান (রা.) পাহাড়ের মতো অটল থেকে বলেন: \"আল্লাহর শপথ! আমি কখনোই এই সত্য দ্বীন পরিত্যাগ করব না।\" তিনি রাসুল (সা.)-এর কন্যা রুকাইয়্যাহ (রা.)-কে নিয়ে হাবশায় প্রথম হিজরতকারীদের দলনেতা ছিলেন। রুকাইয়্যাহর ইন্তেকালের পর রাসুল (সা.) তাঁর দ্বিতীয় কন্যা উম্মে কুলসুম (রা.)-কে তাঁর সাথে বিবাহ দেন, যার কারণে তিনি 'জুন-নুরাইন' (দুই জ্যোতির অধিকারী) উপাধিতে ভূষিত হন।\n\nউসমান (রা.) ছিলেন ইসলামের সর্বশ্রেষ্ঠ দানবীরদের একজন। মদিনায় হিজরতের পর সুপেয় পানির তীব্র সংকট দূর করতে ইহুদির কাছ থেকে ‘বিরে রুমা’ কূপটি নগদ ৩৫ হাজার দিরহামে কিনে মুসলিমদের জন্য ওয়াকফ করে দেন। মসজিদে নববীর স্থান সংকুলান হলে নিজ খরচে পার্শ্ববর্তী জমি কিনে মসজিদ সম্প্রসারণ করেন। তাবুক যুদ্ধের জন্য তিনি একাই ৩০০ উট, ৫০টি ঘোড়া এবং ১০০০ স্বর্ণমুদ্রা রাসুল (সা.)-এর কোলে ঢেলে দেন। তাঁর ১২ বছরের খেলাফতকালে উত্তর আফ্রিকা, আর্মেনিয়া, সাইপ্রাসসহ দূরদূরান্তে ইসলাম বিস্তার লাভ করে এবং ইসলামি নৌবাহিনীর সূচনা হয়। তাঁর সবচেয়ে বড় ঐতিহাসিক অবদান হলো বিভ্রান্তি দূর করে সমগ্র উম্মাহকে এক প্রামাণিক \"মুসহাফে উসমানি\"-তে একত্রিত করা।",
    "islamAcceptanceBn": "ইসলামের প্রথম দিকেই পরম বন্ধু আবু বকর সিদ্দিক (রা.)-এর দাওয়াতে তিনি রাসুলুল্লাহ (সা.)-এর খেদমতে উপস্থিত হয়ে ইসলাম গ্রহণ করেন। ইসলাম গ্রহণের পর তাঁর নিজ গোত্র বনু উমাইয়া চরম ক্ষুব্ধ হয় এবং চাচা হাকাম তাঁকে নির্মম শারীরিক নির্যাতন করে, কিন্তু তিনি হাসিমুখে সব সহ্য করেন।",
