        "story": "বিদ্রোহীরা তাঁর বাড়ি ৪০ দিন ধরে অবরুদ্ধ করে রাখে। পানির একটি ফোঁটাও প্রবেশ করতে দেয়নি। বহু তরুণ সাহাবি—হাসান, হোসাইন, আব্দুল্লাহ ইবনে জুবায়ের (রা.) তরবারি নিয়ে উসমানকে রক্ষা করতে চেয়েছিলেন। কিন্তু উসমান (রা.) কঠোর আদেশ দেন: \"আমার জন্য মদিনার পবিত্র মাটিতে এক ফোঁটা মুসলিম রক্ত ঝরুক—আমি তা কোনোদিন মেনে নেব না।\" মৃত্যুর আগের রাতে স্বপ্নে রাসুল (সা.)-কে দেখলেন। রাসুল (সা.) বললেন: \"উসমান! তুমি কি তৃষ্ণার্ত? আগামীকাল আমাদের সাথে ইফতার করবে।\" পরদিন তিনি রোজা রেখে কুরআন তিলাওয়াত করছিলেন। ঘাতকরা ঘরে ঢুকে তরবারির আঘাত হানলে তাঁর পবিত্র রক্ত কুরআনের সূরা বাকারার ১৩৭ নং আয়াত—\"আল্লাহই তাদের বিরুদ্ধে তোমার জন্য যথেষ্ট\"—এর ওপর ছিটকে পড়ে।"
