    "deathOrMartyrdomBn": "৩৫ হিজরির ১৮ জিলহজ জুমার দিনে রোজা রাখা অবস্থায় কুরআন তিলাওয়াতকালে ৮০ বছর বয়সে অবরুদ্ধ নিজ ঘরে বিদ্রোহীদের হাতে নির্মমভাবে শহীদ হন। জান্নাতুল বাকিতে রাতের আঁধারে সাহাবিগণ পরম ভালোবাসায় তাঁকে সমাহিত করেন।",
