      "উহুদ যুদ্ধে রাসুল (সা.)-এর জীবন রক্ষার্থে নিজের হাত অবশ করে ফেলেন এবং শরীরে ৭০টির বেশি ক্ষত বরণ করেন।",
      "আশারায়ে মুবাশশারা (জান্নাতের সুসংবাদপ্রাপ্ত দশজন)-এর অন্যতম সম্মানিত সদস্য।",
