        "textBn": "যে ব্যক্তি এমন কোনো শহীদকে দেখতে পছন্দ করে, যে জমিনের বুকে হেঁটে বেড়াচ্ছে, সে যেন তালহা ইবনে উবাইদুল্লাহকে দেখে।",
