    "deathOrMartyrdomBn": "৩৬ হিজরিতে জঙ্গে জামালের যুদ্ধক্ষেত্র থেকে সরে আসার সময় মারওয়ান ইবনুল হাকামের অতর্কিত বিষাক্ত তীরের আঘাতে ৬৪ বছর বয়সে শাহাদাত বরণ করেন। বসরার প্রান্তে তাঁকে সমাহিত করা হয়। আলী (রা.) তাঁর জানাজায় কান্নায় ভেঙে পড়ে তাঁর জন্য দোয়া করেন।",
