    "categoryBn": "আশারায়ে মুবাশশারা (#৬)",
    "birthAndDeathBn": "জন্ম: ৫৯৪ খ্রি. মক্কা | শাহাদাত: ৩৬ হিজরি (৬৫৬ খ্রি.)",
    "summaryBn": "ইসলামের ইতিহাসে প্রথম উন্মুক্ত তরবারি উত্তোলনকারী কিশোর বীর, রাসুলুল্লাহ (সা.)-এর ফুফাতো ভাই ও জান্নাতের সুসংবাদপ্রাপ্ত সহচর; যাঁর রণনৈপুণ্য ও বীরত্বে ফেরেশতারাও বিস্মিত হতেন।",
    "detailedBiographyBn": "হযরত যুবায়ের ইবনুল আওয়াম (রা.) ছিলেন রাসুলুল্লাহ (সা.)-এর আপন ফুফু সফিয়্যাহ বিনতে আব্দুল মুত্তালিবের পুত্র এবং উম্মুল মুমিনীন খাদিজা (রা.)-এর ভ্রাতুষ্পুত্র। মাত্র ১৫ বা ১৬ বছর বয়সে তিনি ইসলাম গ্রহণ করেন।\n\nইসলাম গ্রহণের কারণে তাঁর চাচা তাঁকে খেজুর পাতার মাদুরে পেঁচিয়ে নিচে আগুন জ্বালিয়ে দিত যেন ধোঁয়ায় দমবন্ধ হয়ে তিনি ইসলাম ছাড়েন। কিন্তু কিশোর যুবায়ের হুংকার দিয়ে বলতেন: \"আমি কখনোই কুফরির দিকে ফিরে যাব না!\" মক্কায় একবার গুজব রটে যে রাসুল (সা.) কাফেরদের হাতে নিহত হয়েছেন। এ কথা শোনামাত্র ১৬ বছরের যুবায়ের উন্মুক্ত তরবারি হাতে মক্কার অলিগলি চষে রাসুলের দরবারে উপস্থিত হন। রাসুল (সা.) বেঁচে আছেন দেখে আবেগাপ্লুত হন। রাসুল তাঁর জন্য ও তাঁর তরবারির জন্য দোয়া করেন। এটিই ছিল ইসলামের ইতিহাসে আল্লাহর রাস্তায় প্রথম উন্মুক্ত তরবারি।\n\nবদর যুদ্ধে তিনি হলুদ পাগড়ি পরে এমন তাণ্ডব চালিয়েছিলেন যে রাসুল (সা.) বলেছিলেন: \"আজ ফেরেশতারা যুবায়েরের বেশ ধারণ করে যুদ্ধ করছে।\" খন্দকের যুদ্ধে বনু কুরাইজার ষড়যন্ত্রের খবর আনতে রাসুল (সা.) তিনবার সাহাবিদের আহ্বান করলে প্রতিবারই যুবায়ের একা দাঁড়িয়ে যেতেন। তখনই রাসুল তাঁকে 'হাওয়ারী' উপাধি দেন। ইয়ারমুকের যুদ্ধে তিনি একাই রোমানদের দুই ব্যূহ ভেদ করে অপর প্রান্তে চলে যান এবং পুনরায় ব্যূহ ভেদ করে ফিরে আসেন।",
    "islamAcceptanceBn": "আবু বকর (রা.)-এর আহ্বানে মাত্র ১৫-১৬ বছর বয়সে তিনি ইসলাম গ্রহণ করেন। ইসলাম গ্রহণের পর তাঁর আপন চাচা তাঁকে নির্মম নির্যাতন করত, ধোঁয়ায় শ্বাসরোধ করে ফেলত, কিন্তু তিনি একত্ববাদের ওপর অটল থাকেন।",
