    "deathOrMartyrdomBn": "৫১ হিজরিতে মদিনার নিকটে আকিক নামক স্থানে ৮০ বছর বয়সে ইন্তেকাল করেন। সা’দ ইবনে আবি ওয়াক্কাস ও আব্দুল্লাহ ইবনে উমর (রা.) তাঁকে গোসল করান এবং মদিনার জান্নাতুল বাকিতে তাঁকে দাফন করা হয়।",
