    "birthAndDeathBn": "জন্ম: ৫৮১ খ্রি. মক্কা | ওফাত: ৩২ হিজরি (৬৫২ খ্রি.)",
    "summaryBn": "মদিনার বাজারে রিক্তহস্তে নেমে মাত্র কয়েক বছরের মধ্যে হালাল ব্যবসা ও সততার জোরে মদিনার শীর্ষ ধনী হওয়া দানবীর সাহাবি; যাঁর পেছনে দাঁড়িয়ে স্বয়ং রাসুলুল্লাহ (সা.) এক ওয়াক্ত সালাত আদায় করেছিলেন।",
    "detailedBiographyBn": "হযরত আব্দুর রহমান ইবনে আওফ (রা.) ছিলেন কুরাইশ বংশের বনু জুহরা গোত্রের সন্তান। জাহেলি যুগে তাঁর নাম ছিল আবু আমর বা আব্দে কা’বা; রাসুলুল্লাহ (সা.) তাঁর নাম পরিবর্তন করে রাখেন ‘আব্দুর রহমান’। তিনি ছিলেন আবু বকর (রা.)-এর দাওয়াতে ইসলাম গ্রহণকারী প্রথম আটজন পুরুষের একজন।\n\nমক্কার নির্মম নির্যাতন সহ্য করে তিনি প্রথমে হাবশায় এবং পরবর্তীতে মদিনায় হিজরত করেন। মদিনায় পৌঁছার পর রাসুল (সা.) আনসার সাহাবি সা’দ ইবনে রাবি (রা.)-এর সাথে তাঁর ভ্রাতৃত্ব বন্ধন গড়ে দেন। সা’দ তাঁকে বললেন: \"আমার অর্ধেক সম্পদ এবং আমার দুই স্ত্রীর একজনকে তালাক দিয়ে আপনার জন্য সমর্পণ করছি।\" আব্দুর রহমান বিনয়ের সাথে উত্তর দিলেন: \"আল্লাহ তোমার পরিবার ও সম্পদে বরকত দিন, আমাকে কেবল মদিনার বাজারের পথ দেখিয়ে দাও।\" তিনি কায়নুকা বাজারে গিয়ে ঘি ও পনিরের ব্যবসা শুরু করেন এবং অল্প দিনেই সততার মাধ্যমে বিপুল সম্পদের মালিক হন।\n\nআব্দুর রহমান ইবনে আওফ (রা.) বদর, উহুদসহ প্রতিটি যুদ্ধে বীরত্ব প্রদর্শন করেন। উহুদে তিনি বিশটির বেশি আঘাত পান এবং পায়ে আঘাতের ফলে জীবনের বাকি সময় কিছুটা খুঁড়িয়ে হাঁটতেন। তাবুক যুদ্ধে তিনি অকাতরে ২০০ উকিয়া স্বর্ণ দান করেন এবং সেই যুদ্ধেই রাসুল (সা.) এক ওয়াক্ত ফজরের নামাজে আব্দুর রহমানের পেছনে মুক্তাদি হয়ে সালাত আদায় করেছিলেন। উমর (রা.)-এর শাহাদাতের পর গঠিত ছয় সদস্যের খলিফা নির্বাচন কমিটির প্রধান সমন্বয়ক ছিলেন আব্দুর রহমান, যিনি নিজের খলিফা হওয়ার দাবি স্বেচ্ছায় ত্যাগ করে উসমান (রা.)-কে খলিফা নির্বাচিত করেন।",
    "islamAcceptanceBn": "ইসলামের একেবারেই প্রথম প্রহরে আবু বকর সিদ্দিক (রা.)-এর অনুপ্রেরণায় তিনি দারুল আরকামে যাওয়ার পূর্বেই রাসুল (সা.)-এর হাতে ইসলাম গ্রহণ করেন। মক্কার নির্যাতনে অটল থেকে দুইবার হিজরত করার অনন্য সৌভাগ্য অর্জন করেন।",
