    "nameAr": "أبو عبيدة بن الجراح رضي الله عنه",
    "titleBn": "আমীনুল উম্মাহ (এই উম্মতের পরম বিশ্বস্ত ব্যক্তি), সিরিয়ার প্রধান সেনাপতি",
