    "birthAndDeathBn": "জন্ম: ৫৮৩ খ্রি. মক্কা | ওফাত: ১৮ হিজরি (৬৩৯ খ্রি.) আমওয়াস প্লেগ",
    "summaryBn": "নবী করীম (সা.) যাঁর ব্যাপারে ঘোষণা করেছিলেন \"প্রত্যেক উম্মতের একজন পরম বিশ্বস্ত মানুষ থাকে, আর আমার এই উম্মতের বিশ্বস্ত মানুষ হলো আবু উবাইদা\"; ইয়ারমুক ও সিরিয়া বিজয়ের মহান সর্বাধিনায়ক।",
    "detailedBiographyBn": "হযরত আবু উবাইদা আমের ইবনে আব্দুল্লাহ ইবনুল জাররাহ (রা.) ছিলেন কুরাইশ বংশের বনু হারিস গোত্রের এক অসামান্য বিনম্র, দীর্ঘদেহী ও আত্মত্যাগী সাহাবি। তিনি আবু বকর (রা.)-এর ইসলাম গ্রহণের পরদিনই ইসলাম গ্রহণ করেন।\n\nবদর যুদ্ধে তাঁর কাফের পিতা আব্দুল্লাহ ইবনুল জাররাহ বারবার আবু উবাইদাকে হত্যা করার জন্য উদ্যত হচ্ছিল। আবু উবাইদা পিতাকে এড়িয়ে যাচ্ছিলেন, কিন্তু পিতা যখন মুসলিমদের ওপর আক্রমণ বন্ধ না করে আবু উবাইদার পথ পুরোপুরি রোধ করে ফেলল, তখন আবু উবাইদা আল্লাহর তাওহীদের মর্যাদায় বাধ্য হয়ে পিতাকে হত্যা করেন। এই নিদারুণ আত্মত্যাগের স্মরণে কুরআনের সূরা মুজাদালার ২২ নম্বর আয়াত নাজিল হয়।\n\nউহুদের যুদ্ধে যখন রাসুলুল্লাহ (সা.)-এর লোহার শিরস্ত্রাণের দুটি কড়া ভেঙে গাল মোবারকে বিঁধে যায়, তখন আবু উবাইদা হাত দিয়ে না টেনে নিজের সামনের দাঁত দিয়ে কামড়ে ধরে পরম সাবধানে সেই কড়া দুটি টেনে বের করেন। এতে তাঁর সামনের দুটি দাঁত ভেঙে যায়, কিন্তু রাসুল (সা.)-এর কষ্ট উপশম হয়। দাঁত ভাঙার পরও তাঁর চেহারা অত্যন্ত আকর্ষণীয় হয়ে ওঠে। উমর (রা.)-এর খেলাফতকালে তিনি সিরিয়া অভিযানের প্রধান সেনাপতি হন। তিনি দামেশক, হিমস, আন্তাকিয়া ও জেরুসালেম বিজয়ে কেন্দ্রীয় ভূমিকা পালন করেন। খলিফা উমর একবার তাঁর তাঁবুতে গিয়ে দেখেন সিরিয়ার প্রধান সেনাপতির ঘরে শুধু একটি তলোয়ার, একটি ঢাল আর মাটির পাত্র ছাড়া কিছুই নেই; এ দেখে উমর (রা.) অঝোরে কেঁদেছিলেন।",
    "islamAcceptanceBn": "ইসলামের একেবারে প্রথম দিনেই আবু বকর (রা.)-এর সাথে রাসুল (সা.)-এর দরবারে হাজির হয়ে উসমান ইবনে মাজউন ও আব্দুর রহমান ইবনে আওফের সাথে ইসলাম গ্রহণ করেন।",
