    "birthAndDeathBn": "জন্ম: ৫৬৭ খ্রি. মক্কা | শাহাদাত: ৩ হিজরি (উহুদের যুদ্ধ, মার্চ ৬২৫ খ্রি.)",
    "summaryBn": "মক্কার সবচেয়ে নির্ভীক ও প্রভাবশালী শিকারি যোদ্ধা, রাসুলুল্লাহ (সা.)-এর আপন বীর চাচা ও দুধভাই; যাঁর ইসলাম গ্রহণে মক্কার কাফেরদের অহংকার চূর্ণ হয়ে যায় এবং যিনি উহুদের প্রান্তরে বুক চিতিয়ে লড়াই করে শহীদদের সর্দার হিসেবে অমরত্ব লাভ করেন।",
    "detailedBiographyBn": "হযরত হামজা (রা.) ছিলেন রাসুলুল্লাহ (সা.)-এর পিতা আব্দুল্লাহর ছোট ভাই এবং সুয়াইবা দাসীর দুধপানের কারণে রাসুলের দুধভাইও ছিলেন। তিনি ছিলেন আরবের দুর্ধর্ষ শিকারি ও অপরাজেয় তীরন্দাজ।\n\nএকদিন শিকার থেকে ফিরে জানতে পারলেন আবু জাহেল সাফা পাহাড়ে রাসুলুল্লাহ (সা.)-কে কদর্য ভাষায় গালিগালাজ ও শারীরিকভাবে অপমান করেছে। হামজা রাগে ক্ষিপ্ত হয়ে ধনুক হাতে কাবা চত্বরে ছুটে যান। সেখানে আবু জাহেল কুরাইশ নেতাদের সাথে বসে ছিল। হামজা কিছু না বলেই নিজের ভারী ধনুক তুলে আবু জাহেলের মাথায় এমন জোরে আঘাত করলেন যে তার মাথা ফেটে রক্ত ঝরতে লাগল। হামজা বজ্রকণ্ঠে বললেন: \"তুই মুহাম্মদকে গালি দিয়েছিস? জেনে রাখিস, আমিও মুহাম্মদের দ্বীন গ্রহণ করেছি! সাহস থাকে তো এবার আমার ওপর হাত তোল!\" আবু জাহেল ও কুরাইশরা ভয়ে নিশ্চুপ হয়ে যায়। বাড়ি ফিরে তিনি একনিষ্ঠভাবে ইসলাম গ্রহণ করেন।\n\nবদর যুদ্ধে তিনি দুই হাতে দুটি তলোয়ার নিয়ে লড়াই করেছিলেন এবং কাফেরদের শীর্ষ নেতা শায়বা ইবনে রাবিয়াসহ বহু কুখ্যাত বীরকে হত্যা করেন। ৩ হিজরির উহুদ যুদ্ধে তিনি একাই শত্রুবাহিনীর ব্যূহ ছিন্নভিন্ন করে ৩১ জন মুশরিক যোদ্ধাকে হত্যা করেন। কুরাইশরা সরাসরি তাঁর সামনে দাঁড়াতে সাহস না পেয়ে হাবশি দাস ওয়াহশিকে তাঁর পেছনে গুপ্তঘাতক হিসেবে নিযুক্ত করে। পাথরের আড়াল থেকে ওয়াহশির বিষাক্ত বর্শার আঘাতে এই মহান সিংহ শহীদ হন। যুদ্ধশেষে আবু সুফিয়ানের স্ত্রী হিন্দ হামজার বুক চিরে কলিজা বের করে চিবিয়েছিল। তাঁর খণ্ডিত দেহ দেখে রাসুল (সা.) জীবনে সবচেয়ে বেশি কেঁদেছিলেন।",
    "islamAcceptanceBn": "নবুওয়াতের ষষ্ঠ বছরে ভাতিজা মুহাম্মদ (সা.)-এর ওপর আবু জাহেলের অমানবিক অপমানের খবর শুনে ধনুক নিয়ে আবু জাহেলের মাথা ফাটিয়ে দিয়ে প্রকাশ্যে ইসলাম ঘোষণা করেন এবং পরবর্তীতে পূর্ণ আত্মনিবেদন করেন।",
    "keyVirtuesBn": [
      "রাসুলুল্লাহ (সা.) কর্তৃক \"সাইয়্যিদুশ শুহাদা\" (কেয়ামত পর্যন্ত সমস্ত শহীদের সর্দার) উপাধিতে ভূষিত।",
      "আল্লাহ ও তাঁর রাসুলের সিংহ (আসাদুল্লাহ ওয়া আসাদু রাসুলিহি) হিসেবে আসমানে ও জমিনে ঘোষিত।",
      "বদরের যুদ্ধে উভয় হাতে তলোয়ার চালিয়ে কাফেরদের শিরোমণিদের একাই ভূপাতিত করেন।",
      "উহুদ যুদ্ধে তাঁর জানাজায় রাসুল (সা.) ৭০ বার জানাজার তাকবির দিয়ে সালাত আদায় করেছিলেন।"
    ],
    "emotionalStoriesBn": [
      {
        "title": "উহুদের রক্তে রাঙানো হামজার নিথর দেহ ও রাসুল (সা.)-এর বুকফাটা কান্না",
        "story": "উহুদের যুদ্ধ শেষে রাসুলুল্লাহ (সা.) ময়দানে হামজার লাশের খোঁজে বের হলেন। প্রান্তরের এক কোণে গিয়ে দেখলেন তাঁর বীর চাচা হামজার নাক-কান কাটা এবং বুক চেরা, কলিজা বের করা। এই মর্মান্তিক দৃশ্য দেখে রহমাতুল্লিল আলামিন রাসুল (সা.) নিজের আবেগকে ধরে রাখতে পারেননি; তিনি ফুঁপিয়ে ফুঁপিয়ে এমনভাবে কাঁদলেন যা সাহাবিরা আগে কখনো দেখেননি। রাসুল (সা.) নিজের চাদর দিয়ে হামজার দেহ ঢাকতে গেলেন। কিন্তু চাদরটি এত ছোট ছিল যে মাথা ঢাকলে পা বের হয়ে যেত, আর পা ঢাকলে মাথা উন্মুক্ত হয়ে পড়ত। রাসুল (সা.) চোখের পানি মুছতে মুছতে বললেন: \"মাথা চাদর দিয়ে ঢেকে দাও এবং পায়ের ওপর ইযখির ঘাস বিছিয়ে দাও।\" জিবরাইল (আ.) এসে জানালেন: \"হে আল্লাহর রাসুল! সাত আসমানের ফেরেশতাদের মাঝে লেখা হয়েছে—হামজা ইবনে আব্দুল মুত্তালিব আল্লাহ ও তাঁর রাসুলের সিংহ!\""
      }
    ],
