        "textBn": "কেয়ামতের দিন শহীদদের সর্দার হবেন হামজা ইবনে আব্দুল মুত্তালিব এবং এমন ব্যক্তি যে অত্যাচারী শাসকের সামনে দাঁড়িয়ে সত্য কথা বলে নিহত হয়।",
