    "deathOrMartyrdomBn": "৩ হিজরির শাওয়াল মাসে উহুদের প্রান্তরে ওয়াহশির বর্শার আঘাতে শাহাদাত বরণ করেন। উহুদের পবিত্র মাটিতে তাঁর ভাগিনা আব্দুল্লাহ ইবনে জাহশের সাথে একই কবরে তাঁকে সমাহিত করা হয়।",
