        "title": "ছেঁড়া কম্বলে কাফন ও রাসুল (সা.)-এর ক্রন্দন",
        "story": "উহুদের যুদ্ধের পর মুসআবের নিথর দেহ পড়ে ছিল বালিতে। কাফন দেওয়ার জন্য তাঁর পরিহিত একটিমাত্র ছোট পশমি চাদর ছাড়া আর কিছুই পাওয়া গেল না। সেই চাদর দিয়ে মাথা ঢাকলে পা উন্মুক্ত হয়ে পড়ত, আর পা ঢাকলে মাথা বের হয়ে যেত। রাসুলুল্লাহ (সা.) এই দৃশ্য দেখে দুচোখের অশ্রু ধরে রাখতে পারলেন না। তিনি কান্নাজড়িত কণ্ঠে বললেন: \"আমি মক্কায় এমন কাউকে দেখিনি যে মুসআবের চেয়ে বেশি সুন্দর পোশাক পরত এবং যার চেয়ে বেশি প্রাচুর্য ছিল। আর আজ দেখো, মুসআব এমন অবস্থায় শুয়ে আছে যে তার মাথা ঢাকলে পা বের হয়ে যায়!\" রাসুল (সা.) নির্দেশ দিলেন: \"চাদরটি দিয়ে মাথা ঢেকে দাও এবং পায়ের ওপর সুগন্ধি ইযখির ঘাস বিছিয়ে দাও।\" এরপর রাসুল সূরা আহযাবের সেই আয়াত তিলাওয়াত করলেন: \"মুমিনদের মধ্যে কিছু পুরুষ এমন রয়েছে যারা আল্লাহর সাথে করা অঙ্গীকার পূর্ণ করেছে।\""
