    "summaryBn": "পারস্যের অগ্নিপূজারীর গৃহ ছেড়ে সত্য দ্বীনের সন্ধানে বছরের পর বছর দেশ থেকে দেশান্তরে ঘুরে দাসত্বের শৃঙ্খল পেরিয়ে রাসুলুল্লাহ (সা.)-এর কোলে আশ্রয় নেওয়া মহাসাধক; খন্দক যুদ্ধে যাঁর খনন কৌশলে মদিনা রক্ষা পায়।",
    "detailedBiographyBn": "হযরত সালমান ফারসি (রা.) ছিলেন পারস্যের ইস্পাহানের এক সম্ভ্রান্ত অগ্নিপূজক পুরোহিতের সন্তান। পিতার অগাধ ধনসম্পদ থাকা সত্ত্বেও তাঁর হৃদয় একত্ববাদের সন্ধানে ব্যাকুল ছিল। তিনি বাড়ি থেকে পালিয়ে সিরিয়ায় গিয়ে খ্রিস্টান সন্ন্যাসীদের সান্নিধ্যে বছরের পর বছর সত্যান্বেষণ করেন।\n\nমৃত্যুর পূর্বে তাঁর শেষ শিক্ষক তাঁকে বলেছিলেন: \"আরব ভূমিতে শেষ নবির আবির্ভাব ঘটতে চলেছে, যিনি উপহার গ্রহণ করবেন কিন্তু সদকা খাবেন না এবং তাঁর দুই কাঁধের মাঝে নবুওয়াতের মোহর থাকবে।\" এই লক্ষণের খোঁজে তিনি মদিনার উদ্দেশ্যে এক আরব কাফেলার সাথে যাত্রা করলে কাফেলার লোকেরা বিশ্বাসঘাতকতা করে তাঁকে এক ইহুদির কাছে দাস হিসেবে বিক্রি করে দেয়। তিনি খেজুর বাগানে অমানুষিক দাসত্বের জীবন যাপন করতে থাকেন।\n\nরাসুল (সা.) মদিনায় হিজরত করলে সালমান তিনটি লক্ষণ প্রত্যক্ষ করে রাসুলের পায়ে লুটিয়ে পড়ে ইসলাম গ্রহণ করেন। সাহাবিদের আর্থিক সহায়তায় ৩০০ খেজুর গাছ রোপণ ও নির্দিষ্ট অর্থ পরিশোধ করে তিনি দাসত্ব থেকে মুক্তি পান। ৫ হিজরিতে খন্দকের যুদ্ধে যখন ১০ হাজার কাফেরের সম্মিলিত বাহিনী মদিনা ধ্বংস করতে এলো, তখন সালমান পারস্যের সামরিক কৌশল অনুযায়ী মদিনার অরক্ষিত অংশে গভীর পরিখা (খন্দক) খননের পরামর্শ দেন। রাসুল (সা.) তা বাস্তবায়ন করে মদিনাকে ঐতিহাসিক বিজয় এনে দেন। রাসুল (সা.) তাঁকে এতো ভালোবাসতেন যে ঘোষণা করেছিলেন: \"সালমান আমাদের আহলে বাইতের অন্তর্ভুক্ত!\" খলিফা উমরের সময়ে তিনি মাদায়েনের গভর্নর হন, কিন্তু গভর্নর হয়েও নিজ হাতে খেজুর পাতার পাটি বুনে জীবিকা নির্বাহ করতেন।",
    "islamAcceptanceBn": "পারস্যের রাজকীয় জীবন ছেড়ে সত্যের সন্ধানে সিরিয়া, মসুল ও নসিবিন ঘুরে দাস হিসেবে মদিনায় বিক্রি হন। এরপর শেষ নবির তিনটি সুস্পষ্ট লক্ষণ মিলিয়ে দেখে রাসুল (সা.)-এর হাতে ইসলাম গ্রহণ করেন।",
