    "emotionalStoriesBn": [
      {
        "title": "মরুভূমির নির্যাতন ও রাসুল (সা.)-এর অশ্রুসজল সান্ত্বনা",
        "story": "মক্কার উত্তপ্ত বাথহা প্রান্তরে ইয়াসির, সুমাইয়া ও আম্মারকে লোহার পোশাকে রোদে দাঁড় করিয়ে চাবুক মারা হচ্ছিল। রাসুলুল্লাহ (সা.) পাশ দিয়ে যাওয়ার সময় এই বীভৎস দৃশ্য দেখে চোখের পানি সংবরণ করতে পারেননি। তিনি তখন তাঁদের বাঁচানোর কোনো পার্থিব শক্তি রাখতেন না। তিনি অশ্রুসজল কণ্ঠে হাত তুলে বলেছিলেন: \"হে ইয়াসিরের পরিবার! ধৈর্য ধারণ করো! নিশ্চয়ই তোমাদের জন্য আল্লাহর ওয়াদাকৃত জান্নাত নির্ধারিত রয়েছে! হে আল্লাহ! ইয়াসিরের পরিবারকে ক্ষমা করুন এবং তাদের কবুল করে নিন!\""
      }
    ],
