    "deathOrMartyrdomBn": "সুমাইয়া (রা.) আবু জাহেলের বর্শার আঘাতে মক্কায় প্রথম শহীদ হন। আম্মার (রা.) ৩৭ হিজরিতে সিফফিনের যুদ্ধে এক চুমুক দুধ পান করে রাসুলের ভবিষ্যদ্বাণী স্মরণ করে বীরদর্পে লড়াই করে শহীদ হন।",
