    "summaryBn": "মক্কার কামারশালার নিগৃহীত দাস সাহাবি, যাঁর নগ্ন পিঠের ওপর জ্বলন্ত কয়লা বিছিয়ে দেওয়া হতো এবং তাঁর পিঠের গলে যাওয়া চর্বি ও রক্তে সেই অঙ্গার নিভে যেত; যিনি ফাতিমা বিনতে খাত্তাবকে গোপনে কুরআন শিক্ষা দিতেন।",
    "detailedBiographyBn": "হযরত খাব্বাব ইবনুল অরাত (রা.) ছিলেন জাহেলি যুগে অপহৃত হয়ে মক্কায় উম্মে আনমার নামের এক কুরাইশ মহিলার কাছে দাস হিসেবে বিক্রি হওয়া তরুণ। তিনি ছিলেন দক্ষ কামার এবং তরবারি তৈরি করতেন।\n\nইসলামের একেবারেই সূচনাপর্বে ষষ্ঠ ব্যক্তি হিসেবে তিনি ইসলাম গ্রহণ করেন। তাঁর ইসলাম গ্রহণের কথা জানতে পেরে উম্মে আনমার ও কুরাইশ কাফেররা তাঁর ওপর পৈশাচিক নির্যাতন চালায়। চুলার জ্বলন্ত কয়লা মাটির ওপর বিছিয়ে খাব্বাবকে নগ্ন পিঠে তার ওপর শুইয়ে দেওয়া হতো এবং এক ব্যক্তি তার বুকের ওপর পা দিয়ে দাঁড়িয়ে থাকত যাতে তিনি নড়তে না পারেন। পিঠের চামড়া পুড়ে গলে যাওয়া চর্বির রসে কয়লাগুলো একসময় নিভে যেত।\n\nখাব্বাব ছিলেন কুরআন শিক্ষায় অগ্রণী। তিনি উমর (রা.)-এর বোন ফাতিমা ও ভগ্নিপতি সাঈদকে গোপনে সূরা ত্বা-হা শেখাচ্ছিলেন, যেখান থেকে পরবর্তীতে উমরের ইসলাম গ্রহণের ঘটনা ঘটে। তিনি বদর, উহুদসহ সকল যুদ্ধে অংশ নেন। জীবনের শেষ ভাগে যখন খলিফা উমর (রা.) তাঁকে সেই দিনের কথা জিজ্ঞাসা করেছিলেন, খাব্বাব নিজের পিঠ উন্মুক্ত করে দেখান। উমর তা দেখে শিউরে উঠে কেঁদে ফেলে বলেছিলেন: \"আমি আজ পর্যন্ত মানুষের পিঠে এমন বীভৎস ক্ষতচিহ্ন দেখিনি!\" কুফায় তিনি প্রথম ব্যক্তি যাঁর অসিয়ত অনুযায়ী শহরের বাইরে খোলা প্রান্তরে কবর দেওয়া হয়।",
    "islamAcceptanceBn": "ইসলামের প্রথম পাঁচ-ছয়জনের একজন হিসেবে অত্যন্ত গোপনে রাসুল (সা.)-এর হাতে ইসলাম গ্রহণ করেন। এরপর উন্মুক্তভাবে তাওহীদ প্রকাশ করায় মক্কার মুশরিকরা তাঁর ওপর নারকীয় নির্যাতন চালায়।",
