        "story": "একদিন কাফেরদের নির্মম নির্যাতনে জর্জরিত হয়ে খাব্বাব (রা.) কাবার ছায়ায় চাদরে হেলান দিয়ে বসা রাসুলুল্লাহ (সা.)-এর দরবারে উপস্থিত হলেন। নিজের রক্তাক্ত ক্ষতবিক্ষত শরীর দেখিয়ে কাতর কণ্ঠে বললেন: \"হে আল্লাহর রাসুল! আপনি কি আমাদের জন্য আল্লাহর কাছে সাহায্য চাইবেন না? আপনি কি আমাদের জন্য দোয়া করবেন না?\" রাসুল (সা.) সোজা হয়ে বসলেন, তাঁর পবিত্র চেহারা মোবারক রক্তিম হয়ে উঠল। তিনি বললেন: \"তোমাদের পূর্ববর্তী উম্মতদের মধ্যে এমন হতো যে মানুষের শরীর মাটিতে গর্ত করে পুঁতে মাথার ওপর করাত চালিয়ে দ্বিখণ্ডিত করে দেওয়া হতো, লোহার চিরুনি দিয়ে হাড় থেকে গোশত আলাদা করা হতো; তবুও তারা দ্বীন ছাড়ত না! আল্লাহর শপথ! আল্লাহ এই দ্বীনকে এমন পূর্ণতা দান করবেন যে একজন পথিক সানআ থেকে হাযরামাউত পর্যন্ত একাকী নির্ভয়ে সফর করবে, আল্লাহ ছাড়া সে আর কাউকে ভয় পাবে না! কিন্তু তোমরা তাড়াহুড়া করছ।\" খাব্বাব এই বাণীতে নতুন জীবন পেলেন।"
