    "birthAndDeathBn": "জন্ম: ৫৮৭ খ্রি. মেসোপটেমিয়া | ওফাত: ৩৮ হিজরি মদিনা (৭০ বছর)",
    "summaryBn": "রোমানদের দাসত্ব থেকে পালিয়ে মক্কায় এসে সফল ব্যবসায়ী হওয়া সাহাবি; যিনি মদিনায় হিজরতের সময় রাসুল (সা.)-এর ভালোবাসায় নিজের জীবনের সমস্ত অর্জিত ধনসম্পদ কাফেরদের হাতে তুলে দিয়ে নিঃস্ব হয়ে হিজরত করেছিলেন।",
    "detailedBiographyBn": "হযরত সুহাইব ইবনে সিনান আর-রূমি (রা.) ছিলেন বংশগতভাবে আরব, কিন্তু শৈশবে রোমান জলদস্যুরা তাঁকে অপহরণ করে রোমান সাম্রাজ্যে দাস হিসেবে বিক্রি করে দেয়। দীর্ঘদিন সেখানে থাকায় তাঁর মুখের ভাষা রোমানদের মতো হয়ে যায় এবং তিনি ‘সুহাইব আর-রূমি’ নামে পরিচিত হন। পরবর্তীতে এক আরব বণিক তাঁকে কিনে মক্কায় নিয়ে আসেন এবং একসময় তিনি স্বাধীন হন।\n\nসুহাইব ছিলেন অত্যন্ত বুদ্ধিমান ও পরিশ্রমী। মক্কায় ব্যবসা করে তিনি বিপুল ধনসম্পদ ও স্বর্ণের মালিক হন। তিনি ও আম্মার ইবনে ইয়াসির একই দিনে দারুল আরকামে প্রবেশ করে ইসলাম গ্রহণ করেন। ইসলাম গ্রহণের পর কুরাইশরা তাঁর ওপর নির্মম নির্যাতন শুরু করে কারণ মক্কায় তাঁর কোনো গোত্রীয় নিরাপত্তা ছিল না।\n\nরাসুল (সা.) যখন মদিনায় হিজরত করলেন, সুহাইবও নিজের যাবতীয় ধনসম্পদ নিয়ে গোপনে রওনা হলেন। কিন্তু কুরাইশদের একটি অশ্বারোহী দল তাঁকে তাড়া করে ঘিরে ফেলল। সুহাইব ঘোড়া থেকে নেমে তীরের থলে হাতে নিয়ে বললেন: \"হে কুরাইশরা! তোমরা জানো আমি তীরন্দাজিতে কেমন! আমার থলের শেষ তীরটি থাকা পর্যন্ত তোমরা কেউ আমার কাছে আসতে পারবে না। তারপর তলোয়ার চালাব। তবে তোমরা যদি আমার সমস্ত স্বর্ণ ও সম্পদের ঠিকানা চাও, আমি তা দিয়ে দেব, কিন্তু আমাকে আমার নবির কাছে যেতে দাও!\" লোভী কাফেররা রাজি হলো। সুহাইব নিজের জীবনের সমস্ত উপার্জিত সম্পদ কাফেরদের হাতে তুলে দিয়ে খালি হাতে পায়ে হেঁটে মদিনার কুবা পল্লীতে রাসুল (সা.)-এর দরবারে পৌঁছেন। রাসুল (সা.) দূর থেকে তাঁকে দেখেই আনন্দের সাথে চিৎকার করে বললেন: \"হে আবু ইয়াহইয়া! তোমার ব্যবসা লাভজনক হয়েছে! তোমার সওদা সফল হয়েছে!\"",
    "islamAcceptanceBn": "আম্মার ইবনে ইয়াসিরের সাথে একই সাথে দারুল আরকামের দরজায় মিলিত হয়ে রাসুল (সা.)-এর খেদমতে হাজির হন এবং সানন্দে ইসলাম কবুল করেন।",
