    "summaryBn": "আলী (রা.)-এর আপন ভাই এবং চেহারায় ও চরিত্রে রাসুলুল্লাহ (সা.)-এর সাথে সর্বাধিক সাদৃশ্যপূর্ণ সাহাবি; যিনি হাবশার বাদশাহ নাজ্জাশির দরবারে ইসলামের পক্ষে নির্ভীক বক্তব্য দিয়ে মুসলিমদের রক্ষা করেন এবং মুতার যুদ্ধে দুই হাত কেটে ফেলার পর শহীদ হন।",
    "detailedBiographyBn": "হযরত জাফর ইবনে আবি তালেব (রা.) ছিলেন রাসুলুল্লাহ (সা.)-এর আপন চাচাত ভাই এবং আলী (রা.)-এর চেয়ে ১০ বছরের বড় ভাই। তিনি ও তাঁর স্ত্রী আসমা বিনতে উমাইস প্রাথমিক পর্যায়েই ইসলাম গ্রহণ করেন।\n\nমক্কার অসহ্য নির্যাতন থেকে বাঁচতে রাসুল (সা.) সাহাবিদের হাবশায় হিজরতের নির্দেশ দিলে জাফর ছিলেন সেই কাফেলার প্রধান নেতা ও মুখপাত্র। কুরাইশরা عمرو ইবনুল আসকে মূল্যবান উপহারসহ বাদশাহ নাজ্জাশির দরবারে পাঠিয়েছিল যাতে মুসলিমদের ফেরত পাঠানো হয়। বাদশাহ নাজ্জাশির দরবারে জাফর (রা.) দাঁড়িয়ে এমন এক তেজস্বী ও সত্যনিষ্ঠ ভাষণ দেন এবং সূরা মারিয়ামের আয়াত তিলাওয়াত করেন যে বাদশাহ নাজ্জাশি ও তাঁর সভাসদরা কান্নায় দাড়ি ভিজিয়ে ফেলেন। নাজ্জাশি ঘোষণা করেন: \"যাও! তোমরা আমার দেশে সম্পূর্ণ নিরাপদ।\"\n\n৭ হিজরিতে খায়বার বিজয়ের দিন জাফর সপরিবারে হাবশা থেকে মদিনায় ফিরে আসেন। রাসুল (সা.) জাফরকে দেখে আনন্দে আত্মহারা হয়ে তাঁর কপালে চুম্বন করেন এবং বলেন: \"আমি জানি না আমি কিসে বেশি আনন্দিত—খায়বার বিজয়ে নাকি জাফরের আগমনে!\" ৮ হিজরিতে মুতার যুদ্ধে রোমানদের এক লক্ষাধিক সৈন্যের বিরুদ্ধে তিন হাজার মুসলিম সেনাদলের দ্বিতীয় সেনাপতি ছিলেন জাফর। প্রথম সেনাপতি যায়েদ শহীদ হলে জাফর ইসলামের পতাকা হাতে তুলে নেন। রোমান সৈন্যরা তাঁর ডান হাত কেটে ফেললে তিনি বাম হাতে পতাকা ধরেন। এরপর বাম হাতও কেটে ফেলা হলে তিনি কর্তিত দুই বাহুর অংশ দিয়ে বুকে পতাকা চেপে ধরেন যতক্ষণ না বর্শার আঘাতে শহীদ হন। রাসুল (সা.) মদিনায় বসে ওহীর মাধ্যমে এই দৃশ্য দেখে সাহাবিদের বলেন: \"আল্লাহ তাআলা জাফরের কর্তিত দুই হাতের পরিবর্তে জান্নাতে দুটি সবুজ ডানা দান করেছেন, যা দিয়ে সে ফেরেশতাদের সাথে উড়ে বেড়ায়!\"",
    "islamAcceptanceBn": "আবু বকর (রা.)-এর মাধ্যমে ভাই আলী ও স্ত্রী আসমাসহ প্রাথমিক দিনগুলোতেই ইসলাম গ্রহণ করেন।",
    "keyVirtuesBn": [
      "রাসুলুল্লাহ (সা.) বলতেন: \"হে জাফর! তুমি চেহারায় ও চরিত্রে আমার সবচেয়ে বেশি সদৃশ!\"",
      "হাবশার খ্রিস্টান বাদশাহ নাজ্জাশির দরবারে অতুলনীয় প্রজ্ঞা ও সাহসিকতার সাথে ইসলামের সত্যতা তুলে ধরা।",
      "মুতার যুদ্ধে ইসলামের পতাকাকে মাটির সাথে না মিশতে দিয়ে দুই হাত হারিয়ে শাহাদাত বরণ।",
      "জান্নাতে সবুজ ডানা নিয়ে ফেরেশতাদের সাথে উড়ে বেড়ানোর দুর্লভ ঐশী মর্যাদা লাভ।"
    ],
    "emotionalStoriesBn": [
      {
        "title": "জাফরের শাহাদাত ও এতিম সন্তানদের মাথায় রাসুল (সা.)-এর স্নেহের পরশ",
        "story": "মুতার প্রান্তরে জাফরের শাহাদাতের সংবাদ যখন মদিনায় পৌঁছাল, রাসুলুল্লাহ (সা.) গভীর শোকে মূহ্যমান হয়ে জাফরের ঘরে ছুটে গেলেন। স্ত্রী আসমা বিনতে উমাইস তখন বাচ্চাদের গোসল করিয়ে পরিষ্কার কাপড় পরিয়ে রুটি বানাচ্ছিলেন। রাসুল (সা.) এসে বললেন: \"আসমা! জাফরের সন্তানদের আমার কাছে নিয়ে এসো।\" সন্তানরা আনন্দে ছুটে এসে রাসুলকে জড়িয়ে ধরল। রাসুল (সা.) তাদের বুকে জড়িয়ে ধরে এমনভাবে ফুঁপিয়ে কাঁদতে লাগলেন যে তাঁর দাড়ি মোবারক অশ্রুতে ভিজে বাচ্চাদের মাথায় টপকে পড়তে লাগল। আসমা আতঙ্কিত হয়ে বললেন: \"হে আল্লাহর রাসুল! আমার মা-বাবা আপনার ওপর কোরবান হোক, আপনি কাঁদছেন কেন? জাফরের কি কোনো দুঃসংবাদ এসেছে?\" রাসুল (সা.) কান্নাজড়িত কণ্ঠে বললেন: \"হ্যাঁ আসমা! জাফর আজ আল্লাহর রাস্তায় শহীদ হয়ে গেছে!\" এরপর রাসুল সাহাবিদের বললেন: \"তোমরা জাফরের পরিবারের জন্য খাবারের ব্যবস্থা করো, কারণ আজ তাদের ওপর এমন শোক এসেছে যাতে তারা রান্না করার অবস্থায় নেই।\""
      }
    ],
