    "summaryBn": "হযরত উমর (রা.)-এর চেয়েও বয়সে বড় ও প্রিয় ভাই, যিনি ইসলাম গ্রহণে ও শাহাদাত বরণে উমরের অগ্রগামী ছিলেন; যাঁর শাহাদাতে উমর (রা.) বলেছিলেন: \"পূবালী বাতাস বইলেই আমি যায়েদের সুবাস পাই!\"",
    "detailedBiographyBn": "হযরত যায়েদ ইবনুল খাত্তাব (রা.) ছিলেন খাত্তাবের জ্যেষ্ঠ পুত্র এবং উমর ফারুক (রা.)-এর আপন বড় ভাই। তিনি উমরের অনেক আগেই ইসলাম গ্রহণ করেন এবং প্রারম্ভিক মুহাজিরদের কাতারে শামিল হন।\n\nবদর ও উহুদ যুদ্ধে তিনি অসাধারণ বীরত্ব দেখান। উহুদের যুদ্ধে উমর (রা.) ভাইয়ের জীবন নিয়ে চিন্তিত হয়ে নিজের মজবুত লোহার বর্মটি যায়েদকে পরতে দেন। কিন্তু কিছুক্ষণ পর উমর দেখলেন যায়েদ বর্মটি খুলে ফেলেছেন। উমর কারণ জিজ্ঞাসা করলে যায়েদ হেসে বললেন: \"হে ভাই! তুমি যেভাবে শাহাদাত কামনা করো, আমিও তো তেমনি শাহাদাত অন্বেষণ করছি! আমি কেন বর্মের আড়ালে বাঁচব?\"\n\n১২ হিজরিতে ভণ্ড নবি মুসায়লামা কাজ্জাবের বিরুদ্ধে ইয়ামামার রক্তক্ষয়ী যুদ্ধে যায়েদ (রা.) মুসলিম বাহিনীর প্রধান পতাকাবাহী ছিলেন। যুদ্ধের এক পর্যায়ে যখন মুসলিম বাহিনী বিপর্যস্ত হয়ে ছত্রভঙ্গ হওয়ার উপক্রম হলো, তখন যায়েদ একটি টিলার ওপর উঠে বজ্রকণ্ঠে গর্জন করে উঠলেন: \"হে মুসলিমরা! দাঁতে দাঁত চেপে লড়াই করো! আল্লাহর কসম, যতক্ষণ না আমরা এই শত্রুদের পরাস্ত করব অথবা আমি আল্লাহর সাথে সাক্ষাৎ করব, ততক্ষণ আমি আর কোনো কথা বলব না!\" এরপর তিনি পতাকা উঁচু করে ধরে শত্রুসেনার ভেতর সিংহবিক্রমে প্রবেশ করেন এবং মুসায়লামার প্রধান সেনাপতি রাজ্জাল ইবনে উনফুয়াকে হত্যা করেন। কিছুক্ষণ পরেই তিনি বীরের মতো শাহাদাতের অমীয় সুধা পান করেন।",
