    "nameAr": "عبد الله بن جحش رضي الله عنه",
    "titleBn": "আমিরুল মুমিনীন (প্রথম অভিযানের সেনাপতি), আল-মুজদ্দা’ ফিল্লাহ",
    "categoryKey": "pioneers_martyrs",
    "categoryBn": "প্রাথমিক ঈমানদার ও শহীদ (#২০)",
    "birthAndDeathBn": "জন্ম: ৫৮০ খ্রি. মক্কা | শাহাদাত: ৩ হিজরি (উহুদের যুদ্ধ)",
    "summaryBn": "রাসুলুল্লাহ (সা.)-এর ফুফাতো ভাই ও উম্মুল মুমিনীন যায়নাব বিনতে জাহশের ভাই; ইসলামের ইতিহাসে সর্বপ্রথম সারিয়্যাহ (অভিযান)-এর সেনাপতি এবং যিনি উহুদের আগের রাতে অদ্ভুত শাহাদাতের দোয়া করেছিলেন।",
    "detailedBiographyBn": "হযরত আব্দুল্লাহ ইবনে জাহশ (রা.) ছিলেন রাসুলুল্লাহ (সা.)-এর আপন ফুফু উমাইমা বিনতে আব্দুল মুত্তালিবের পুত্র। তিনি দারুল আরকামে ইসলামের সূচনাতেই ইসলাম গ্রহণ করেন। মক্কায় তাঁর পরিবারের সকলেই ইসলাম গ্রহণ করায় তাঁদের পুরো বাড়িটি শূন্য করে তাঁরা সপরিবারে মদিনায় হিজরত করেছিলেন। মক্কায় আবু সুফিয়ান তাঁদের খালি বাড়িটি দখল করে বিক্রি করে দিয়েছিল।\n\nমদিনায় হিজরতের পর ২ হিজরির রজব মাসে রাসুল (সা.) তাঁকে বারোজন সাহাবির একটি বিশেষ সামরিক গোয়েন্দা দলের দায়িত্ব দিয়ে ‘নাখলা’ নামক স্থানে পাঠান। রাসুল (সা.) তাঁকে একটি বন্ধ চিঠি দিয়ে বলেছিলেন দুই দিন পথ চলার পর চিঠিটি খুলতে। সেই চিঠির নির্দেশ অনুযায়ী তিনি কুরাইশদের বাণিজ্য কাফেলার গতিবিধি পর্যবেক্ষণ করেন। ইসলামের ইতিহাসে তিনিই প্রথম ব্যক্তি যাঁকে কোনো সামরিক দলের নেতা হিসেবে সাহাবিরা ‘আমির’ বলে সম্বোধন করেছিলেন।\n\nউহুদ যুদ্ধের আগের রাতে তিনি ও সা’দ ইবনে আবি ওয়াক্কাস একান্তে বসে দোয়া করছিলেন। সা’দ দোয়া করলেন: \"হে আল্লাহ! কাল এমন এক শক্তিশালী কাফেরের মুখোমুখি আমাকে করো, যার সাথে আমি যুদ্ধ করব এবং তাকে হত্যা করব।\" আব্দুল্লাহ বললেন: \"আমিন।\" এরপর আব্দুল্লাহ দোয়া করলেন: \"হে আল্লাহ! কাল ময়দানে আমার সামনে এমন এক হিংস্র ও শক্তিশালী কাফেরকে পাঠাও, যার সাথে আমি প্রচণ্ড যুদ্ধ করব। এরপর সে যেন আমাকে হত্যা করে আমার নাক ও কান কেটে ফেলে! এরপর কেয়ামতের দিন যখন আপনি আমাকে জিজ্ঞাসা করবেন—হে আব্দুল্লাহ! তোমার নাক ও কান কার জন্য কাটা হলো? তখন আমি পরম শান্তিতে বলব—হে আমার রব! একমাত্র আপনার ও আপনার রাসুলের ভালোবাসায় আমার নাক-কান কাটা হয়েছে!\" পরদিন যুদ্ধক্ষেত্রে তাঁর সেই দোয়ার প্রতিটি শব্দ হুবহু বাস্তবায়িত হয়।",
    "islamAcceptanceBn": "দারুল আরকামে সূচনাপর্বেই ইসলাম গ্রহণ করেন এবং পরিবারের সবাইকে নিয়ে পূর্ণ হিজরত করেন।",
