    "summaryBn": "বাসর রাতের প্রথম ভোরে যুদ্ধের রণহুংকার শুনে ফরজ গোসলের সুযোগ না পেয়েই তলোয়ার হাতে উহুদে ছুটে যাওয়া তরুণ বীর; যাঁর শাহাদাতের পর আসমান ও জমিনের মাঝে রূপার থালায় মেঘের পানিতে স্বয়ং ফেরেশতারা গোসল করিয়েছিলেন।",
    "detailedBiographyBn": "হযরত হানজালা ইবনে আবি আমির (রা.) ছিলেন মদিনার আওস গোত্রের এক নিষ্ঠাবান তরুণ সাহাবি। তাঁর পিতা আবু আমির ছিল রাসুল (সা.)-এর ঘোর শত্রু ও মুনাফিকদের সর্দার, যাকে রাসুল 'আবু আমির ফাসেক' বলতেন। কিন্তু পিতার চরম বিরোধিতা সত্ত্বেও হানজালা ছিলেন ইসলামের একনিষ্ঠ মুমিন।\n\nউহুদ যুদ্ধের আগের রাতে মদিনার আব্দুল্লাহ ইবনে উবাইয়ের কন্যা জামিলা (রা.)-এর সাথে তাঁর বিবাহ সম্পন্ন হয়। বাসর রাতের পর ভোরবেলায় যখন তিনি স্ত্রীর সান্নিধ্যে ছিলেন, ঠিক তখনই মদিনার গলিতে রাসুল (সা.)-এর আহ্বানকারীর কণ্ঠ ভেসে এলো: \"হে আল্লাহর অশ্বারোহীরা! প্রস্তুত হও! উহুদের ময়দানে চলো!\"\n\nহানজালা এক মুহূর্তও দেরি করলেন না। ফরজ গোসলের পানি গরম করার মতো সময়টুকুও তিনি নিলেন না, পাছে রাসুল (সা.)-এর ডাক থেকে তিনি পিছিয়ে পড়েন! অপবিত্র শরীরেই তিনি তলোয়ার হাতে নিয়ে পাগলের মতো উহুদের ময়দানে ছুটে যান। সেখানে গিয়ে কাফের সেনাপতি আবু সুফিয়ানের ওপর আক্রমণ চালান এবং তাকে প্রায় পরাস্ত করে ফেলেন। এমন সময় পেছন থেকে শাদ্দাদ ইবনে আসওয়াদ বর্শা মেরে হানজালাকে শহীদ করে। যুদ্ধশেষে রাসুল (সা.) হঠাৎ আকাশপানে তাকিয়ে বললেন: \"আমি দেখতে পাচ্ছি আসমান ও জমিনের মাঝে ফেরেশতারা রূপার পাত্রে মেঘের পানি দিয়ে হানজালাকে গোসল করাচ্ছে!\"",
    "islamAcceptanceBn": "মদিনায় রাসুল (সা.)-এর হিজরতের পরেই কুফরি পিতার বিরুদ্ধে গিয়ে একনিষ্ঠ অন্তরে ইসলাম গ্রহণ করেন।",
