        "story": "উহুদ যুদ্ধ শেষে রাসুল (সা.) বললেন: \"তোমাদের সঙ্গী হানজালাকে ফেরেশতারা গোসল করাচ্ছে, তোমরা তার স্ত্রীর কাছে গিয়ে খবর নাও তো তার কী হয়েছিল!\" সাহাবিরা মদিনায় গিয়ে তাঁর নতুন স্ত্রীকে জিজ্ঞাসা করলেন। স্ত্রী কাঁদলেন এবং বললেন: \"আজ আমাদের বাসর রাত ছিল। ফজরের ঠিক পূর্বে যুদ্ধের ডাক শুনে হানজালা এতটাই ব্যাকুল হয়ে পড়েছিল যে ফরজ গোসল করার সময়টুকুও সে নেয়নি; অপবিত্র অবস্থায় তরবারি নিয়ে দৌড়ে গেছে।\" রাসুল (সা.) এ কথা শুনে বললেন: \"এই কারণেই ফেরেশতারা আকাশ থেকে মেঘের পানি নিয়ে এসে রূপার পাত্রে তাকে গোসল করিয়েছে!\" এরপর সাহাবিরা গিয়ে দেখলেন হানজালার মাথা থেকে সুগন্ধিযুক্ত ফোঁটা ফোঁটা পানি ঝরছে।"
