    "summaryBn": "মদিনার অতি দরিদ্র, কুশ্রী চেহারার ও কুলপরিচয়হীন নিগৃহীত সাহাবি; যাকে সমাজ অবহেলা করত, কিন্তু বিশ্বনবী (সা.) যাঁকে বুকে জড়িয়ে ধরে বলেছিলেন: \"জুলাইবীব আমার থেকে আর আমি জুলাইবীব থেকে!\"",
    "detailedBiographyBn": "হযরত জুলাইবীব (রা.) ছিলেন মদিনার এমন এক সাহাবি যাঁর কোনো বংশপরিচয়, ধনসম্পদ, রূপ-সৌন্দর্য বা প্রভাব-প্রতিপত্তি ছিল না। তিনি ছিলেন বেঁটে, অত্যন্ত শ্যামবর্ণ ও অভাবী। মদিনার সমাজের অনেকে তাঁকে অবজ্ঞার চোখে দেখত। কিন্তু তিনি ছিলেন রাসুলুল্লাহ (সা.)-এর একনিষ্ঠ ভালোবাসায় সিক্ত একজন নিষ্কলুষ হৃদয়ের মুমিন।\n\nএকদিন রাসুলুল্লাহ (সা.) স্নেহভরে তাঁকে বললেন: \"হে জুলাইবীব! তুমি কি বিবাহ করবে না?\" জুলাইবীব স্মিত হেসে বললেন: \"হে আল্লাহর রাসুল! আমাকে কে পাত্র হিসেবে গ্রহণ করবে? আমার তো কোনো ধনদৌলত বা রূপ নেই, আমি তো সমাজে মূল্যহীন!\" রাসুল (সা.) বললেন: \"কিন্তু তুমি আল্লাহর কাছে মোটেও মূল্যহীন নও!\" এরপর রাসুল (সা.) এক সম্ভ্রান্ত আনসারির ঘরে গিয়ে তাঁর সুন্দরী ও রূপবতী কন্যার সাথে জুলাইবীবের বিবাহের প্রস্তাব দেন। পিতা-মাতা কিছুটা দ্বিধায় পড়লেও সেই মুমিন কন্যা বললেন: \"রাসুলুল্লাহ (সা.) যার প্রস্তাব দিয়েছেন তোমরা কি তা ফিরিয়ে দেবে? আল্লাহর শপথ, রাসুল যাকে মনোনীত করেছেন আমি সানন্দে তাকেই বিয়ে করব!\"\n\nবিবাহের মাত্র কিছুদিন পরই রাসুল (সা.)-এর সাথে এক জিহাদে জুলাইবীব অংশ নেন। যুদ্ধ শেষে রাসুল (সা.) সাহাবিদের জিজ্ঞাসা করলেন: \"তোমরা কি কাউকে হারিয়েছ?\" সাহাবিরা বললেন: \"হ্যাঁ, অমুক অমুক শহীদ হয়েছেন।\" রাসুল (সা.) আবার বললেন: \"কিন্তু আমি তো একজনকে খুঁজে পাচ্ছি না! আমার জুলাইবীব কোথায়?\" রাসুল (সা.) নিজে ময়দানে খুঁজতে বের হলেন। প্রান্তরের এক কোণে গিয়ে দেখলেন সাতজন কাফেরের লাশের পাশে জুলাইবীবের রক্তাক্ত নিথর দেহ পড়ে আছে। তিনি একাই সেই সাত কাফেরকে হত্যা করে শহীদ হয়েছেন।",
