    "summaryBn": "মদিনার আনসার যোদ্ধা, যিনি আল্লাহর সাথে অঙ্গীকার করেছিলেন কাফেরের দেহ কখনো স্পর্শ করবেন না এবং কোনো কাফেরকেও নিজের শরীর স্পর্শ করতে দেবেন না; যাঁর শাহাদাতের পর মৌমাছির ঝাঁক পাঠিয়ে আল্লাহ কাফেরদের হাত থেকে যাঁর দেহ সুরক্ষিত রেখেছিলেন।",
    "detailedBiographyBn": "হযরত আসিম ইবনে সাবিত (রা.) ছিলেন মদিনার আওস গোত্রের এক নির্ভীক তীরন্দাজ সাহাবি। তিনি বদর ও উহুদের যুদ্ধে অত্যন্ত বীরত্বের সাথে লড়াই করেন। উহুদের যুদ্ধে তিনি কুরাইশ বংশের সুলাফা বিনতে সাদের দুই পুত্র মুসাফে ও কিলাবকে তীর নিক্ষেপ করে হত্যা করেন। প্রতিশোধে উন্মাদ হয়ে সুলাফা মানত করেছিল যে আসিমের মাথা কেটে নিয়ে এলে সে আসিমের মাথার খুলিতে মদ ঢেলে পান করবে এবং যে আসিমের মাথা এনে দেবে তাকে একশটি উট পুরস্কার দেবে।\n\n৪ হিজরিতে রাসুলুল্লাহ (সা.) আসিম ইবনে সাবিতের নেতৃত্বে দশজন সাহাবির একটি দলকে দ্বীন শিক্ষার জন্য ‘রাজি’ নামক স্থানে পাঠান। কিন্তু সেখানে হুযাইল ও লিহইয়ান গোত্রের দুই শতাধিক সশস্ত্র কাফের বিশ্বাসঘাতকতা করে তাঁদের ঘিরে ফেলে। কাফেররা অভয় দিয়ে আত্মসমর্পণ করতে বললে আসিম বীরদর্পে উত্তর দেন: \"আল্লাহর কসম! আমি কোনো কাফেরের প্রতিশ্রুতির ওপর নির্ভর করে আত্মসমর্পণ করব না!\"\n\nআসিম তলোয়ার হাতে নিয়ে আল্লাহর দরবারে হাত তুলে ফরিয়াদ করলেন: \"হে আল্লাহ! আমি জীবনের সূচনা থেকে আপনার দ্বীনের হেফাজত করেছি, আজ দিনের শেষে আপনি আমার মৃতদেহের হেফাজত করবেন!\" এরপর তিনি বীরবিক্রমে লড়াই করে শহীদ হন। কাফেররা যখন একশ উটের লোভে তাঁর মাথা কাটতে উদ্যত হলো, তখনই এক অলৌকিক মোজেজা ঘটল। চারদিক থেকে লাখ লাখ বিষাক্ত বোলতা ও মৌমাছির ঝাঁক এসে আসিমের পুরো দেহ ঘিরে ফেলল। কাফেরদের কেউ তাঁর কাছে ঘেঁষতে পারল না। তারা ভাবল রাতে মৌমাছি চলে গেলে মাথা কেটে নেব। কিন্তু রাতের বেলা আকাশে প্রচণ্ড ঝড় ও বৃষ্টি নেমে এলো এবং পাহাড়ি ঢল এসে আসিমের পবিত্র দেহকে ভাসিয়ে এক অজানা স্থানে নিয়ে গেল, যার ফলে কাফেররা তাঁর দেহ স্পর্শও করতে পারল না।",
    "islamAcceptanceBn": "আকাবার বাইয়াতের মাধ্যমে প্রাথমিক পর্যায়েই ইসলাম গ্রহণ করেন এবং বদর ও উহুদে তলোয়ার চালান।",
