    "summaryBn": "মক্কার বনু মাখজুম গোত্রের সেই তরুণ সাহাবি, যাঁর সাফা পাহাড়ের পাদদেশের বাড়িটি ছিল ইসলামের ইতিহাসের সর্বপ্রথম শিক্ষাকেন্দ্র ও হেডকোয়ার্টার (দারুল আরকাম); যেখানে বসে উমর (রা.)-সহ ৪০ জন শীর্ষ সাহাবি ইসলামে দীক্ষিত হন।",
    "detailedBiographyBn": "হযরত আল-আরকাম ইবনে আবিল আরকাম (রা.) ছিলেন কুরাইশ বংশের অত্যন্ত প্রভাবশালী বনু মাখজুম শাখার এক দূরদর্শী ও সম্ভ্রান্ত তরুণ। এই গোত্রটি ছিল রাসুলুল্লাহ (সা.)-এর বনু হাশিম গোত্রের ঐতিহাসিক প্রতিদ্বন্দ্বী এবং আবু জাহেল ছিল এই গোত্রের সর্দার।\n\nমাত্র ১৬ বছর বয়সে আবু বকর (রা.)-এর দাওয়াতে আরকাম ইসলাম গ্রহণ করেন। মক্কার সূচনাপর্বে যখন মুসলিমদের ওপর কাফেরদের নজরদারি ও নির্যাতন চরমে পৌঁছাল, তখন আরকাম নিজের সাফা পাহাড়ের পাদদেশের নিরাপদ বাড়িটিকে রাসুল (সা.)-এর জন্য উন্মুক্ত করে দেন। কাফেররা কখনোই কল্পনা করতে পারেনি যে তাদের প্রধান শত্রু আবু জাহেলের নিজ গোত্রের এক তরুণের ঘরেই মুহাম্মদ (সা.) তাঁর কেন্দ্র গড়ে তুলেছেন!\n\nএই ‘দারুল আরকাম’-এই ইসলামের প্রথম চল্লিশজন ঈমানদার গোপনে সালাত আদায় করতেন, অহী শুনতেন এবং দ্বীনের তালিম নিতেন। এই পবিত্র গৃহেই হযরত হামজা (রা.) এবং হযরত উমর ইবনুল খাত্তাব (রা.) ইসলাম গ্রহণ করেন। উমর (রা.)-এর ইসলাম গ্রহণের পর মুসলিমদের সংখ্যা ৪০ পূর্ণ হলে তাঁরা এই বাড়ি থেকেই প্রথম প্রকাশ্যে কাবার দিকে তাকবির দিয়ে মিছিল করে বের হন। হিজরতের পর আরকাম মদিনায় বসবাস করেন এবং বদর ও উহুদসহ সকল যুদ্ধে অংশ নেন। তিনি তাঁর সাফা পাহাড়ের ঐতিহাসিক বাড়িটিকে একটি চিরস্থায়ী ইসলামি ওয়াকফ সম্পত্তি ঘোষণা করেছিলেন।",
    "islamAcceptanceBn": "মাত্র ১৬ বছর বয়সে আরকাম দারুল আরকাম প্রতিষ্ঠার আগেই ইসলাম গ্রহণ করেন এবং নিজের বাড়িটি ইসলামের জন্য ওয়াকফ করে দেন।",
