        "story": "উমর (রা.) যখন তরবারি নিয়ে দারুল আরকামের দরজায় আঘাত করলেন, সাহাবিরা উমরের তলোয়ার দেখে শঙ্কিত হয়ে পড়লেন। কিন্তু হামজা (রা.) বললেন: \"দরজা খুলে দাও! উমর ভালো নিয়তে এলে ভালো, আর খারাপ নিয়তে এলে তার তলোয়ার দিয়েই তার গর্দান ওড়াব!\" রাসুলুল্লাহ (সা.) নিজে এগিয়ে গিয়ে উমরের চাদর ও তলোয়ারের খাপ ধরে সজোরে ঝাঁকুনি দিয়ে বললেন: \"হে খাত্তাবের পুত্র! তুমি কি ততক্ষণ থামবে না যতক্ষণ না আল্লাহ তোমার ওপর ধ্বংস নামিয়ে দেবেন?\" উমর কেঁপে উঠলেন এবং কদমে পড়ে বললেন: \"হে আল্লাহর রাসুল! আমি সাক্ষ্য দিচ্ছি আল্লাহ ছাড়া কোনো মাবুদ নেই এবং আপনি আল্লাহর রাসুল!\" পুরো দারুল আরকাম সাহাবিদের সমস্বরে তাকবিরে প্রকম্পিত হয়ে উঠেছিল।"
