    "titleBn": "সাইফুল্লাহ (আল্লাহর উন্মুক্ত তরবারি), অপরাজিত সেনাপতি",
    "categoryKey": "commanders",
    "categoryBn": "রণাঙ্গনের অকুতোভয় সেনাপতি (#২৫)",
    "birthAndDeathBn": "জন্ম: ৫৯২ খ্রি. মক্কা | ওফাত: ২১ হিজরি হিমস, সিরিয়া (৫৮ বছর)",
    "summaryBn": "সামরিক ইতিহাসের সর্বকালের শ্রেষ্ঠ রণকৌশলী, যিনি জীবনের কোনো একক যুদ্ধেও পরাজিত হননি; মুতার যুদ্ধে যাঁর হাতে ৯টি তরবারি ভেঙেছিল এবং যাঁর নেতৃত্বে পারস্য ও রোমান পরাশক্তি ধূলিসাৎ হয়েছিল।",
    "detailedBiographyBn": "হযরত খালিদ বিন ওয়ালিদ (রা.) ছিলেন কুরাইশ বংশের বনু মাখজুম শাখার বিখ্যাত সেনাপতি ওয়ালিদ ইবনুল মুগিরার পুত্র। সামরিক কৌশল ও অশ্বারোহী পরিচালনায় তিনি ছিলেন আরবের অদ্বিতীয় প্রতিভার অধিকারী। হুদায়বিয়ার সন্ধির পর ৭ হিজরিতে তিনি মদিনায় এসে রাসুলুল্লাহ (সা.)-এর হাতে ইসলাম গ্রহণ করেন। রাসুল (সা.) তাঁর ইসলামে আনন্দিত হয়ে তাঁকে ‘সাইফুল্লাহ’ (আল্লাহর তরবারি) উপাধিতে ভূষিত করেন।\n\n৮ হিজরির মুতার যুদ্ধে তিন হাজার মুসলিম সৈন্য যখন এক লক্ষ রোমান সৈন্যের মুখোমুখি হয়ে তিন প্রধান সেনাপতিকেই হারায়, তখন খালিদ স্বপ্রণোদিত হয়ে নেতৃত্বের হাল ধরেন। একাই ৯টি তলোয়ার ভেঙে তিনি এমন বিস্ময়কর রণকৌশল অবলম্বন করেন যে রোমানরা ভেবেছিল নতুন মুসলিম সৈন্য এসেছে এবং খালিদ সমস্ত মুসলিম বাহিনীকে নিরাপদে বের করে আনেন। এরপর মক্কা বিজয় ও হুনাইনের যুদ্ধে তিনি অগ্রণী ভূমিকা পালন করেন।\n\nরাসুল (সা.)-এর ওফাতের পর খলিফা আবু বকর (রা.) খালিদকে রিদ্দার যুদ্ধ দমনে এবং পরবর্তীতে পারস্য ও শাম বিজয়ের প্রধান সেনাপতি করেন। খালিদের নেতৃত্বে একযোগে বিশ্বের দুই পরাশক্তি সাসানীয় পারস্য সাম্রাজ্য ও বাইজেন্টাইন রোমান সাম্রাজ্যের পতন ঘটে। ইয়ারমুকের মহাযুদ্ধে তাঁর রণকৌশলে লক্ষাধিক রোমান বাহিনীকে শোচনীয়ভাবে পরাজিত হতে হয়। খলিফা উমর (রা.) যখন জনগণের মধ্যে যাতে খালিদের ব্যক্তিগত নির্ভরতা না তৈরি হয় সেজন্য তাঁকে সেনাপতির পদ থেকে অব্যাহতি দেন, তখন খালিদ কোনো ক্ষোভ না দেখিয়ে হাসিমুখে একজন সাধারণ সৈনিক হিসেবে যুদ্ধ চালিয়ে যান।",
    "islamAcceptanceBn": "৭ হিজরির সফর মাসে আমর ইবনুল আস ও উসমান ইবনে তালহার সাথে মদিনায় এসে রাসুলের কদমে আনুগত্যের বায়াত গ্রহণ করেন। রাসুল বলেন: \"আমি জানতাম তোমার মতো বুদ্ধিমান ব্যক্তি একদিন ঠিকই সত্য খুঁজে পাবে।\"",
