        "story": "২১ হিজরিতে সিরিয়ার হিমসে মৃত্যুশয্যায় শুয়ে খালিদ বিন ওয়ালিদ কাঁদছিলেন। একজন এসে জিজ্ঞাসা করলেন: \"হে আবু সুলাইমান! আপনি কাঁদছেন কেন?\" খালিদ নিজের চাদর সরিয়ে বললেন: \"দেখো! আমার শরীরের এমন এক ইঞ্চি জায়গাও খালি নেই যেখানে কোনো তীর, বর্শা বা তরবারির আঘাতের দাগ নেই! আমি আজীবন চেয়েছিলাম ময়দানে বীরের মতো শহীদ হতে; অথচ আজ আমাকে একটি বৃদ্ধ উটের মতো বিছানায় শুয়ে মরতে হচ্ছে! কাপুরুষদের চোখ যেন কখনোই না ঘুমায়!\" তখন তাঁর এক সাথি বললেন: \"হে খালিদ! আপনি বুঝতে পারেননি! স্বয়ং রাসুলুল্লাহ (সা.) আপনাকে 'সাইফুল্লাহ' (আল্লাহর তরবারি) উপাধি দিয়েছিলেন। আল্লাহর তরবারি কি কোনোদিন কাফেরের হাতে ভেঙে যেতে পারে? আপনি যদি ময়দানে শহীদ হতেন, তবে মানুষ বলত আল্লাহর তরবারি ভেঙে গেছে!\" এ কথা শুনে খালিদ শান্ত হলেন এবং তাঁর অন্তরে স্বস্তি ফিরে এলো।"
