    "birthAndDeathBn": "জন্ম: ৫৭৩ খ্রি. মক্কা | ওফাত: ৪৩ হিজরি মিশর (৯০ বছর)",
    "summaryBn": "প্রাচীন আরবের শীর্ষ চার প্রতিভাধর প্রাজ্ঞ রাজনীতিকের অন্যতম, যাঁর দূরদর্শী সেনাপতিত্বে সম্পূর্ণ বিনা বাধায় নীল নদের অববাহিকায় রোমান শাসন হটিয়ে মিসর বিজিত হয় এবং ইসলামি সভ্যতার কেন্দ্রবিন্দু ফুস্তাত নগরী প্রতিষ্ঠিত হয়।",
    "detailedBiographyBn": "হযরত আমর ইবনুল আস (রা.) ছিলেন কুরাইশ বংশের বনু সাহম গোত্রের এক তীক্ষ্ণবুদ্ধিসম্পন্ন, বাগ্মী ও কৌশলী নেতা। জাহেলি যুগে তিনি কুরাইশদের শীর্ষ কূটনীতিক ছিলেন। আবিসিনিয়ার নাজ্জাশির দরবারে মুসলমানদের ফিরিয়ে আনার জন্য কাফেররা তাঁকেই রাষ্ট্রদূত করে পাঠিয়েছিল।\n\n৭ হিজরিতে খালিদ বিন ওয়ালিদের সাথে মদিনায় এসে তিনি রাসুল (সা.)-এর হাতে ইসলাম গ্রহণ করেন। রাসুল (সা.) তাঁর হাত ধরে বলেছিলেন: \"আমর! ইসলাম গ্রহণের মাধ্যমে তোমার পেছনের সমস্ত গুনাহ ক্ষমা হয়ে গেছে।\" ইসলাম গ্রহণের মাত্র কিছুদিন পরেই রাসুল (সা.) তাঁকে ‘জাতুস সালাসিল’ অভিযানে সেনাপতি করে পাঠান, যেখানে আবু বকর ও উমর (রা.)-ও তাঁর অধীনে সৈন্য ছিলেন।\n\nখলিফা উমরের সময়ে আমর (রা.) শামের ফিলিস্তিন বিজয়ে নেতৃত্ব দেন এবং পরবর্তীতে উমরকে বুঝিয়ে ঐতিহাসিক মিসর অভিযানের নেতৃত্ব দেন। মাত্র ৪ হাজার মুজাহিদ নিয়ে তিনি রোমানদের বাবিলিয়ন দুর্গ জয় করেন এবং সমগ্র মিশর ইসলামি খিলাফতের অন্তর্ভুক্ত করেন। তিনি নীল নদের তীরে আফ্রিকার প্রথম জামে মসজিদ ‘মসজিদে আমর ইবনুল আস’ এবং ফুস্তাত নগরী প্রতিষ্ঠা করেন। খলিফা উমর তাঁর বুদ্ধিমত্তা দেখে বলতেন: \"আমরের জমিনে সাধারণ মানুষ হিসেবে চলা উচিত নয়, তার উচিত কোনো দেশের শাসক হয়ে থাকা!\"",
    "islamAcceptanceBn": "হুদায়বিয়ার সন্ধির পর হাবশার নাজ্জাশির প্রভাবে প্রভাবিত হয়ে ৭ হিজরিতে খালিদ বিন ওয়ালিদের সাথে মদিনায় এসে রাসুল (সা.)-এর হাতে ইসলাম গ্রহণ করেন।",
    "keyVirtuesBn": [
      "মিশর বিজয়ের মহানায়ক এবং আফ্রিকায় ইসলামের প্রথম প্রবেশদ্বার উন্মোচনকারী।",
      "রাসুলুল্লাহ (সা.) যাঁর ঈমানের সাক্ষ্য দিয়ে বলেছিলেন: \"মানুষ ইসলাম এনেছে, কিন্তু আমর ঈমান এনেছে!\"",
      "আরবের শীর্ষ প্রজ্ঞাবান ও কূটনীতিকদের মধ্যে অগ্রগণ্য ব্যক্তিত্ব।"
    ],
    "emotionalStoriesBn": [
      {
        "title": "মৃত্যুশয্যায় প্রাচীরের দিকে মুখ ফিরিয়ে কান্না",
        "story": "৪৩ হিজরিতে মৃত্যুর সময় আমর ইবনুল আস প্রাচীরের দিকে মুখ ফিরিয়ে অঝোরে কাঁদছিলেন। তাঁর ছেলে আব্দুল্লাহ বললেন: \"বাবা! আপনি কাঁদছেন কেন? রাসুল (সা.) কি আপনাকে সুসংবাদ দেননি?\" আমর মুখ ফিরিয়ে বললেন: \"আমার জীবনের সবচেয়ে বড় সম্পদ হলো লা ইলাহা ইল্লাল্লাহু মুহাম্মাদুর রাসুলুল্লাহর সাক্ষ্য। আমার জীবনের তিনটি অধ্যায় ছিল—প্রথমে আমি রাসুলকে সবচেয়ে ঘৃণা করতাম এবং ভাবতাম তাঁকে হত্যা করতে পারলে সফল হব। সেই অবস্থায় মরলে জাহান্নামী হতাম। এরপর যখন ইসলাম আনলাম, তখন রাসুলকে এত ভালোবাসতাম যে লজ্জায় ও শ্রদ্ধায় চোখ তুলে তাঁর দিকে তাকাতে পারতাম না। কেউ যদি আমাকে রাসুলের চেহারার বর্ণনা দিতে বলত আমি দিতে পারতাম না, কারণ আমি কখনো তৃপ্ত হয়ে তাঁর দিকে তাকাইনি। সেই অবস্থায় মরলে জান্নাতী হতাম। এরপর দুনিয়ার রাজনীতিতে জড়িয়েছি, জানি না আল্লাহর দরবারে আমার কী হাল হবে!\" এরপর তিনি আল্লাহর দরবারে হাত তুলে ফরিয়াদ করতে লাগলেন: \"হে আল্লাহ! আমি নির্দোষ নই যে ওজর পেশ করব, আমি শক্তিশালী নই যে জয়ী হব; তবে আপনি ছাড়া কোনো উদ্ধারকারী নেই!\" এই অবস্থায় তিনি ইন্তেকাল করেন।"
      }
    ],
