    "summaryBn": "পবিত্র কুরআনে নাম উল্লেখিত একমাত্র সাহাবি যায়েদ, যিনি আপন পিতা-মাতার চেয়ে রাসুল (সা.)-এর গোলামিকে ভালোবেসে গ্রহণ করেছিলেন; এবং যাঁর পুত্র উসামা মাত্র ১৭ বছর বয়সে রাসুল (সা.)-এর অন্তিম মুহূর্তে রোমান অভিযানের সর্বাধিনায়ক নিযুক্ত হন।",
    "detailedBiographyBn": "হযরত যায়েদ বিন হারেসা (রা.) শৈশবে দস্যুদের দ্বারা অপহৃত হয়ে দাস হিসেবে মক্কায় বিক্রি হন। উম্মুল মুমিনীন খাদিজা (রা.) তাঁকে কিনে রাসুলুল্লাহ (সা.)-কে উপহার দেন। রাসুল (সা.) যায়েদকে পুত্রের মতো ভালোবাসতেন। পরবর্তীতে যায়েদের পিতা-চাচা বিপুল মুক্তিপণ নিয়ে মক্কায় এসে যায়েদকে ফেরত চাইলে রাসুল (সা.) যায়েদকে স্বাধীনতা দেন যে তিনি চাইলে পরিবারের সাথে ফিরে যেতে পারেন। কিন্তু যায়েদ রাসুল (সা.)-এর পা জড়িয়ে ধরে কেঁদে বললেন: \"আমি আপনার চেয়ে কাউকে প্রাধান্য দিতে পারি না! আমি আজীবন আপনার গোলাম হয়ে থাকতে চাই!\" রাসুল (সা.) এতে আবেগাপ্লুত হয়ে কাবার সামনে ঘোষণা দেন: \"যায়েদ আমার পুত্র, আমি তার ওয়ারিশ আর সে আমার ওয়ারিশ!\"\n\nতিনি ছিলেন স্বাধীনের মধ্যে প্রথম মুসলমান। পবিত্র কুরআনের সূরা আহযাবের ৩৭ নম্বর আয়াতে স্বয়ং আল্লাহ তাআলা নাম ধরে যায়েদের উল্লেখ করেছেন; কুরআনে অন্য কোনো সাহাবির নাম আসেনি। ৮ হিজরিতে মুতার যুদ্ধে রাসুল (সা.) যায়েদকে প্রথম সেনাপতি করেন এবং সেখানেই তিনি শহীদ হন।\n\nযায়েদের পুত্র উসামা ইবনে যায়েদ (রা.)-কে রাসুল (সা.) নিজের নাতি হাসান-হোসাইনের মতোই ভালোবাসতেন। ১১ হিজরিতে রাসুল (সা.) তাঁর ওফাতের ঠিক পূর্বে রোমান সাম্রাজ্যের বিরুদ্ধে শামে এক সুবিশাল অভিযানের জন্য মাত্র ১৭ বা ১৮ বছরের তরুণ উসামাকে প্রধান সেনাপতি নিয়োগ করেন। এই বাহিনীতে আবু বকর ও উমর (রা.)-এর মতো শীর্ষ সাহাবিরা সাধারণ সৈন্য ছিলেন। আবু বকর (রা.) খলিফা হয়ে সবার আপত্তি উপেক্ষা করে রাসুলের নির্দেশিত ‘জায়শে উসামা’ প্রেরণ করেন এবং উসামা বিজয়ী হয়ে ফিরে আসেন।",
    "islamAcceptanceBn": "নবুওয়াতের প্রথম দিনেই খাদিজা ও আলীর পরপরই দাস ও স্বাধীনদের মধ্যে সর্বপ্রথম ইসলাম গ্রহণ করেন।",
