      {
        "title": "পিতা ও রাসুলের মাঝে যায়েদের পছন্দ",
        "story": "যায়েদের পিতা হারেসা যখন মক্কায় এসে চোখের পানিতে বললেন: \"হে যায়েদ! তোমার বিরহে তোমার মায়ের চোখ অন্ধ হওয়ার উপক্রম, আমাদের সাথে ঘরে ফিরে চলো!\" রাসুল (সা.) বললেন: \"যায়েদ, তুমি স্বাধীন, চাইলে পিতার সাথে যেতে পারো।\" যায়েদ রাসুল (সা.)-এর হাত নিজের বুকে চেপে ধরে বললেন: \"হে আল্লাহর রাসুল! আমি আপনার মধ্যে যে মহত্ত্ব দেখেছি, এরপর আমি পৃথিবীর আর কাউকে আপনার ওপর প্রাধান্য দিতে পারি না! আমার মা-বাবা ফিরে যান, আমি মুহাম্মদ (সা.)-এর সঙ্গ এক মুহূর্তের জন্যও ছাড়ব না!\" যায়েদের পিতা ক্ষোভে ফেটে পড়েছিলেন, কিন্তু যায়েদের এই নিখাদ প্রেম তাঁকে চিরদিনের জন্য রাসুলের কোলে স্থান করে দেয়।"
      }
