    "nameAr": "أبو دجانة سماك بن خرشة رضي الله عنه",
    "titleBn": "জুস-সিবাতিল হামরা (লাল পট্টিওয়ালা বীর), রাসুলের তরবারির হক আদায়কারী",
    "categoryKey": "commanders",
