    "birthAndDeathBn": "জন্ম: মদিনা | শাহাদাত: ১২ হিজরি (ইয়ামামার যুদ্ধ)",
    "summaryBn": "উহুদের যুদ্ধে রাসুলুল্লাহ (সা.)-এর হাত থেকে তরবারি নিয়ে মাথায় লাল রেশমি ফিতা বেঁধে মৃত্যুর মিছিল থামিয়ে দেওয়া বীর; যিনি ভণ্ড নবি মুসায়লামা কাজ্জাবের দুর্গপ্রাকারে লাফিয়ে পড়ে শাহাদাত বরণ করেছিলেন।",
    "detailedBiographyBn": "হযরত আবু দুজানা সিমাক ইবনে খারশাহ (রা.) ছিলেন মদিনার খাযরাজ গোত্রের এক অসীম সাহসী বীর মুজাহিদ। যুদ্ধের ময়দানে তিনি যখন মাথায় একটি বিশেষ লাল রঙের কাপড় বাঁধতেন, তখন সাহাবিরা বুঝে নিতেন যে আবু দুজানা আজ মৃত্যুর আগ পর্যন্ত যুদ্ধ করার শপথ নিয়েছেন।\n\nউহুদের যুদ্ধের প্রাক্কালে রাসুলুল্লাহ (সা.) একটি ধারালো তরবারি হাতে তুলে নিয়ে ঘোষণা করলেন: \"কে আছে যে আমার হাত থেকে এই তরবারিটি নেবে এবং এর উপযুক্ত হক আদায় করবে?\" সাহাবিদের মধ্যে অনেকেই—উমর, জুবায়ের, আলী (রা.) হাত বাড়ালেন। কিন্তু রাসুল (সা.) হাত গুটিয়ে নিলেন। আবু দুজানা এগিয়ে এসে জিজ্ঞাসা করলেন: \"হে আল্লাহর রাসুল! এই তরবারির হক কী?\" রাসুল (সা.) বললেন: \"এর হক হলো তুমি শত্রুসেনার ওপর এই তরবারি এমনভাবে চালাবে যতক্ষণ না তা বাঁকা হয়ে যায়!\" আবু দুজানা বললেন: \"আমি এর হক আদায় করব!\"\n\nতিনি মাথায় লাল পট্টি বেঁধে বুক ফুলিয়ে দুলকি চালে শত্রুসেনার দিকে এগোতে লাগলেন। রাসুল (সা.) তা দেখে বললেন: \"এই চলার ভঙ্গি আল্লাহ সবচেয়ে ঘৃণা করেন, তবে একমাত্র যুদ্ধের এই ময়দান ছাড়া!\" উহুদের ময়দানে তিনি কাফেরদের ব্যূহ ছিন্নভিন্ন করে সামনে এগোতে থাকেন। যুদ্ধের এক পর্যায়ে তিনি এক সৈন্যকে তলোয়ারের মুখে পান যে কাফেরদের উৎসাহ দিচ্ছিল; পরে দেখলেন সে আবু সুফিয়ানের স্ত্রী হিন্দ। তিনি তলোয়ার নামিয়ে নিলেন এবং বললেন: \"রাসুলের তরবারিকে আমি কোনো নারীর রক্তে কলঙ্কিত করব না।\" ১২ হিজরিতে ইয়ামামার যুদ্ধে মুসায়লামার ‘মৃত্যুর বাগান’ দুর্গের দেয়াল টপকে তিনি ভেতরে লাফিয়ে পড়েন এবং মুসায়লামাকে হত্যায় অংশ নিয়ে শহীদ হন।",
    "islamAcceptanceBn": "মদিনায় হিজরতের প্রাক্কালে আনসারদের সাথে ইসলাম গ্রহণ করেন এবং বদরে বীরত্ব দেখান।",
