        "story": "উহুদের চরম সংকটে যখন চারদিক থেকে রাসুল (সা.)-এর ওপর তীরের বৃষ্টি হচ্ছিল, আবু দুজানা নিজের শরীরকে ধনুকের মতো বাঁকা করে রাসুলুল্লাহ (সা.)-এর ওপর ঝাঁপিয়ে পড়লেন। শত্রুর একের পর এক বিষাক্ত তীর তাঁর নগ্ন পিঠে বিঁধতে লাগল। তীরবিদ্ধ হয়ে রক্তে তাঁর সারা শরীর ভিজে যাচ্ছিল, কিন্তু তিনি একটুও নড়েননি যাতে একটি তীরও তাঁর নিচে থাকা রাসুল (সা.)-এর গায়ে না লাগে। সাহাবিরা বলতেন, আবু দুজানার পিঠটি তীরের আঘাতে একটি শজারুর মতো দেখাচ্ছিল!"
