    "summaryBn": "খলিফা আবু বকর (রা.) যাঁর রণহুংকার সম্পর্কে বলেছিলেন: \"যে সেনাদলে কাকা’র মতো একজন বীর রয়েছে তারা কখনো পরাজিত হতে পারে না\"; কাদিসিয়ার যুদ্ধে পারস্যের হস্তীবাহিনীকে একাই ধূলিসাৎকারী মহাবীর।",
    "detailedBiographyBn": "হযরত কাকা’ ইবনে আমর আত-তমিমি (রা.) ছিলেন বনু তামিম গোত্রের এক অনন্যসাধারণ অশ্বারোহী যোদ্ধা ও কবি। তিনি ৯ হিজরিতে রাসুলুল্লাহ (সা.)-এর দরবারে প্রতিনিধিদলের সাথে এসে ইসলাম গ্রহণ করেন।\n\nখলিফা আবু বকর সিদ্দিক (রা.) যখন খালিদ বিন ওয়ালিদকে পারস্য অভিযানের জন্য সাহায্য পাঠানোর অনুরোধ পান, তখন আবু বকর শুধু কাকা’ ইবনে আমরকে সাহায্য হিসেবে পাঠান। লোকেরা বিস্মিত হয়ে বলল: \"হে খলিফা! খালিদের সাহায্যের জন্য আপনি মাত্র একজনকে পাঠালেন?\" আবু বকর (রা.) উত্তরে এক ঐতিহাসিক উক্তি করলেন: \"যুদ্ধক্ষেত্রে কাকা’র কণ্ঠস্বর এক হাজার অশ্বারোহীর চেয়েও বেশি শক্তিশালী! যে বাহিনীতে কাকা’র মতো মানুষ আছে সে বাহিনী কোনোদিন পরাজিত হতে পারে না!\"\n\nকাদিসিয়ার ঐতিহাসিক যুদ্ধে সা’দ ইবনে আবি ওয়াক্কাস যখন সেনাপতি ছিলেন, কাকা’র অসাধারণ কৌশল সমগ্র যুদ্ধের মোড় ঘুরিয়ে দেয়। পারস্য বাহিনীর বিশাল যুদ্ধের হাতিগুলো যখন মুসলিম অশ্বারোহীদের ছত্রভঙ্গ করে দিচ্ছিল, কাকা’ নিজ বুদ্ধি খাটিয়ে উটগুলোকে অদ্ভুত কাপড়ে সাজিয়ে হাতির মতো বানিয়ে পারসিকদের ঘোড়াগুলোকে দিগ্বিদিক ছুটিয়ে দেন। এরপর তিনি নিজে বর্শা নিয়ে পারস্যের প্রধান সাদা হাতিটির চোখে আঘাত করে তাকে অন্ধ করে দেন, যার ফলে হস্তীবাহিনী উল্টো পারসিক সৈন্যদের পদদলিত করে পালায়। ইয়ারমুক ও কাদিসিয়া বিজয়ে তাঁর তরবারি ও গর্জন মুসলিমদের বিজয় সুনিশ্চিত করে।",
    "islamAcceptanceBn": "৯ হিজরিতে ওফাতুল ওফুদ (প্রতিনিধিদলের বছর)-এ বনু তামিমের সাথে এসে রাসুল (সা.)-এর হাতে ইসলাম গ্রহণ করেন।",
