    "summaryBn": "আনাস ইবনে মালিক (রা.)-এর আপন বড় ভাই, যিনি একাকী ১০০ জনেরও বেশি মুশরিক বীরকে দ্বন্দ্বযুদ্ধে হত্যা করেছিলেন; যাঁর কসম ও দোয়া আল্লাহ কখনোই ফেরত দিতেন না এবং যিনি ইয়ামামার দুর্গে নিজেকে ছুড়ে ফেলার নির্দেশ দিয়েছিলেন।",
    "detailedBiographyBn": "হযরত বারাআ ইবনে মালিক (রা.) ছিলেন রাসুলুল্লাহ (সা.)-এর প্রিয় খাদেম আনাস ইবনে মালিক (রা.)-এর আপন ভাই। দেখতে ছিলেন রোগা-পাতলা, কিন্তু যুদ্ধের ময়দানে তিনি ছিলেন এক প্রচণ্ড অগ্নিকুণ্ড। খলিফা উমর (রা.) সমস্ত সেনাপতিকে সতর্ক করে চিঠি লিখেছিলেন: \"সাবধান! বারাআ ইবনে মালিককে কখনো কোনো বাহিনীর সেনাপতি বানাবে না; কারণ তার অদম্য সাহসের কারণে সে সৈন্যদের নিয়ে আত্মঘাতী মৃত্যুর মুখে ঝাঁপিয়ে পড়বে!\"\n\n১২ হিজরিতে ইয়ামামার যুদ্ধে ভণ্ড নবি মুসায়লামার ৪০ হাজার সৈন্য যখন ‘হাদিকাতুল মাউত’ (মৃত্যুর বাগান) নামক সুরম্য দুর্গের ভেতর ঢুকে ভারী লোহার দরজা বন্ধ করে দিল, তখন মুসলিমরা দরজার সামনে আটকা পড়ে গেল। বারাআ চিৎকার করে বললেন: \"হে মুসলিমরা! আমাকে একটি ঢালের ওপর বসিয়ে বর্শা দিয়ে ঠেলে ওই দুর্গের প্রাচীরের ওপারে কাফেরদের ভেতর ছুড়ে ফেলো! আমি একাই দরজা খুলে দেব অথবা শহীদ হব!\" সাহাবিরা তাঁকে প্রাচীরের ওপর ছুড়ে মারলেন। তিনি একা ভেতরে পড়ে শত শত কাফের সেনার সাথে যুদ্ধ করে মারাত্মক আহত অবস্থায় দুর্গের লোহার খিল খুলে দেন। সেদিন তাঁর শরীরে ৮০টির বেশি তরবারি ও তীরের ক্ষত তৈরি হয়েছিল এবং খালিদ বিন ওয়ালিদ এক মাস তাঁর সেবা করে সুস্থ করেছিলেন।\n\n২০ হিজরিতে পারস্যের সুরক্ষিত তুসতার দুর্গে যখন লড়াই চলছিল, তখন বারাআ আল্লাহর দরবারে শাহাদাতের দোয়া করেন। তুসতার দুর্গের প্রাচীর থেকে পারসিকরা আগুনে উত্তপ্ত লোহার শিক ও শিকল ফেলে মুসলিমদের টেনে তুলছিল। তাঁর ভাই আনাসকে এমন এক জ্বলন্ত শিকলে আটকে টানা হচ্ছিল। বারাআ খালি হাতে সেই জ্বলন্ত গরম শিকল আঁকড়ে ধরে টেনে ধরে নিজের হাতের মাংস পুড়িয়ে হাড় বের করে ভাইকে রক্ষা করেন এবং কিছুক্ষণ পরেই শাহাদাতের অমীয় পেয়ালা পান করেন।",
    "islamAcceptanceBn": "মদিনায় সূচনাতেই ইসলাম গ্রহণ করেন এবং উহুদ, খন্দকসহ প্রতিটি যুদ্ধে অংশ নেন।",
