        "story": "তুসতার দুর্গে পারসিকদের প্রাচীর থেকে নামানো জ্বলন্ত লোহার আঁকশিতে আনাস (রা.) আটকে ছটফট করছিলেন। বারাআ ক্ষিপ্রগতিতে ছুটে এসে নিজের দুই হাত দিয়ে সেই লাল টকটকে জ্বলন্ত লোহার শিকল আঁকড়ে ধরলেন। তাঁর হাতের তালুর গোশত পুড়ে ছাই হয়ে হাড় দেখা যাচ্ছিল, কিন্তু তিনি শিকল ছাড়েননি যতক্ষণ না ভাই আনাসকে মুক্ত করে মাটিতে নামিয়েছেন। এরপর সাহাবিরা এসে বললেন: \"হে বারাআ! রাসুল বলেছেন তোমার দোয়া আল্লাহ কবুল করেন, তুমি আল্লাহর দরবারে বিজয়ের জন্য দোয়া করো!\" বারাআ হাত তুললেন: \"হে আল্লাহ! আজ আপনি আমাদের মুসলিম বাহিনীকে বিজয় দান করুন এবং আমাকে নবি মুহাম্মদ (সা.)-এর সাথে মিলিত হওয়ার জন্য সর্বপ্রথম শহীদ হিসেবে কবুল করুন!\" কিছুক্ষণের মধ্যেই তুসতার দুর্গ জয় হলো এবং বারাআ শাহাদাতের হাসিমুখে মাটিতে লুটিয়ে পড়লেন।"
