    "categoryKey": "commanders",
    "categoryBn": "রণাঙ্গনের অকুতোভয় সেনাপতি (#৩১)",
    "birthAndDeathBn": "জন্ম: মুযাইনা গোত্র | শাহাদাত: ২১ হিজরি (নাহাওয়ান্দের যুদ্ধ)",
    "summaryBn": "মুযাইনা গোত্রের সর্দার যিনি একাই নিজের দশ ভাই ও চারশ অশ্বারোহী নিয়ে রাসুল (সা.)-এর কাছে এসে ইসলাম গ্রহণ করেছিলেন; এবং ২১ হিজরিতে ‘ফাতহুল ফুতুহ’ (বিজয়ের মহাবিজয়) নাহাওয়ান্দের যুদ্ধে পারস্যের দেড় লাখ সৈন্যের বিরুদ্ধে নেতৃত্ব দিয়ে শহীদ হন।",
    "detailedBiographyBn": "হযরত নু’মান ইবনে মুকাররিন (রা.) ছিলেন মদিনার সন্নিকটে বসবাসকারী মুযাইনা গোত্রের এক অত্যন্ত সম্মানিত গোত্রপ্রধান। ৫ হিজরিতে খন্দক যুদ্ধের পূর্বে তিনি এক রাতে গোত্রের লোকদের ডেকে বললেন: \"আমরা মুহাম্মদ (সা.)-এর কাছ থেকে কেবল কল্যাণ ও উত্তম চরিত্রই শুনেছি, তবে কেন আমরা ইসলাম গ্রহণে দেরি করছি?\" পরদিন তিনি নিজের দশ সহোদর ভাই এবং চারশত অশ্বারোহী যোদ্ধা নিয়ে মদিনায় রাসুলুল্লাহ (সা.)-এর দরবারে উপস্থিত হন। আরবের ইতিহাসে একই সাথে এক পরিবারের এতগুলো ভাইয়ের ইসলাম গ্রহণের এমন নজির আর ছিল না। স্বয়ং আল্লাহ তাআলা তাঁদের প্রশংসায় সূরা তাওবার ৯৯ নম্বর আয়াত নাজিল করেন।\n\nতিনি খন্দক, খায়বার, মক্কা বিজয় ও হুনাইনের যুদ্ধে অংশ নেন। খলিফা উমর (রা.)-এর আমলে পারস্য সাম্রাজ্য যখন তাদের সর্বশেষ অস্তিত্ব রক্ষার জন্য নাহাওয়ান্দে দেড় লক্ষ সৈন্যের এক মহাবহর একত্রিত করে, তখন খলিফা উমর অত্যন্ত চিন্তিত হয়ে মদিনাবাসীদের পরামর্শে নু’মান ইবনে মুকাররিনকে সেই চূড়ান্ত অভিযানের সর্বাধিনায়ক নিযুক্ত করেন।\n\n২১ হিজরিতে নাহাওয়ান্দের প্রান্তরে নু’মান এক বিস্ময়কর রণকৌশল অবলম্বন করেন। পারসিকরা যখন সুরক্ষিত পরিখার ভেতরে লুকিয়ে বের হচ্ছিল না, তখন নু’মান পিছু হটার ভান করে তাদের খোলা ময়দানে নিয়ে আসেন। যুদ্ধের পূর্বে তিনি বললেন: \"আমি তিনবার তাকবির বলব। তৃতীয় তাকবিরের পর আক্রমণ করবে। আর যদি আমি শহীদ হই, তবে কেউ যেন আমার জন্য না থামে; আমার জায়গায় হুযায়ফা পতাকা তুলবে!\" প্রচণ্ড যুদ্ধের মাঝে একটি তীরের আঘাতে ঘোড়া থেকে পড়ে নু’মান শহীদ হন। তাঁর ভাই এসে দ্রুত একটি চাদর দিয়ে তাঁর লাশ ঢেকে রাখেন এবং পতাকা তুলে যুদ্ধ চালিয়ে যান। সূর্যাস্তের পূর্বেই পারস্য সাম্রাজ্যের কফিনে শেষ পেরেক ঠুকে দেওয়া হয় এবং ঐতিহাসিক ‘ফাতহুল ফুতুহ’ অর্জিত হয়।",
    "islamAcceptanceBn": "৫ হিজরিতে নিজ গোত্রের দশ ভাই ও চারশ সৈন্যসহ এসে রাসুল (সা.)-এর হাতে ইসলাম গ্রহণ করেন।",
