        "title": "নাহাওয়ান্দের ময়দানে চাদরে ঢাকা সেনাপতির লাশ ও কান্না",
        "story": "নাহাওয়ান্দের রক্তক্ষয়ী যুদ্ধের সমাপ্তিতে মুসলিমরা যখন আল্লাহর দরবারে শুকরিয়া জানাচ্ছিল, তখন সাহাবিরা সেনাপতি নু’মানের খোঁজে এলেন। দেখলেন ঘোড়ার পায়ের কাছে রক্তের সাগরে একটি চাদর দিয়ে নু’মানের দেহ ঢাকা। চাদরটি সরাতেই দেখা গেল নু’মানের মুখে লেগে আছে জান্নাতী প্রশান্তির এক মধুর হাসি। মদিনায় যখন উমর (রা.)-এর কাছে নাহাওয়ান্দ বিজয়ের সুসংবাদ নিয়ে দূত পৌঁছাল, উমর আনন্দের সাথে জিজ্ঞাসা করলেন: \"আমার সেনাপতি নু’মান কেমন আছেন?\" দূত মাথা নিচু করে বলল: \"হে আমিরুল মুমিনীন! নু’মান শাহাদাতের মর্যাদা পেয়েছেন!\" এ কথা শোনামাত্র উমর (রা.) মুখে দুই হাত গুঁজে এমন বুকফাটা আর্তনাদ করে কাঁদলেন যে তাঁর কান্নায় উপস্থিত সবাই অঝোরে কাঁদতে লাগলেন।"
