    "summaryBn": "ইসলামের চরম শত্রু আবু জাহেলের সুযোগ্য পুত্র, যিনি মক্কা বিজয়ের পর পালিয়ে গিয়ে স্ত্রীর আহবানে রাসুলের কাছে এসে নিখাদ তওবা করেছিলেন; এবং ইয়ারমুকের যুদ্ধে ৪০০ বীর মুজাহিদকে নিয়ে মৃত্যুর শপথ করে রোমান প্রাচীর চূর্ণ করেছিলেন।",
    "detailedBiographyBn": "হযরত ইকরিমা ইবনে আবি জাহেল (রা.) ছিলেন মক্কার কুরাইশদের শীর্ষ নেতা এবং ইসলামের চিরশত্রু আবু জাহেলের পুত্র। পিতার মতোই তিনি ছিলেন বদর, উহুদ ও খন্দকে মুসলিমদের বিরুদ্ধে প্রচণ্ড শত্রুতা প্রদর্শনকারী এক দুর্ধর্ষ অশ্বারোহী যোদ্ধা।\n\n৮ হিজরিতে মক্কা বিজয়ের দিন রাসুলুল্লাহ (সা.) যে চারজন ব্যক্তির রক্ত হালাল ঘোষণা করেছিলেন, ইকরিমা ছিলেন তাদের একজন। প্রাণের ভয়ে তিনি ইয়েমেনের উদ্দেশ্যে লোহিত সাগরের জাহাজে চড়ে পালান। সাগরে প্রচণ্ড ঝড় উঠলে জাহাজের মাঝি বলল: \"আজ লাত ও উজ্জা কোনো কাজে আসবে না, একমাত্র এক আল্লাহর কাছে দোয়া করো!\" ইকরিমা চমকে উঠে ভাবলেন: \"সাগরে যদি এক আল্লাহ ছাড়া কেউ বাঁচাতে না পারে, তবে স্থলেও তো তিনি ছাড়া কেউ বাঁচাতে পারেন না! হে আল্লাহ! আমি অঙ্গীকার করছি, যদি আমি বেঁচে যাই তবে আমি সোজা গিয়ে মুহাম্মদ (সা.)-এর হাতে হাত রেখে তওবা করব!\" ইতোমধ্যে তাঁর স্ত্রী উম্মে হাকিম রাসুল (সা.)-এর কাছ থেকে ইকরিমার জন্য প্রাণভিক্ষা চেয়ে ইয়েমেন গিয়ে ইকরিমাকে ফিরিয়ে আনেন।\n\nমক্কায় এসে তিনি যখন রাসুল (সা.)-এর দরবারে হাজির হলেন, রাসুল (সা.) এত খুশি হলেন যে নিজের চাদর ফেলে দিয়ে আনন্দিত হয়ে উঠে দাঁড়িয়ে ইকরিমাকে জড়িয়ে ধরেন। রাসুল সাহাবিদের আগেই নির্দেশ দিয়েছিলেন: \"ইকরিমা আসছে, কেউ যেন তার সামনে তার মৃত পিতাকে গালি না দেয়!\" ইকরিমা ইসলাম গ্রহণ করে কেঁদে বললেন: \"হে আল্লাহর রাসুল! আমি অতীতে ইসলাম ধ্বংসের জন্য যত সম্পদ ও শ্রম ব্যয় করেছি, শপথ করছি তার দ্বিগুণ আল্লাহর রাস্তায় ব্যয় করব!\" ১৫ হিজরিতে ইয়ারমুকের রক্তক্ষয়ী যুদ্ধে রোমানদের লক্ষাধিক সৈন্যের চাপে যখন মুসলিম ব্যূহ ভেঙে পড়ার উপক্রম হলো, ইকরিমা চিৎকার করে ডাকলেন: \"কে আছ আমার সাথে মৃত্যুর বায়াত গ্রহণ করবে?\" চারশত বীর মুজাহিদ এগিয়ে এলেন। ইকরিমা সেই চারশত জানবাযকে নিয়ে রোমানদের ব্যূহে এমন মরণপণ আক্রমণ চালান যে রোমানদের মেরুদণ্ড ভেঙে যায় এবং ইকরিমা নিজে তীর ও তলোয়ারের অগণিত ক্ষত নিয়ে মাটিতে লুটিয়ে পড়েন।",
    "islamAcceptanceBn": "মক্কা বিজয়ের পর সাগরে ঝড়ের মুখে তাওহীদের সত্যতা উপলব্ধি করে মক্কায় ফিরে রাসুলুল্লাহ (সা.)-এর বুকে লুটিয়ে পড়ে ইসলাম গ্রহণ করেন।",
    "keyVirtuesBn": [
      "রাসুলুল্লাহ (সা.) যাঁর সম্মানে সাহাবিদের আবু জাহেলকে গালি দিতে নিষেধ করেছিলেন।",
      "ইয়ারমুকের যুদ্ধে চারশত মুজাহিদকে নিয়ে ঐতিহাসিক \"কাতাইবাতুল মাউত\" (মৃত্যুর সেনাদল) গঠনকারী।",
      "অতীতের কুফরির অনুশোচনায় আজীবন কুরআনের পাতায় মুখ রেখে চোখের পানিতে তিলাওয়াত করতেন।"
    ],
    "emotionalStoriesBn": [
      {
        "title": "ইয়ারমুকের পানি ও তিন মুমূর্ষু শহীদের ত্যাগ",
        "story": "ইয়ারমুকের যুদ্ধের শেষে ইকরিমা, সুহাইল ইবনে আমর এবং হারিস ইবনে হিশাম মারাত্মক রক্তাক্ত অবস্থায় শেষ নিঃশ্বাস ত্যাগ করছিলেন। একজন সাহাবি এক পাত্র পানি নিয়ে ইকরিমার মুখের কাছে ধরলেন। ইকরিমা পাশে থাকা সুহাইলের দিকে তাকিয়ে ইশারা করে বললেন: \"আগে ওকে দাও, ও আমার চেয়ে বেশি তৃষ্ণার্ত!\" পানি যখন সুহাইলের মুখে নেওয়া হলো, সুহাইল দেখলেন হারিস কাতরাচ্ছেন; তিনি বললেন: \"আগে হারিসকে দাও!\" পানি নিয়ে যখন হারিসের কাছে পৌঁছানো হলো, ততক্ষণে হারিস শহীদ হয়ে গেছেন। দ্রুত সুহাইলের কাছে ফিরে দেখলেন তিনিও শহীদ। এরপর ইকরিমার কাছে ছুটে এসে দেখলেন তৃষ্ণার্ত অবস্থাতেই ইকরিমাও রবের কাছে চলে গেছেন। তিনজনই অন্যের মুখে পানি তুলে দিতে গিয়ে নিজেরা পানি না খেয়ে আল্লাহর সান্নিধ্যে চলে যান।"
      }
    ],
