    "summaryBn": "ইসলামের ইতিহাসে সর্বাধিক হাদিস সংরক্ষণ ও বর্ণনাকারী সাহাবি (৫,৩৭৪টি হাদিস); যিনি আহলে সুফফায় ক্ষুধার জ্বালায় পেটে পাথর বেঁধে দিনরাত রাসুলুল্লাহ (সা.)-এর পবিত্র মুখনিঃসৃত প্রতিটি কথা মুখস্থ করেছিলেন।",
    "detailedBiographyBn": "হযরত আবু হুরায়রা (রা.) ছিলেন ইয়েমেনের দাওস গোত্রের সন্তান। জাহেলি যুগে তাঁর নাম ছিল আব্দুশ শামস; রাসুলুল্লাহ (সা.) তাঁর নাম রাখেন ‘আব্দুর রহমান’। জামার আস্তিনের ভেতর একটি ছোট বিড়ালছানা পরম যত্নে রাখতেন বলে রাসুল (সা.) ভালোবেসে তাঁকে ‘আবু হুরায়রা’ (বিড়ালছানার পিতা) কুনিয়াত দেন।\n\n৭ হিজরিতে খায়বার বিজয়ের সময় তিনি মদিনায় এসে ইসলাম গ্রহণ করেন। ইসলাম গ্রহণের পর তিনি দুনিয়ার যাবতীয় ব্যবসা-বাণিজ্য ও কৃষি কাজ ত্যাগ করে মসজিদে নববীর বারান্দা ‘সুফফাহ’-তে দিনরাত পড়ে থাকতেন। তাঁর একমাত্র ব্রত ছিল রাসুল (সা.)-এর পবিত্র কথা ও আমল মুখস্থ রাখা। ক্ষুধায় পেটে পাথর বেঁধে অজ্ঞান হয়ে যেতেন, তবুও রাসুলের সান্নিধ্য ছাড়তেন না।\n\nএকদিন তিনি রাসুল (সা.)-এর কাছে স্মৃতিশক্তির দুর্বলতার কথা জানালে রাসুল (সা.) বললেন: \"তোমার চাদর বিছিয়ে দাও!\" আবু হুরায়রা চাদর পাতলেন, রাসুল (সা.) তাতে হাত দিয়ে কিছু যেন ঢেলে দিয়ে বললেন: \"চাদরটি বুকে জড়িয়ে নাও!\" আবু হুরায়রা চাদরটি বুকে চেপে ধরলেন। এরপর থেকে তিনি জীবনের শেষ দিন পর্যন্ত রাসুলের মুখ থেকে যা শুনেছেন, তার একটি হরফও কখনো বিস্মৃত হননি। তিনি উম্মাহর জন্য ৫,৩৭৪টি সহিহ হাদিস নিখুঁত সনদে পৌঁছে দিয়েছেন। তাঁর সারা রাত তিন ভাগে বিভক্ত ছিল—এক ভাগ ঘুমানো, এক ভাগ নামাজ ও এক ভাগ হাদিস পুনরাবৃত্তি করা।",
    "islamAcceptanceBn": "৭ হিজরিতে খায়বারের সময় ইয়েমেন থেকে তুফায়েল ইবনে আমরের দাওয়াতে মদিনায় এসে রাসুল (সা.)-এর হাতে ইসলাম গ্রহণ করেন।",
