        "story": "আবু হুরায়রা (রা.) বলেন: আল্লাহর কসম! এমন দিনও গেছে যখন ক্ষুধার যন্ত্রণায় মসজিদে নববীর মিম্বার ও আয়েশা (রা.)-এর ঘরের মাঝখানে আমি বেহুঁশ হয়ে পড়ে থাকতাম। পথচারীরা ভাবত আমি হয়তো মৃগীরোগী, কিন্তু আল্লাহর শপথ! আমার কোনো রোগ ছিল না, শুধু তীব্র ক্ষুধার কারণেই আমি অজ্ঞান হয়ে যেতাম। একদিন রাসুল (সা.) আমাকে দেখে মুচকি হাসলেন এবং আমার অন্তরের অবস্থা বুঝে ডাকলেন: \"আবু হুরায়রা!\" আমি বললাম: \"লাব্বাইক ইয়া রাসূলাল্লাহ!\" এরপর এক পেয়ালা দুধ দিয়ে আহলে সুফফার সমস্ত সাহাবিকে তৃপ্ত করে পান করালেন এবং শেষে আমাকে পেট ভরে পান করিয়ে পরম তৃপ্তি দিলেন।"
