    "emotionalStoriesBn": [
      {
        "title": "রাসুল (সা.)-এর চোখের পানি ও ইবনে মাসউদের তিলাওয়াত",
        "story": "একদিন রাসুলুল্লাহ (সা.) ইবনে মাসউদকে বললেন: \"আব্দুল্লাহ! আমাকে কুরআন তিলাওয়াত করে শোনাও!\" ইবনে মাসউদ লজ্জিত হয়ে বললেন: \"হে আল্লাহর রাসুল! আপনার ওপর কুরআন নাজিল হয়েছে, আর আমি আপনাকে তিলাওয়াত শোনাব?\" রাসুল (সা.) বললেন: \"হ্যাঁ, অন্যের মুখ থেকে তিলাওয়াত শুনতে আমার খুব ভালো লাগে।\" ইবনে মাসউদ সূরা নিসা তিলাওয়াত শুরু করলেন। পড়তে পড়তে যখন ৪১ নম্বর আয়াতে পৌঁছলেন—\"তখন কেমন হবে যখন আমি প্রত্যেক উম্মত থেকে একজন সাক্ষী আনব এবং তোমাকেও তাদের ওপর সাক্ষীরূপে পেশ করব?\"—তখন রাসুল (সা.) বললেন: \"থামো আব্দুল্লাহ!\" ইবনে মাসউদ তাকিয়ে দেখলেন রাসুলুল্লাহ (সা.)-এর দুই চোখ মোবারক দিয়ে অবিরল ধারায় অশ্রু ঝরছে।"
      }
    ],
