        "textBn": "সেই সত্তার শপথ যাঁর হাতে আমার প্রাণ! মিজানের পাল্লায় আব্দুল্লাহর এই দুটি পা উহুদ পাহাড়ের চেয়েও বেশি ভারী হবে!",
