    "summaryBn": "মাত্র ১০ বছর বয়সে যাঁর মা উম্মে সুলাইম তাঁকে রাসুল (সা.)-এর খেদমতে সমর্পণ করেছিলেন; যিনি টানা ১০ বছর রাসুলের সার্বক্ষণিক সেবা করেছেন এবং রাসুল যাঁর জন্য দীর্ঘায়ু ও সম্পদে বরকতের ঐতিহাসিক দোয়া করেছিলেন।",
    "detailedBiographyBn": "হযরত আনাস ইবনে মালিক আল-আনসারী (রা.) ছিলেন মদিনার খাযরাজ গোত্রের সন্তান। রাসুলুল্লাহ (সা.) যখন মদিনায় হিজরত করেন, তখন মদিনার সমস্ত নারী-পুরুষ রাসুলকে বিভিন্ন উপহার দেন। আনাসের মা উম্মে সুলাইম (রা.) ছোট্ট আনাসের হাত ধরে রাসুলের দরবারে নিয়ে এসে বললেন: \"হে আল্লাহর রাসুল! আনসারদের সবাই আপনাকে কিছু না কিছু হাদিয়া দিয়েছে, আমার তো এই ছোট্ট আনাস ছাড়া কিছুই নেই; একে আমি আপনার আজীবনের খাদেম হিসেবে উপহার দিলাম!\"\n\nআনাস (রা.) টানা দশ বছর রাসুলুল্লাহ (সা.)-এর সাথে ছায়ার মতো অবস্থান করেন। রাসুল (সা.) তাঁকে অপরিসীম স্নেহ করতেন এবং আদর করে ডাকতেন ‘উনাইস’ বা ‘ইয়া বুনাইয়া’ (হে আমার স্নেহের বৎস)। আনাস বলেন: \"আমি দশ বছর রাসুলের খেদমত করেছি। আল্লাহর কসম! রাসুল কোনোদিন আমার ওপর একটু বিরক্ত হয়ে 'উহ্' পর্যন্ত বলেননি। আমি কোনো কাজ করতে ভুল করলে তিনি কখনো বলেননি—তুমি এটা কেন করলে? অথবা কোনো কাজ না করলে কখনো বলেননি—কেন করলে না?\"\n\nএকদিন তাঁর মা রাসুলকে বললেন: \"হে আল্লাহর রাসুল! আপনার ছোট খাদেম আনাসের জন্য দোয়া করুন!\" রাসুল (সা.) হাত তুলে দোয়া করলেন: \"হে আল্লাহ! এর সম্পদ ও সন্তান বৃদ্ধি করে দিন এবং আপনি একে যা দিয়েছেন তাতে বরকত দিন!\" এই দোয়ার বরকতে আনাস (রা.) সাহাবিদের মধ্যে সর্বাধিক দীর্ঘায়ু (১০৩ বছর) পেয়েছিলেন, তাঁর নিজের ঔরসের শতাধিক সন্তান-সন্ততি ছিল এবং তাঁর খেজুর বাগান বছরে দুইবার ফল দান করত। ৯৩ হিজরিতে বসরার মাটিতে তিনি শেষ বয়োবৃদ্ধ সাহাবি হিসেবে ইন্তেকাল করেন।",
