        "story": "রাসুলুল্লাহ (সা.)-এর ওফাতের পর আনাস (রা.) রাসুলের স্মৃতিচিহ্নগুলো চোখের মনির মতো আগলে রেখেছিলেন। তাঁর কাছে রাসুল (সা.)-এর কিছু চুল মোবারক, একটি কাঠের পেয়ালা এবং একটি ছোট লাঠি ছিল। আনাস (রা.) বলতেন: \"আমি এমন কোনো রাত নেই যে রাতে আমার হাবিব মুহাম্মদ (সা.)-কে স্বপ্নে দেখি না!\" মৃত্যুর পূর্বে তিনি অসিয়ত করে গিয়েছিলেন যে রাসুলুল্লাহ (সা.)-এর বরকতময় একটি চুল মোবারক যেন তাঁর জিহ্বার নিচে রেখে দেওয়া হয় এবং রাসুলের দেওয়া লাঠিটি যেন তাঁর কাফনের ভেতরে তাঁর পাঁজরের পাশে রাখা হয়। সাহাবিরা তাঁর সেই অসিয়ত পরম শ্রদ্ধায় পূর্ণ করেছিলেন।"
