    "summaryBn": "রাসুলুল্লাহ (সা.) যাঁর হাত ধরে বলেছিলেন: \"মুআয! আল্লাহর কসম, আমি তোমাকে ভালোবাসি!\"; যাঁকে রাসুল ইয়েমেনের প্রথম প্রধান বিচারপতি হিসেবে পাঠিয়েছিলেন এবং কেয়ামতের দিন যিনি সমস্ত আলেমের অগ্রভাগে এক তীর নিক্ষেপ দূরত্বে নেতৃত্ব দেবেন।",
    "detailedBiographyBn": "হযরত মুআয ইবনে জাবাল (রা.) ছিলেন মদিনার খাযরাজ গোত্রের এক অত্যন্ত রূপবান, সদা হাস্যোজ্জ্বল ও প্রখর মেধার অধিকারী তরুণ। মাত্র ১৮ বছর বয়সে তিনি আকাবার দ্বিতীয় শপথে ইসলাম গ্রহণ করেন।\n\nতিনি ছিলেন ইসলামি শরিয়তের হালাল ও হারামের সবচেয়ে বড় বিশেষজ্ঞ। রাসুলুল্লাহ (সা.) সাহাবিদের বলতেন: \"আমার উম্মতের মধ্যে হালাল ও হারামের বিষয়ে সবচেয়ে প্রাজ্ঞ ব্যক্তি হলো মুআয ইবনে জাবাল।\" ৯ হিজরিতে রাসুল (সা.) তাঁকে ইয়েমেনের গভর্নর ও বিচারপতি করে পাঠান। বিদায়ের সময় রাসুল তাঁকে জিজ্ঞাসা করেছিলেন: \"মুআয! তুমি কিসের ভিত্তিতে বিচার করবে?\" মুআয বললেন: \"আল্লাহর কিতাব দিয়ে।\" রাসুল বললেন: \"যদি কিতাবে সরাসরি না পাও?\" মুআয বললেন: \"রাসুলের সুন্নাহ দিয়ে।\" রাসুল বললেন: \"যদি সুন্নাহতেও না পাও?\" মুআয বললেন: \"আমি আমার আকল দিয়ে ইজতিহাদ করব এবং কোনো ত্রুটি করব না।\" রাসুল (সা.) অত্যন্ত আনন্দিত হয়ে মুআযের বুকে হাত রেখে বললেন: \"সমস্ত প্রশংসা আল্লাহর যিনি তাঁর রাসুলের দূতকে এমন তৌফিক দিয়েছেন যাতে তাঁর রাসুল সন্তুষ্ট!\"\n\nরাসুলুল্লাহ (সা.) পায়ে হেঁটে মুআযের ঘোড়ার সাথে বহু দূর পর্যন্ত এগিয়ে দিয়ে বলেছিলেন: \"হে মুআয! হয়তো আগামী বছর তুমি আমার সাথে আর দেখা করতে পারবে না; হয়তো তুমি আমার মসজিদ ও রওজার পাশ দিয়ে হেঁটে যাবে।\" এ শুনে মুআয কান্নায় ভেঙে পড়েছিলেন। খলিফা উমর (রা.) বলতেন: \"মুআয যদি না থাকত তবে উমর ধ্বংস হয়ে যেত।\" মাত্র ৩৮ বছর বয়সে তিনি শামের প্লেগে ইন্তেকাল করেন।",
    "islamAcceptanceBn": "আকাবার দ্বিতীয় শপথে ১৮ বছর বয়সে মদিনার সর্দারদের সাথে ইসলাম গ্রহণ করেন।",
