        "story": "একদিন রাসুলুল্লাহ (সা.) মুআযের হাত নিজের হাতের মধ্যে পরম ভালোবাসায় জড়িয়ে ধরে বললেন: \"হে মুআয! আল্লাহর কসম, আমি নিশ্চয়ই তোমাকে ভালোবাসি! আল্লাহর কসম, আমি তোমাকে ভালোবাসি!\" মুআয কেঁদে ফেলে বললেন: \"আমার পিতা-মাতা আপনার ওপর কোরবান হোক ইয়া রাসূলাল্লাহ! আমিও আপনাকে ভালোবাসি!\" রাসুল (সা.) বললেন: \"হে মুআয! আমি তোমাকে অসিয়ত করছি, কোনো নামাজের পর এই দোয়াটি পড়া কখনো ছাড়বে না—'আল্লাহুম্মা আইন্নি আলা জিকরিকা ওয়া শুকরিকা ওয়া হুসনি ইবাদাতিকা' (হে আল্লাহ! আপনার স্মরণ, আপনার শোকর এবং আপনার সুন্দর ইবাদত করার জন্য আমাকে সাহায্য করুন)।\""
