    "titleBn": "সাইয়্যিদুল কুররা (ক্বারীগণের সর্দার), অহী লেখক",
    "categoryKey": "scholars",
    "categoryBn": "বিজ্ঞ আলেম ও ফকিহ (#৩৮)",
    "birthAndDeathBn": "জন্ম: মদিনা | ওফাত: ৩০ হিজরি মদিনা",
    "summaryBn": "কুরআনের শ্রেষ্ঠ ক্বারী, যাঁর জন্য স্বয়ং মহান রাব্বুল আলামিন সাত আসমানের ওপর থেকে নাম ধরে রাসুল (সা.)-কে তাঁর কাছে কুরআন পাঠ করে শোনানোর নির্দেশ দিয়েছিলেন।",
    "detailedBiographyBn": "হযরত উবাই ইবনে কা’ব (রা.) ছিলেন মদিনার খাযরাজ গোত্রের বনু নাজ্জার শাখার এক অসাধারণ মেধাবী আলেম। তিনি আকাবার দ্বিতীয় শপথে ইসলাম গ্রহণ করেন। মদিনায় হিজরতের পর রাসুলুল্লাহ (সা.)-এর প্রধান অহী লেখকদের অন্যতম ছিলেন উবাই। রাসুলের উপস্থিতিতে মদিনায় সর্বপ্রথম অহী লিপিবদ্ধ করার সূচনা তিনিই করেছিলেন।\n\nকুরআনের তিলাওয়াত, বিশুদ্ধ উচ্চারণ ও অন্তর্নিহিত জ্ঞানে তিনি ছিলেন অদ্বিতীয়। রাসুল (সা.) বলতেন: \"আমার উম্মতের মধ্যে কুরআনের সবচেয়ে বড় ক্বারী হলো উবাই ইবনে কা’ব।\"\n\nএকদিন রাসুলুল্লাহ (সা.) উবাইকে ডেকে বললেন: \"হে উবাই! আল্লাহ তাআলা আমাকে আদেশ করেছেন আমি যেন তোমাকে সূরা বাইয়িনাহ তিলাওয়াত করে শোনাই!\" উবাই বিস্মিত ও স্তম্ভিত হয়ে কাঁপতে কাঁপতে জিজ্ঞাসা করলেন: \"হে আল্লাহর রাসুল! স্বয়ং আল্লাহ কি তাঁর আসমানে আমার নাম উচ্চারণ করেছেন?\" রাসুল (সা.) বললেন: \"হ্যাঁ, আল্লাহ তোমার নাম ধরে বলেছেন!\" এ কথা শোনামাত্র উবাই ইবনে কা’ব দুহাতে মুখ ঢেকে অঝোরে কাঁদতে লাগলেন। খলিফা উমর (রা.) যখন মসজিদে নববীতে তারাবির সালাত জামাতে পড়ার সুব্যবস্থা করেন, তখন তিনি উবাই ইবনে কা’বকেই সমগ্র সাহাবিদের প্রধান ইমাম নিযুক্ত করেছিলেন।",
    "islamAcceptanceBn": "আকাবার দ্বিতীয় শপথে ইসলাম গ্রহণ করেন এবং মদিনায় রাসুলের প্রধান অহী লেখক হন।",
