        "story": "আনাস (রা.) বর্ণনা করেন: যখন রাসুল (সা.) উবাইকে বললেন—\"আল্লাহ আমাকে নির্দেশ দিয়েছেন তোমাকে কুরআন পাঠ করে শোনাতে\", উবাই আবেগ সংবরণ করতে পারলেন না। তিনি কাঁপতে কাঁপতে বললেন: \"হে আল্লাহর রাসুল! আমার মতো এক নগণ্য বান্দার নাম কি রাব্বুল আলামিনের দরবারে উচ্চারিত হয়েছে?\" রাসুল (সা.) বললেন: \"হ্যাঁ, বিশ্বজাহানের রবের কাছে তোমার নাম নেওয়া হয়েছে!\" উবাইয়ের চোখ দিয়ে অশ্রুর বন্যা বয়ে গেল। সাহাবিরা বলতেন, এই সৌভাগ্যের চেয়ে বড় কোনো সম্মান দুনিয়ার কোনো মানুষের হতে পারে না।"
