    "birthAndDeathBn": "জন্ম: মদিনা | ওফাত: ১৫ হিজরি সিরিয়ার হাওরান",
    "summaryBn": "মদিনার খাযরাজ গোত্রের প্রধান নেতা, যাঁর বাড়ির একটি পাত্র থেকে প্রতিদিন রাসুলুল্লাহ (সা.)-এর পবিত্র স্ত্রীদের ঘরে নিয়মিত খাবার যেত; যাঁর প্রচণ্ড আত্মমর্যাদাবোধ ও দানশীলতার প্রশংসা স্বয়ং রাসুলুল্লাহ (সা.) করেছিলেন।",
    "detailedBiographyBn": "হযরত সা’দ ইবনে উবাদাহ (রা.) ছিলেন জাহেলি যুগেও আরবের শীর্ষ ব্যক্তিত্ব। তিনি একাধারে সাঁতার, তীরন্দাজি এবং লেখালিখি জানতেন বলে জাহেলি আরবে তাঁকে ‘আল-কামিল’ (পরিপূর্ণ মানব) বলা হতো। আকাবার দ্বিতীয় শপথে তিনি মদিনার খাযরাজ গোত্রের অন্যতম প্রধান নকীব (প্রতিনিধি) ছিলেন। আকাবা থেকে ফেরার পথে মক্কার কাফেররা তাঁকে বন্দি করে মক্কার অলিগলিতে চুল ধরে টেনেহিঁচড়ে নিয়ে মারাত্মক নির্যাতন করেছিল।\n\nসা’দ ছিলেন আরবের এক অনন্য দানবীর। মদিনায় তাঁর বাড়ির ছাদ থেকে প্রতিদিন হাঁক ছেড়ে বলা হতো: \"যার গোশত ও রুটির প্রয়োজন সে যেন সা’দ ইবনে উবাদার ঘরে আসে!\" রাসুলুল্লাহ (সা.) যখনই কোনো যুদ্ধের প্রস্তুতি নিতেন, সা’দ একাই বহু উট ও খাদ্যসামগ্রী দান করতেন। মদিনার প্রতিটি ঘরে যখন রাসুলের জন্য হাদিয়া যেত, সা’দের বাড়ি থেকে নিয়মিত একটি বড় পাত্রে সুস্বাদু তরকারি রাসুলের ঘরে পৌঁছাত।\n\nমক্কা বিজয়ের দিনে আনসারদের মূল পতাকা সা’দের হাতে ছিল। হুনাইনের যুদ্ধের পর যখন রাসুল (সা.) নতুন মুসলমানদের মন জয়ের জন্য প্রচুর গনিমত দিলেন কিন্তু আনসারদের কিছুই দিলেন না, তখন আনসারদের মনে কিছুটা মান অভিমান সৃষ্টি হয়েছিল। সা’দ ইবনে উবাদাহ নির্ভীকভাবে আনসারদের সেই অন্তরের কথা রাসুল (সা.)-এর কাছে তুলে ধরেন, যার প্রেক্ষিতে রাসুল (সা.) আনসারদের জন্য তাঁর জীবনের সবচেয়ে আবেগঘন ও অশ্রুসজল ভাষণ দিয়েছিলেন।",
    "islamAcceptanceBn": "আকাবার দ্বিতীয় শপথে ৭০ জন আনসারের অন্যতম প্রধান নেতা হিসেবে বাইয়াত গ্রহণ করেন।",
