        "story": "হুনাইন যুদ্ধের পর সা’দ এসে রাসুলকে বললেন: \"হে আল্লাহর রাসুল! আনসাররা মনে কিছুটা কষ্ট পেয়েছে যে আপনি তাদের বাদ দিয়ে কুরাইশদের গনিমত বিলিয়ে দিলেন!\" রাসুল (সা.) বললেন: \"হে সা’দ! তুমি আনসারদের এক তাঁবুতে একত্রিত করো।\" এরপর রাসুল (সা.) তাঁবুতে এসে বললেন: \"হে আনসাররা! তোমরা কি সন্তুষ্ট নও যে অন্য লোকেরা উট আর বকরি নিয়ে ঘরে ফিরবে আর তোমরা স্বয়ং আল্লাহর রাসুলকে নিয়ে তোমাদের ঘরে ফিরবে? আল্লাহর কসম! যদি হিজরতের মর্যাদা না থাকত, তবে আমি আনসারদের একজন হয়ে বেঁচে থাকতে চাইতাম! হে আল্লাহ! আনসারদের ওপর রহম করুন, আনসারদের সন্তানদের ওপর রহম করুন!\" রাসুলের এই বাণীতে সা’দ ইবনে উবাদাহ এবং সমস্ত আনসার সাহাবি এমনভাবে কাঁদলেন যে তাঁদের বুক ও দাড়ি মোবারক অশ্রুতে ভিজে একাকার হয়ে গিয়েছিল।"
