    "birthAndDeathBn": "জন্ম: মদিনা | ওফাত: ১ হিজরি মদিনা (মসজিদে নববী নির্মাণের সময়)",
    "summaryBn": "মদিনার ইতিহাসের সর্বপ্রথম মুসলমান যিনি আকাবার গিরিপথে সবার আগে রাসুল (সা.)-এর হাতে হাত রেখেছিলেন; এবং যিনি রাসুল (সা.) মদিনায় পৌঁছার পূর্বেই মদিনায় সর্বপ্রথম জুমার সালাত কায়েম করেছিলেন।",
    "detailedBiographyBn": "হযরত আস’াদ ইবনে যুরারাহ আবু উমামা (রা.) ছিলেন মদিনার খাযরাজ গোত্রের অন্যতম দূরদর্শী যুবক নেতা। নবুওয়াতের একাদশ বর্ষে হজের মৌসুমে মক্কার মিনায় আকাবা গিরিপথে যে ছয়জন মদিনাবাসী রাসুলুল্লাহ (সা.)-এর সাথে প্রথম সাক্ষাৎ করেন, আস’াদ ছিলেন তাঁদের প্রধান মুখপাত্র এবং সবার আগে রাসুলের হাতে হাত রেখে ইসলাম গ্রহণকারী।\n\nপরের বছর আকাবার প্রথম শপথে তিনি বারোজনের দল নিয়ে আসেন এবং রাসুল (সা.) তাঁকে মদিনার বারোজন নকীবের প্রধান নকীব মনোনীত করেন। তিনি রাসুল (সা.)-এর কাছে মদিনাবাসীদের জন্য একজন শিক্ষক প্রার্থনা করেন। রাসুল (সা.) মুসআব ইবনে উমাইরকে পাঠালে আস’াদ মুসআবকে নিজের ঘরে আশ্রয় দেন এবং মদিনার অলিগলিতে বাড়ি বাড়ি গিয়ে ইসলামের দাওয়াত দেন।\n\nইসলামের ইতিহাসে মদিনার মাটিতে সর্বপ্রথম জুমার সালাত কায়েম করার অবিসংবাদিত গৌরব আস’াদ ইবনে যুরারার। তিনি বনু বায়াদার প্রান্তরে ৪০ জন সাহাবিকে একত্রিত করে প্রথম জুমা আদায় করান। হিজরতের পর রাসুল (সা.)-এর উট যে স্থানে বসেছিল, সেই জমিটি ছিল আস’াদের তত্ত্বাবধানে থাকা দুই এতিম বালক সাহল ও সুহাইলের। রাসুল (সা.) যখন মসজিদে নববীর ভিত্তি স্থাপন করছিলেন, তখন ১ হিজরির শাওয়াল মাসে আস’াদ মারাত্মক গলার রোগে আক্রান্ত হন এবং হিজরতের মাত্র কয়েক মাসের মাথায় প্রথম আনসার নেতা হিসেবে ইন্তেকাল করেন। রাসুল (সা.) নিজ হাতে তাঁকে গোসল দেন এবং জান্নাতুল বাকিতে তিনিই প্রথম দাফনকৃত সাহাবি।",
    "islamAcceptanceBn": "আকাবার গিরিপথে মক্কার বাইরে প্রথম সাক্ষাতেই কালবিলম্ব না করে রাসুলের হাতে হাত রেখে ইসলাম গ্রহণ করেন।",
