    "birthAndDeathBn": "জন্ম: হাযরামাউত | ওফাত: ৩৩ হিজরি মদিনা (৭০ বছর)",
    "summaryBn": "বদর যুদ্ধে ৩১৩ জনের নিরস্ত্র মুসলিম কাফেলার একমাত্র অশ্বারোহী যোদ্ধা; যিনি বদরের প্রাক্কালে ঐতিহাসিক ঘোষণা দিয়েছিলেন: \"আমরা মূসার কওমের মতো বলব না যে আপনি আর আপনার রব গিয়ে যুদ্ধ করুন; বরং আমরা আপনার ডানে, বামে, সামনে ও পেছনে থেকে যুদ্ধ করব!\"",
    "detailedBiographyBn": "হযরত মিকদাদ ইবনে আমর (রা.) ছিলেন হাযরামাউতের বনু কিনানাহ গোত্রের সন্তান। মক্কায় আসওয়াদ ইবনে আব্দে ইয়াগুস তাঁকে দত্তক নেওয়ায় তিনি ‘মিকদাদ ইবনুল আসওয়াদ’ নামে খ্যাত হন। তিনি মক্কায় সপ্তম ব্যক্তি হিসেবে প্রকাশ্যে ইসলাম গ্রহণ করেন এবং কাফেরদের তীব্র নির্যাতনের শিকার হন।\n\nবদর যুদ্ধের ঐতিহাসিক মুহূর্তে যখন মুসলিমরা বাণিজ্য কাফেলার বদলে মক্কার এক হাজার সুসজ্জিত সেনাদলের মুখোমুখি হলো, তখন রাসুলুল্লাহ (সা.) সাহাবিদের পরামর্শ চাইলেন। সবাই দ্বিধায় ছিলেন। তখন মিকদাদ ইবনুল আসওয়াদ উঠে দাঁড়িয়ে এমন এক সিংহদিল ভাষণ দিলেন যা কিয়ামত পর্যন্ত ঈমানের প্রতীক হয়ে থাকবে। তিনি বললেন: \"হে আল্লাহর রাসুল! আল্লাহ আপনাকে যে নির্দেশ দিয়েছেন আপনি সেদিকে চলুন, আমরা আপনার সাথে আছি! আল্লাহর কসম! বনি ইসরাইল যেমন মূসা (আ.)-কে বলেছিল—'তুমি আর তোমার রব গিয়ে লড়াই করো, আমরা এখানে বসে রইলাম', আমরা কখনোই আপনাকে তা বলব না! বরং আমরা বলব—আপনি ও আপনার রব লড়াই করুন, আমরা আপনার ডানে, বামে, সামনে ও পেছনে রক্ত দিয়ে যুদ্ধ করব!\"\n\nমিকদাদের এই তেজোদৃপ্ত বক্তব্য শুনে রাসুলুল্লাহ (সা.)-এর পবিত্র চেহারা মোবারক খুশিতে উজ্জ্বল হয়ে উঠেছিল। বদরের ময়দানে মুসলিমদের মাত্র দুটি ঘোড়া ছিল, যার একটির আরোহী ছিলেন স্বয়ং মিকদাদ। পরবর্তীতে তিনি মিসর বিজয় ও সাইপ্রাস অভিযানে অসামান্য রণনৈপুণ্য প্রদর্শন করেন।",
