    "summaryBn": "ইয়েমেনের দাওস গোত্রের প্রধান কবি ও নেতা, যিনি মক্কায় এসে কুরাইশদের ভয়ে কানে তুলা গুঁজে কাবার সামনে গিয়েছিলেন যাতে মুহাম্মদের কথা না শোনেন; কিন্তু কুরআনের এক ঝলক শুনেই ইসলাম কবুল করে যাঁর লাঠির মাথায় নূরের আলো প্রজ্জ্বলিত হয়েছিল।",
    "detailedBiographyBn": "হযরত আল-তুফায়েল ইবনে আমর আদ-দৌসী (রা.) ছিলেন আরবের এক অত্যন্ত প্রতিভাধর কবি ও দাওস গোত্রের ধনী সর্দার। মক্কায় এলে কুরাইশ নেতারা তাঁকে সতর্ক করে বলল: \"মুহাম্মদ এমন এক জাদুকর যার কথা শুনলে বাপ-বেটার মাঝে বিচ্ছেদ ঘটে! সাবধান, তার সাথে কথা বলবে না।\" তুফায়েল এতটাই ভীত হলেন যে কাবা তাওয়াফ করার সময় কানে তুলো গুঁজে নিলেন যাতে কোনো শব্দ প্রবেশ না করে।\n\nকিন্তু কাবার সামনে রাসুল (সা.)-কে নামাজ পড়তে দেখে তিনি ভাবলেন: \"আমি একজন প্রবীণ কবি, ভালো-মন্দ বোঝার জ্ঞান আমার আছে, আমি কেন এক টুকরো তুলোর কারণে শুনব না?\" তিনি কান থেকে তুলো ফেলে দিলেন এবং রাসুলের মুখে সূরা ইখলাস ও ফালাক শুনে অভিভূত হয়ে রাসুলের পিছু পিছু তাঁর ঘরে গিয়ে ইসলাম গ্রহণ করলেন।\n\nতুফায়েল বললেন: \"হে আল্লাহর রাসুল! আমার গোত্রে ফিরে গিয়ে আমি ইসলামের দাওয়াত দেব, আপনি আমার জন্য আল্লাহর কাছে একটি নিদর্শন চান!\" রাসুল দোয়া করলেন। গোত্রে ফেরার পথে অন্ধকার রাতে তাঁর কপালে একটি প্রদীপের মতো আলো চমকাতে লাগল। তুফায়েল দোয়া করলেন: \"হে আল্লাহ! মানুষ যেন না ভাবে এটি কোনো রোগ!\" সাথে সাথে সেই নূর তাঁর লাঠির মাথায় স্থানান্তরিত হলো এবং অন্ধকার পাহাড়ি পথে তাঁর লাঠিটি একটি উজ্জ্বল লণ্ঠনের মতো আলো ছড়াতে লাগল। এই অলৌকিক মোজেজা দেখে তাঁর পিতা ও স্ত্রী সাথে সাথে ইসলাম গ্রহণ করেন এবং পরবর্তীতে আবু হুরায়রা (রা.)-সহ পুরো দাওস গোত্র ইসলাম গ্রহণ করে ৭ হিজরিতে মদিনায় এসে রাসুলের সাথে মিলিত হয়। ১২ হিজরিতে ইয়ামামার রক্তক্ষয়ী যুদ্ধে তিনি বীরবিক্রমে লড়াই করে শাহাদাত বরণ করেন।",
    "islamAcceptanceBn": "কানে তুলো গুঁজে কাবার চত্বরে গিয়েও নিজের বিবেক দিয়ে কুরআনের সত্যতা উপলব্ধি করে ইসলাম গ্রহণ করেন।",
