        "story": "মুয়াবিয়া (রা.)-এর যুগে একবার এক ব্যক্তি মসজিদে নববীতে এক অতি বিনম্র বৃদ্ধকে সালাত আদায় করতে দেখে জিজ্ঞাসা করল: \"ইনি কে?\" কায়স ইবনে উবাদ বললেন: \"ইনি জান্নাতবাসীদের একজন!\" সালাত শেষে তিনি আব্দুল্লাহ ইবনে সালামকে জিজ্ঞাসা করলেন: \"আপনি কীভাবে জান্নাতী হলেন?\" আব্দুল্লাহ বললেন: \"রাসুলের জীবদ্দশায় আমি এক স্বপ্ন দেখেছিলাম—আমি এক সুবিশাল সবুজ শ্যামল বাগানে দাঁড়িয়ে আছি যার মাঝখানে একটি লোহার খুঁটি আকাশ পর্যন্ত উঠে গেছে এবং তার শীর্ষে একটি মজবুত হাতল রয়েছে। আমাকে বলা হলো ওঠো! আমি উপরে উঠে সেই হাতলটি শক্ত করে ধরলাম। এরপর আমি ঘুম থেকে উঠলাম। রাসুল (সা.)-কে এই স্বপ্ন জানালে রাসুল মুচকি হেসে বললেন: সেই সবুজ বাগানটি হলো ইসলাম, খুঁটিটি হলো দ্বীনের স্তম্ভ আর সেই হাতলটি হলো 'উরওয়াতুল উসকা' (মজবুত রশি); তুমি মৃত্যুর আগ পর্যন্ত ইসলামের এই মজবুত হাতল আঁকড়ে ধরে থাকবে!\""
