    "id": "suraqah-ibn-malik",
    "rank": 47,
    "nameBn": "হযরত সুরাকা ইবনে মালিক (রা.)",
    "nameAr": "سراقة بن مالك المدلجي رضي الله عنه",
    "titleBn": "কিসরার স্বর্ণের চুড়ি পরিধানকারী, হিজরতের প্রত্যক্ষদর্শী",
    "categoryKey": "commanders",
    "categoryBn": "রণাঙ্গনের অকুতোভয় সেনাপতি (#৪৭)",
    "birthAndDeathBn": "জন্ম: মক্কার উপকণ্ঠ | ওফাত: ২৪ হিজরি মদিনা",
    "summaryBn": "মদিনায় হিজরতের পথে একশ উটের লোভে যিনি রাসুল (সা.)-কে বন্দি করতে ছুটে গিয়েছিলেন; কিন্তু অলৌকিকভাবে ঘোড়ার পা বালিতে গেঁথে যাওয়ার পর রাসুল যাঁর ব্যাপারে ভবিষ্যদ্বাণী করেছিলেন: \"সুরাকা! কেমন লাগবে যেদিন তুমি পারস্য সম্রাট কিসরার রাজকীয় স্বর্ণের চুড়ি পরবে?\"",
    "detailedBiographyBn": "হযরত সুরাকা ইবনে মালিক আল-মুদলিজী (রা.) ছিলেন বনু মুদলিজ গোত্রের দক্ষ অশ্বারোহী ও পদচিহ্ন বিশারদ। রাসুলুল্লাহ (সা.) ও আবু বকর (রা.) যখন মদিনার উদ্দেশ্যে হিজরত করেন, কুরাইশরা ঘোষণা দেয় যে মুহাম্মদকে জীবিত বা মৃত এনে দিতে পারলে একশটি লাল উট পুরস্কার দেওয়া হবে।\n\nসুরাকা লোভ সামলাতে না পেরে দ্রুত বর্ম ও বর্শা নিয়ে নিজের দ্রুতগামী ঘোড়ায় চড়ে রাসুলের পিছু নেন। যখন তিনি রাসুলের একদম কাছাকাছি এসে গেলেন এবং তাঁদের কথোপকথন শুনতে পেলেন, হঠাৎ সুরাকার শক্তিশালী ঘোড়াটির সামনের পা দুটি শক্ত পাথুরে মাটির ভেতর হাঁটু পর্যন্ত ধেবে গেল এবং সুরাকা ছিটকে মাটিতে পড়ে গেলেন। সুরাকা ঘোড়া উঠিয়ে আবার আক্রমণ করতে চাইলে এবার ঘোড়ার পা আরও গভীরভাবে বালিতে দেবে গেল এবং সেখান থেকে ধোঁয়ার মতো এক কুণ্ডলী আকাশে উঠল। সুরাকা বুঝতে পারলেন মুহাম্মদ কোনো সাধারণ মানুষ নন, তিনি আল্লাহর সুরক্ষিত রাসুল।\n\nসুরাকা প্রাণভিক্ষা চেয়ে চিৎকার করলেন: \"আমাকে ক্ষমা করুন! আমি আপনাদের কোনো ক্ষতি করব না!\" রাসুল (সা.) দোয়া করলে ঘোড়ার পা মুক্ত হলো। সুরাকা রাসুলের কাছে একটি নিরাপত্তার লিখিত চিঠি চাইলেন। রাসুল তা লিখে দিয়ে হঠাৎ মুচকি হেসে বললেন: \"সুরাকা! কেমন হবে যখন তুমি পারস্যের প্রতাপশালী সম্রাট কিসরার স্বর্ণের রাজকীয় চুড়ি ও মুকুট পরিধান করবে?\" সুরাকা বিস্মিত হয়ে বললেন: \"কিসরা ইবনে হরমুজ? পারস্যের সেই মহামান্বিত সম্রাট?\" রাসুল বললেন: \"হ্যাঁ, কিসরা ইবনে হরমুজের চুড়ি!\" ৮ হিজরিতে তায়েফ বিজয়ের পর সুরাকা সেই চিঠি নিয়ে এসে রাসুলের হাতে ইসলাম গ্রহণ করেন।\n\nরাসুলের ওফাতের বহু বছর পর ১৬ হিজরিতে খলিফা উমর (রা.)-এর আমলে পারস্যের রাজধানী মাদায়েন বিজিত হলে সম্রাট কিসরার মণিমুক্তা খচিত স্বর্ণের পোশাক, মুকুট ও চুড়ি মদিনায় এলো। উমর (রা.) ভরা মজলিসে সুরাকাকে ডেকে রাসুলের ভবিষ্যদ্বাণী বাস্তবায়ন করতে বললেন। সুরাকা কিসরার স্বর্ণের চুড়ি ও মুকুট পরলে উমর (রা.) কেঁদে ফেলে বললেন: \"সমস্ত প্রশংসা আল্লাহর যিনি কিসরা ইবনে হরমুজের হাত থেকে কেড়ে নিয়ে বনু মুদলিজের সাধারণ এক বেদুইন সুরাকার হাতে পরিয়ে দিয়েছেন!\"",
