        "textBn": "উমর (রা.) বলেছিলেন: \"হাক্কুন আলা কুল্লি মুসলিমিন আই ইয়ুকাব্বিলা রা’সা আব্দিল্লাহি বিন হুজাফাহ, ওয়া আনা আবদাউ বিহি!\" (প্রতিটি মুসলিমের দায়িত্ব আব্দুল্লাহর মাথায় চুম্বন করা, আর আমি নিজেই তা প্রথম করছি!)",
