    "deathOrMartyrdomBn": "নবুওয়াতের দশম বর্ষে মক্কায় ৬৫ বছর বয়সে ইন্তেকাল করেন। মক্কার জান্নাতুল মুয়াল্লায় রাসুলুল্লাহ (সা.) নিজ হাতে তাঁকে কবরে নামিয়ে সমাহিত করেন। তখনো জানাজার নামাজের বিধান নাজিল হয়নি।",
