        "story": "আয়েশা (রা.) অশ্রুসজল কণ্ঠে স্মৃতিচারণ করতেন: \"আল্লাহর অন্যতম শ্রেষ্ঠ নেয়ামত হলো রাসুলুল্লাহ (সা.) আমার ঘরে, আমার পালার দিনে এবং আমার চিবুক ও বুকের মাঝে মাথা রেখে ইন্তেকাল করেছেন! মৃত্যুর একটু আগে আমার ভাই আব্দুর রহমান একটি কাঁচা তাজা মেসওয়াক হাতে নিয়ে ঘরে ঢুকল। আমি দেখলাম রাসুল (সা.) সেটির দিকে বারবার তাকাচ্ছেন। আমি তাঁর মনের ইচ্ছা বুঝতে পেরে বললাম: 'আমি কি এটি আপনার জন্য নরম করে দেব?' রাসুল মাথা নেড়ে সম্মতি জানালেন। আমি মেসওয়াকটি নিজের দাঁত দিয়ে চিবিয়ে নরম করে রাসুলের মুখে দিলাম। রাসুল পরম স্বস্তিতে মেসওয়াক করলেন। এরপর আমার বুকের ওপর মাথা রেখে রাসুল হাত তুললেন এবং বললেন: 'বালির রাফিকিল আ’লা' (বরং আমি ঊর্ধ্বলোকের পরম বন্ধু আল্লাহর সান্নিধ্য চাই)। এরপর তাঁর পবিত্র হাতটি ঢলে পড়ল এবং আমার কোলেই তিনি শেষ নিঃশ্বাস ত্যাগ করলেন।\""
