    "birthAndDeathBn": "জন্ম: নবুওয়াতের ৫ম বর্ষ পূর্বে মক্কা | ওফাত: ৩ রমজান, ১১ হিজরি মদিনা (২৯ বছর)",
    "summaryBn": "রাসুলুল্লাহ (সা.)-এর কলিজার টুকরো কনিষ্ঠ কন্যা, জান্নাতবাসী সমস্ত নারীর সম্রাজ্ঞী এবং জান্নাতের যুবকদের সর্দার হাসান ও হোসাইনের মাতা; যাঁর দুঃখ-কষ্টে স্বয়ং রাসুলুল্লাহ (সা.) ব্যথিত হতেন।",
    "detailedBiographyBn": "হযরত ফাতিমা আজ-জাহরা (রা.) ছিলেন রাসুলুল্লাহ (সা.) ও খাদিজা (রা.)-এর কনিষ্ঠা ও সর্বাধিক স্নেহের কন্যা। তিনি অবয়বে, হাঁটাচলায়, কথাবার্তায় এবং চরিত্রে হুবহু রাসুলুল্লাহ (সা.)-এর প্রতিচ্ছবি ছিলেন। শৈশবেই তিনি যখন দেখতেন মক্কার কাফেররা কাবার চত্বরে সালাতরত রাসুলের পিঠে উটের পচা নাড়িভুঁড়ি চাপিয়ে দিয়েছে, তখন ছোট্ট ফাতিমা দৌড়ে এসে নিজ হাতে তা পরিষ্কার করতেন এবং কাফেরদের দিকে তাকিয়ে নির্ভীক প্রতিবাদ জানাতেন। মা খাদিজার ওফাতের পর তিনি রাসুলের এমন সেবা করতেন যে সাহাবিরা তাঁকে ডাকতেন ‘উম্মু আবিহা’ (পিতার মা)।\n\nমদিনায় হিজরতের পর ২ হিজরিতে হযরত আলী (রা.)-এর সাথে তাঁর অত্যন্ত অনাড়ম্বর বিবাহ সম্পন্ন হয়। দেনমোহর ছিল আলীর একটি বর্ম। ফাতিমা (রা.) নিজ হাতে যাঁতা পিষে আটা বানাতেন, যার কারণে তাঁর নরম হাতে কড়া পড়ে গিয়েছিল; চামড়ার মশক টেনে পানি আনতেন যার কারণে তাঁর বুকে দাগ হয়ে গিয়েছিল। তবুও তিনি কখনো অভিযোগ করেননি।\n\nরাসুলুল্লাহ (সা.) ফাতিমাকে প্রাণাধিক ভালোবাসতেন। সফরে যাওয়ার সময় সবার শেষে ফাতিমার সাথে দেখা করতেন এবং সফর থেকে ফিরে সবার আগে ফাতিমার ঘরে আসতেন। রাসুল (সা.) ঘোষণা করেছিলেন: \"ফাতিমা আমার শরীরের অংশ (বিত’আতু মিন্নী); যে তাকে কষ্ট দেয় সে যেন আমাকেই কষ্ট দেয়, আর যে তাকে সন্তুষ্ট করে সে যেন আমাকেই সন্তুষ্ট করে।\" রাসুল (সা.)-এর ওফাতের মাত্র ছয় মাস পর ১১ হিজরির ৩ রমজানে মাত্র ২৯ বছর বয়সে এই মহীয়সী মানবী পিতার সান্নিধ্যে চলে যান।",
    "islamAcceptanceBn": "রাসুল (সা.) ও খাদিজা (রা.)-এর ঘরে তাওহীদের কোলে জন্ম নিয়ে শৈশব থেকেই ইসলামের মহিমায় লালিত হন।",
