        "title": "রাসুল (সা.)-এর কানে কানে বলা সেই গোপন কথা ও ফাতিমার কান্না-হাসি",
        "story": "উম্মুল মুমিনীন আয়েশা (রা.) বর্ণনা করেন: রাসুলুল্লাহ (সা.)-এর অন্তিম রোগশয্যায় ফাতিমা এলেন। তাঁর হাঁটার ভঙ্গি ছিল হুবহু রাসুলের মতো। রাসুল (সা.) পরম ভালোবাসায় বললেন: \"মারহাবান বি-ইবনাতী!\" (স্বাগতম আমার স্নেহের কন্যা!)। এরপর রাসুল ফাতিমাকে কাছে টেনে নিয়ে কানে কানে কিছু বললেন। ফাতিমা তা শুনে ফুঁপিয়ে কেঁদে উঠলেন। রাসুল আবার তাঁকে কাছে টেনে নিয়ে কানে কানে আরেকটি কথা বললেন, এবার ফাতিমা মুচকি হেসে উঠলেন। আয়েশা (রা.) তখন এর রহস্য জানতে চাইলেন। রাসুলের ওফাতের পর ফাতিমা প্রকাশ করলেন: \"রাসুল প্রথমবার কানে বলেছিলেন—জিবরাইল প্রতি বছর আমার সাথে একবার কুরআন পুনরাবৃত্তি করতেন, কিন্তু এই বছর তিনি দুইবার করেছেন; এতে আমি বুঝতে পারছি আমার বিদায়ের সময় এসে গেছে। এ কথা শুনে আমি শোকের কান্নায় ভেঙে পড়েছিলাম। এরপর রাসুল আমাকে সান্ত্বনা দিয়ে বললেন—আমার পরিবারের মধ্যে তুমিই সবার আগে আমার সাথে এসে মিলিত হবে এবং তুমি কি খুশি নও যে তুমি জান্নাতের সমস্ত নারীদের সর্দার হবে? এ শুনে আমি আনন্দে হেসে ফেলেছিলাম!\""
