    "nameAr": "أسماء بنت أبي بكر رضي الله عنهما",
    "titleBn": "জাতুন নিতাকাইন (দুই কোমরবন্ধের অধিকারিণী), বীরমাতা",
    "categoryKey": "sahabiyyat",
    "categoryBn": "মহীয়সী নারী সাহাবি ও উম্মাহাতুল মুমিনীন (#৫২)",
    "birthAndDeathBn": "জন্ম: মক্কা | ওফাত: ৭৩ হিজরি মক্কা (১০০ বছর)",
    "summaryBn": "আবু বকর (রা.)-এর জ্যেষ্ঠা কন্যা ও আয়েশা (রা.)-এর বড় বোন; হিজরতের রাতে যিনি নিজের কোমরবন্ধ ছিঁড়ে দুই টুকরো করে রাসুল (সা.)-এর খাবার বেঁধে দিয়ে ‘জাতুন নিতাকাইন’ উপাধি পান এবং ১০০ বছর বয়সেও পূর্ণ দৃষ্টি ও দাঁত অক্ষুণ্ণ রেখে পুত্রের শাহাদাতে বীরত্ব প্রদর্শন করেন।",
    "detailedBiographyBn": "হযরত আসমা বিনতে আবি বকর (রা.) ছিলেন ইসলামের প্রথম সারির অন্যতম সাহসী নারী। তিনি যুবায়ের ইবনুল আওয়াম (রা.)-এর স্ত্রী এবং আব্দুল্লাহ ইবনুল জুবায়ের (রা.)-এর মা ছিলেন।\n\nহিজরতের সংকটময় রাতে রাসুল (সা.) ও আবু বকর (রা.) যখন সাওর গুহায় লুকিয়ে ছিলেন, তখন আসমা রাতের আঁধারে মক্কার দুর্গম পাহাড় বেয়ে গোপনে তাঁদের খাবার ও পানি পৌঁছে দিতেন। খাবার বাঁধার জন্য কোনো রশি না পেয়ে তিনি নিজের কোমরের বন্ধনী (নিতাক) খুলে দুই টুকরো করেন—এক টুকরো দিয়ে খাবারের থলে বাঁধেন এবং অপর টুকরো দিয়ে নিজের কোমর বাঁধেন। রাসুল (সা.) এই অনন্য বুদ্ধি ও নিষ্ঠা দেখে দোয়া করলেন: \"আল্লাহ তাআলা এর পরিবর্তে জান্নাতে তোমাকে দুটি নূরের কোমরবন্ধ দান করবেন!\" সেদিন থেকেই তিনি ‘জাতুন নিতাকাইন’ খেতাবে ভূষিত হন।\n\nআবু জাহেল ক্ষিপ্ত হয়ে সাওর গুহার সন্ধানে আবু বকরের ঘরে এসে আসমার গালে এমন জোরে থাপ্পড় মেরেছিল যে তাঁর কানের দুল ছিটকে পড়েছিল, তবুও তিনি রাসুলের ঠিকানা প্রকাশ করেননি। মদিনায় হিজরতের পর তিনিই প্রথম মুহাজির যিনি মদিনার মাটিতে প্রথম সন্তান আব্দুল্লাহ ইবনুল জুবায়েরকে জন্ম দেন, যা ইহুদিদের জাদুবিদ্যাকে মিথ্যা প্রমাণ করে মুসলিমদের আনন্দিত করেছিল। ৭৩ হিজরিতে যখন হাজ্জাজ বিন ইউসুফ মক্কায় কাবা শরিফে অবরোধ করে তাঁর পুত্র আব্দুল্লাহকে হত্যার হুমকি দেয়, তখন শতবর্ষী অন্ধ আসমা পুত্রকে বলেন: \"বাবা! সম্মানের সাথে লড়াই করে শহীদ হও, কিন্তু জালেমের কাছে কখনো আত্মসমর্পণ করো না!\"",
    "islamAcceptanceBn": "পিতা আবু বকরের ইসলাম গ্রহণের প্রথম দিনগুলোতেই শৈশবে ইসলাম গ্রহণ করেন।",
    "keyVirtuesBn": [
      "রাসুলুল্লাহ (সা.) কর্তৃক জান্নাতি উপাধি \"জাতুন নিতাকাইন\" (দুই কোমরবন্ধের অধিকারিণী) লাভ।",
      "হিজরতের চরম বিপজ্জনক সময়ে প্রাণ বাজি রেখে সাওর গুহায় খাদ্য সরবরাহকারী অতন্দ্র প্রহরী।",
      "১০০ বছর বয়সেও একটি দাঁতও না পড়া এবং মস্তিষ্কের পূর্ণ প্রখরতা বজায় থাকার মোজেজা।"
    ],
    "emotionalStoriesBn": [
      {
        "title": "অন্ধ মাতার সামনে পুত্রের শেষ বিদায় ও বর্ম খুলে ফেলা",
        "story": "মক্কায় হাজ্জাজের বিশাল বাহিনীর বিরুদ্ধে লড়াইয়ের শেষ সকালে আব্দুল্লাহ ইবনুল জুবায়ের তাঁর শতবর্ষী অন্ধ মা আসমার কাছে দোয়ার জন্য এলেন। আসমা পুত্রকে বুকে জড়িয়ে ধরে আদর করতে গিয়ে অনুভব করলেন যে পুত্রের গায়ে লোহার শক্ত বর্ম পরা রয়েছে। আসমা (রা.) বললেন: \"বাবা! এটা কী পরেছ? যে ব্যক্তি আল্লাহর রাস্তায় শাহাদাত অন্বেষণ করে সে কখনো এমন বর্ম পরে না! এটা খুলে ফেলো এবং হালকা পোশাকে ময়দানে নামো যাতে শত্রুকে আঘাত করতে কোনো বাধা না হয়!\" আব্দুল্লাহ বর্ম খুলে ফেললেন এবং মায়ের কপালে চুম্বন করে বললেন: \"মা! আমি ভয় পাচ্ছিলাম আমার মৃত্যুর পর ওরা আমার লাশ কেটে বিকৃত করবে।\" আসমা বীরদর্পে বললেন: \"ছাগলকে জবেহ করার পর তার চামড়া ছিলা হলে ছাগলের কোনো ব্যথা লাগে না! যাও বাবা, মাথা উঁচু করে বীরের মতো লড়াই করো!\" আব্দুল্লাহ শহীদ হলেন এবং হাজ্জাজ তাঁর লাশ শূলে চড়ালো। আসমা সেই লাশের সামনে দাঁড়িয়ে হাজ্জাজকে চরম ভর্ৎসনা করে আল্লাহর দরবারে শোকর আদায় করলেন।"
      }
    ],
