    "deathOrMartyrdomBn": "৭৩ হিজরিতে পুত্র আব্দুল্লাহ ইবনুল জুবায়েরের শাহাদাতের মাত্র কয়েকদিন পর ১০০ বছর বয়সে মক্কায় ইন্তেকাল করেন।",
