    "nameAr": "نسيبة بنت كعب رضي الله عنها",
    "titleBn": "উম্মে আম্মারা, উহুদের অকুতোভয় বীরাঙ্গনা মুজাহিদা",
    "categoryKey": "sahabiyyat",
    "categoryBn": "মহীয়সী নারী সাহাবি ও উম্মাহাতুল মুমিনীন (#৫৩)",
    "birthAndDeathBn": "জন্ম: মদিনা | ওফাত: ১৩ হিজরি মদিনা",
    "summaryBn": "উহুদের রক্তঝরা প্রান্তরে তলোয়ার ও ধনুক হাতে একাকী বুক চিতিয়ে রাসুলুল্লাহ (সা.)-কে রক্ষাকারী বীরাঙ্গনা সাহাবি; যাঁর ব্যাপারে রাসুল (সা.) বলেছিলেন: \"উহুদের দিন আমি ডানে কিংবা বামে যেদিকেই তাকিয়েছি, কেবল উম্মে আম্মারাকেই আমার প্রতিরক্ষায় যুদ্ধ করতে দেখেছি!\"",
    "detailedBiographyBn": "হযরত নুসাইবাহ বিনতে কা’ব (রা.) ছিলেন মদিনার খাযরাজ গোত্রের বনু নাজ্জার শাখার এক মহীয়সী নারী। তিনি আকাবার দ্বিতীয় শপথে উপস্থিত যে দুজন মাত্র নারী রাসুলুল্লাহ (সা.)-এর হাতে আনুগত্যের বাইয়াত গ্রহণ করেছিলেন, নুসাইবাহ ছিলেন তাঁদের অন্যতম।\n\n৩ হিজরির উহুদ যুদ্ধে তিনি শুরুতে আহত মুজাহিদদের পানি পান করানো ও ব্যান্ডেজ বাঁধার জন্য এসেছিলেন। কিন্তু যুদ্ধের এক পর্যায়ে যখন মুসলিম বাহিনী বিশৃঙ্খল হয়ে পড়ল এবং কাফেররা রাসুল (সা.)-কে হত্যা করতে ঘিরে ধরল, তখন নুসাইবাহ পানির পাত্র ফেলে দিয়ে খোলা তলোয়ার ও ধনুক হাতে তুলে নেন। তিনি তাঁর স্বামী ও দুই পুত্রকে নিয়ে রাসুল (সা.)-এর চারপাশে মানব প্রাচীর তৈরি করেন। কাফের অশ্বারোহী ইবনে কামিয়া যখন রাসুলকে হত্যার জন্য চিৎকার করে ধেয়ে আসছিল, নুসাইবাহ বুক চিতিয়ে তার সামনে দাঁড়ান এবং তলোয়ারের মুখোমুখি হন। ইবনে কামিয়ার তলোয়ারের আঘাতে তাঁর কাঁধে গভীর ক্ষত তৈরি হয় যেখান থেকে ফোয়ারার মতো রক্ত ঝরছিল। কিন্তু নুসাইবাহ নিজের ক্ষতের পরোয়া না করে উল্টো তার ওপর তলোয়ারের আঘাত হানেন। সেদিন তাঁর শরীরে ১২টি তরবারি ও বর্শার আঘাত লেগেছিল।\n\nরাসুলুল্লাহ (সা.) তাঁর এই অসাধারণ আত্মত্যাগ দেখে আবেগাপ্লুত হয়ে দোয়া করেছিলেন: \"হে আল্লাহ! এদেরকে জান্নাতে আমার সঙ্গী বানিয়ে দিন!\" নুসাইবাহ তখন চিৎকার করে বলেছিলেন: \"এরপর দুনিয়ার আর কোনো বিপদেরই আমি পরোয়া করি না!\" ১২ হিজরিতে ইয়ামামার যুদ্ধে ভণ্ড নবি মুসায়লামার বিরুদ্ধে লড়াইয়ে তিনি এক হাত হারিয়েছিলেন এবং ১১টি ক্ষত নিয়ে বিজয়ী হয়েছিলেন।",
    "islamAcceptanceBn": "আকাবার দ্বিতীয় শপথে মদিনার মাত্র দুজন নারীর একজন হয়ে রাসুল (সা.)-এর হাতে ইসলাম গ্রহণ করেন।",
