        "title": "উহুদের রক্তক্ষরণ ও রাসুল (সা.)-এর দোয়া",
        "story": "উহুদের যুদ্ধে নুসাইবাহর কাঁধ থেকে যখন রক্ত বইছিল, রাসুলুল্লাহ (সা.) তাঁর পুত্র আব্দুল্লাহকে ডেকে বললেন: \"তোমার মায়ের ব্যান্ডেজ বাঁধো! তোমাদের এই পরিবারের ওপর আল্লাহর বরকত নাজিল হোক!\" নুসাইবাহ রক্তমাখা অবস্থাতেই বললেন: \"হে আল্লাহর রাসুল! আল্লাহর কাছে দোয়া করুন যেন জান্নাতে আমরা আপনার সঙ্গী হতে পারি!\" রাসুলুল্লাহ (সা.) তখনই দুহাত তুলে দোয়া করলেন: \"হে আল্লাহ! এদেরকে জান্নাতে আমার সঙ্গী বানিয়ে দিন!\" নুসাইবাহ (রা.) চিৎকার করে বললেন: \"আল্লাহর কসম! এই দোয়ার পর দুনিয়ায় আমার সাথে যা-ই ঘটুক না কেন, আমি আর কোনো কিছুরই পরোয়া করি না!\""
