    "birthAndDeathBn": "জন্ম: মক্কা | ওফাত: ৪৫ হিজরি মদিনা (৬০ বছর)",
    "summaryBn": "উমর ফারুক (রা.)-এর বিদুষী কন্যা ও উম্মুল মুমিনীন; যাঁর আমানতে আবু বকর ও উমরের সংকলিত মূল ঐতিহাসিক পবিত্র কুরআন সংরক্ষিত ছিল এবং যাঁর তাকওয়া দেখে জিবরাইল (আ.) বলেছিলেন: \"হাফসা জান্নাতে রাসুলের স্ত্রী!\"",
    "detailedBiographyBn": "হযরত হাফসা বিনতে উমর (রা.) ছিলেন খলিফা উমর ইবনুল খাত্তাব (রা.)-এর কন্যা। তিনি শৈশবেই পিতার সাথে ইসলাম গ্রহণ করেন এবং খুনাইস ইবনে হুযাফার সাথে বিবাহিত হন। বদর যুদ্ধে তাঁর স্বামী মারাত্মক আহত হয়ে পরবর্তীতে মদিনায় শহীদ হন। মাত্র ১৮-১৯ বছর বয়সে হাফসা বিধবা হন।\n\nউমর (রা.) মেয়ের অভিভাবকত্ব নিয়ে চিন্তিত হয়ে প্রথমে উসমান এবং পরে আবু বকর (রা.)-কে হাফসার বিবাহের প্রস্তাব দেন। কিন্তু রাসুলুল্লাহ (সা.) স্বয়ং উমরকে সুসংবাদ দিয়ে বলেন: \"হাফসা এমন স্বামী পাবে যে উসমানের চেয়ে উত্তম, আর উসমান এমন স্ত্রী পাবে যে হাফসার চেয়ে উত্তম!\" ৩ হিজরিতে রাসুলুল্লাহ (সা.) স্বয়ং হাফসাকে বিবাহ করে উম্মুল মুমিনীনদের কাতারে শামিল করেন।\n\nহাফসা (রা.) ছিলেন অত্যন্ত জ্ঞানবতী, শিক্ষিতা ও ইবাদতগুজার। তিনি কুরআন লিখতে ও পড়তে জানতেন। রাসুলুল্লাহ (সা.)-এর ওফাতের পর খলিফা আবু বকর (রা.) যখন পবিত্র কুরআনকে সংকলন করে একটি প্রামাণিক মুসহাফ তৈরি করেন, সেই মূল কপিটি আবু বকরের ওফাতের পর উমরের কাছে আসে এবং উমরের শাহাদাতের পর তা উম্মুল মুমিনীন হাফসার কাছে সযত্নে গচ্ছিত থাকে। পরবর্তীতে খলিফা উসমান (রা.) হাফসার কাছ থেকেই সেই মূল মুসহাফ চেয়ে নিয়ে অনুলিপি তৈরি করে সারা বিশ্বে ছড়িয়ে দেন।",
    "islamAcceptanceBn": "পিতা উমরের সাথেই বাল্যকালে মক্কায় ইসলাম গ্রহণ করেন এবং মদিনায় হিজরত করেন।",
