        "story": "একবার পারিবারিক এক মান-অভিমানের ঘটনায় রাসুলুল্লাহ (সা.) হাফসাকে এক তালাক দেওয়ার ইচ্ছা পোষণ করলেন। সাথে সাথে জিবরাইল (আ.) আসমান থেকে ওহী নিয়ে অবতীর্ণ হলেন। জিবরাইল (আ.) বললেন: \"হে আল্লাহর রাসুল! হাফসাকে ফিরিয়ে নিন! কারণ সে দিনে প্রচণ্ড রোজা পালনকারিণী (সাওওয়ামাহ) এবং রাতে দীর্ঘ তাহাজ্জুদ আদায়কারিণী (ক্বাওয়াওমাহ)! এবং সে জান্নাতেও আপনার প্রিয়তমা স্ত্রী!\" রাসুল (সা.) তৎক্ষণাৎ হাফসাকে ফিরিয়ে নিলেন।"
