    "birthAndDeathBn": "জন্ম: মক্কা | ওফাত: ১৪ হিজরি মদিনা",
    "summaryBn": "আবু সুফিয়ানের স্ত্রী ও আমীর মুয়াবিয়ার মাতা; যিনি অতীতে উহুদের যুদ্ধে বীর হামজার দেহ ক্ষতবিক্ষত করেছিলেন, কিন্তু মক্কা বিজয়ে খাঁটি অন্তরে ইসলাম গ্রহণ করে ইয়ারমুকের প্রান্তরে তাবু উপড়ে রোমানদের বিরুদ্ধে দাঁড়িয়েছিলেন।",
    "detailedBiographyBn": "হযরত হিন্দ বিনতে উৎবাহ (রা.) ছিলেন মক্কার শীর্ষ কুরাইশ নেতা উৎবাহ ইবনে রাবিয়ার কন্যা এবং কুরাইশ প্রধান আবু সুফিয়ানের স্ত্রী। বদর যুদ্ধে তাঁর পিতা, ভাই ও চাচা নিহত হওয়ায় তিনি প্রতিশোধে উন্মাদ হয়ে পড়েন এবং উহুদ যুদ্ধে হাবশি দাস ওয়াহশিকে দিয়ে রাসুলের চাচা হামজা (রা.)-কে হত্যা করান এবং চরম ক্ষোভে হামজার কলিজা চিবিয়েছিলেন।\n\nকিন্তু ৮ হিজরিতে মক্কা বিজয়ের দিন রাসুলুল্লাহ (সা.) যখন সাধারণ ক্ষমা ঘোষণা করলেন, তখন হিন্দের হৃদয় বিগলিত হলো। তিনি বোরকা ও নেকাব পরে অন্য নারীদের সাথে রাসুল (সা.)-এর দরবারে বায়াত নিতে এলেন। রাসুল যখন নারীদের শর্ত দিলেন—\"তোমরা চুরি করবে না\", হিন্দ বলে উঠলেন: \"হে আল্লাহর রাসুল! আবু সুফিয়ান তো কৃপণ মানুষ, আমি কি তার না বলে খরচ করতে পারব?\" রাসুল মুচকি হেসে বললেন: \"তুমি কি হিন্দ?\" তিনি বললেন: \"হ্যাঁ, আমি হিন্দ! অতীতকে ক্ষমা করে দিন, আল্লাহ আপনাকে ক্ষমা করবেন!\" রাসুল তাঁকে সানন্দে ক্ষমা করলেন।\n\nইসলাম গ্রহণের পর হিন্দের জীবন সম্পূর্ণ পরিবর্তিত হয়ে যায়। ঘরে ফিরে নিজের সমস্ত মূর্তি তিনি কুড়াল দিয়ে ভেঙে টুকরো টুকরো করে বলেন: \"তোদের কারণে এতদিন আমরা পথভ্রষ্ট ছিলাম!\" ১৫ হিজরিতে ইয়ারমুকের যুদ্ধে তিনি নারীদের নিয়ে যুদ্ধক্ষেত্রের ঠিক পেছনে অবস্থান নেন। যখনই কোনো মুসলিম সেনা রোমানদের ভয়ে পিছিয়ে আসতে চাইত, হিন্দ তাঁবুর খুঁটি তুলে তাদের মুখে আঘাত করে চিৎকার করে বলতেন: \"কোথায় পালাচ্ছ? তোমরা কি নিজেদের স্ত্রীদের রোমান কাফেরদের হাতে তুলে দিতে চাও? ফিরে যাও ময়দানে!\" তাঁর এই গর্জনে মুসলিম মুজাহিদরা পুনরায় সিংহের মতো ময়দানে ঝাঁপিয়ে পড়ে ঐতিহাসিক বিজয় ছিনিয়ে আনেন।",
    "islamAcceptanceBn": "৮ হিজরিতে মক্কা বিজয়ের দিন রাসুলুল্লাহ (সা.)-এর হাতে বোরকা পরে এসে খাঁটি অন্তরে তাওহীদের বাইয়াত গ্রহণ করেন।",
