    "birthAndDeathBn": "জন্ম: নজদ | ওফাত: ৬৮ হিজরি কুফা (১২০ বছর)",
    "summaryBn": "আরবের কিংবদন্তি দানবীর হাতেম তাঈর সুযোগ্য পুত্র ও খ্রিস্টান গোত্রপ্রধান; যিনি রাসুলুল্লাহ (সা.)-এর দারিদ্র্য ও বাদশাহহীন বিনম্র চালচলন দেখে ইসলাম গ্রহণ করেছিলেন এবং যার সামনে রাসুলের তিনটি ভবিষ্যৎবাণী সত্য হয়েছিল।",
    "detailedBiographyBn": "হযরত আদি ইবনে হাতিম (রা.) ছিলেন আরবের প্রবাদপুরুষ দানবীর হাতেম তাঈর জ্যেষ্ঠ পুত্র। তিনি পিতা ও গোত্রের ঐতিহ্যানুযায়ী তাইয়ি গোত্রের সর্দার এবং খ্রিস্টান ধর্মের অনুসারী ছিলেন। মুসলিম বাহিনী যখন তাঁর এলাকা জয় করে, তিনি প্রাণভয়ে শামে পালিয়ে যান। কিন্তু তাঁর বোন সুফানা বন্দি হওয়ার পর রাসুলুল্লাহ (সা.)-এর পরম সদাচরণ দেখে মুগ্ধ হয়ে ইসলাম গ্রহণ করেন এবং শামে গিয়ে ভাইকে রাসুলের দরবারে যাওয়ার অনুরোধ করেন।\n\n৯ হিজরিতে আদি মদিনায় রাসুল (সা.)-এর দরবারে এলেন। রাসুলুল্লাহ (সা.) এই খ্রিস্টান সর্দারকে দেখে সম্মান জানিয়ে নিজ ঘরে নিয়ে গেলেন। ঘরে বসার মতো একটি মাত্র খেজুরের পাতার গদিওয়ালা কুশন ছিল। রাসুল (সা.) সেই কুশনটি আদিকে বসতে দিয়ে নিজে মাটির মেঝেতে বসলেন। আদি মনে মনে বললেন: \"আল্লাহর কসম! এটা কোনো পার্থিব রাজার চালচলন নয়, ইনি নিশ্চয়ই সত্য নবি!\"\n\nরাসুল (সা.) আদিকে বললেন: \"হে আদি! হয়তো তুমি ভাবছ মুসলিমরা বড় দরিদ্র আর দুর্বল, তাই ইসলামে আসছ না? আল্লাহর কসম! অচিরেই এমন দিন আসবে যখন একজন একা নারী কাদিসিয়া থেকে উটে চড়ে একাকী মক্কায় কাবা তাওয়াফ করতে আসবে, আল্লাহ ছাড়া সে আর কাউকে ভয় পাবে না! এমন দিন আসবে যখন পারস্য সম্রাট কিসরার সমস্ত রাজকোষ উন্মুক্ত করে মুসলিমরা জয় করবে! আর এমন দিন আসবে যখন মানুষ এক থলে স্বর্ণ নিয়ে রাস্তায় রাস্তায় ঘুরে বেড়াবে সদকা দেওয়ার জন্য, কিন্তু তা নেওয়ার মতো একজন অভাবী মানুষও খুঁজে পাওয়া যাবে না!\" আদি ইসলাম গ্রহণ করেন এবং দীর্ঘ ১২০ বছর বেঁচে থেকে রাসুলের এই তিনটি ভবিষ্যদ্বাণীর প্রতিটি নিজের চোখে প্রত্যক্ষ করেছিলেন। কাদিসিয়া ও নাহাওয়ান্দে তিনি অসামান্য বীরত্ব প্রদর্শন করেন।",
    "islamAcceptanceBn": "৯ হিজরিতে মদিনায় এসে রাসুলুল্লাহ (সা.)-এর অনাড়ম্বর জীবনযাপন ও নবুওয়াতের নিদর্শন প্রত্যক্ষ করে ইসলাম গ্রহণ করেন।",
