    "nameAr": "كعب بن مالك رضي الله عنه",
    "titleBn": "শায়েরু আনসার, তওবা কবুল হওয়া সৌভাগ্যবান সাহাবি",
    "categoryKey": "ansar",
    "categoryBn": "আনসার সাহাবি ও সহযোগী (#৫৭)",
    "birthAndDeathBn": "জন্ম: মদিনা | ওফাত: ৫০ হিজরি মদিনা (৭৭ বছর)",
    "summaryBn": "মদিনার কবি ও আকাবার বীর, যিনি কোনো ওজর ছাড়াই শুধু আলস্যের কারণে তাবুক যুদ্ধে যাওয়া থেকে পিছিয়ে পড়েছিলেন; কিন্তু মিথ্যার আশ্রয় না নিয়ে সত্য কথা বলে ৫০ দিন একঘরে থাকার পর স্বয়ং আল্লাহ কুরআনের আয়াত নাজিল করে যাঁর তওবা কবুল করেছিলেন।",
    "detailedBiographyBn": "হযরত কা’ব ইবনে মালিক আল-আনসারী (রা.) ছিলেন মদিনার অন্যতম শীর্ষ কবি ও যোদ্ধা। তিনি আকাবার দ্বিতীয় শপথে ইসলাম গ্রহণ করেন এবং বদর ছাড়া উহুদসহ সমস্ত যুদ্ধে অংশ নেন। উহুদে তিনি ১৭টি আঘাত সহ্য করেছিলেন।\n\n৯ হিজরির তীব্র গরমে যখন তাবুক যুদ্ধের ডাক এলো, কা’ব ছিলেন তাঁর জীবনের সবচেয়ে সচ্ছল অবস্থায়। তাঁর কাছে দুটি দ্রুতগামী সওয়ারী ছিল। কিন্তু তিনি \"আজ যাব, কাল যাব\" করতে করতে আলস্যের কারণে রাসুল (সা.)-এর কাফেলা থেকে পিছিয়ে পড়েন। যুদ্ধ শেষে রাসুল (সা.) যখন মদিনায় ফিরলেন, মুনাফিকরা মিথ্যা শপথ ও ওজর দেখিয়ে রাসুলের কাছ থেকে ক্ষমা চেয়ে নিল। কিন্তু কা’ব এসে রাসুলকে সোজাসুজি বললেন: \"হে আল্লাহর রাসুল! আল্লাহর কসম, আমি যদি দুনিয়ার অন্য কোনো বাদশাহর সামনে বসতাম, তবে মিথ্যা কথা বানিয়ে নিজেকে রক্ষা করতাম। কারণ আমি অত্যন্ত বাকপটু। কিন্তু আমি জানি আজ যদি মিথ্যা বলে আপনাকে খুশি করি, আল্লাহ অচিরেই আপনার মনে আমার প্রতি অসন্তুষ্টি তৈরি করবেন। আর যদি আজ সত্য বলে আপনার কাছে অসন্তুষ্টির মুখোমুখি হই, তবে আল্লাহর কাছে মাগফিরাতের আশা রাখি। আল্লাহর কসম! আমার কোনো ওজর ছিল না, আমি সম্পূর্ণ সচ্ছল ও সুস্থ ছিলাম!\"\n\nরাসুল (সা.) বললেন: \"এই লোকটি সত্য কথা বলেছে। তুমি যাও, যতক্ষণ না আল্লাহ তোমার ব্যাপারে ফয়সালা দেন।\" রাসুল সমস্ত সাহাবিকে কা’ব এবং আরও দুজনের সাথে কথা বলা সম্পূর্ণ নিষিদ্ধ করলেন। টানা ৫০ দিন পুরো মদিনায় তাঁদের সাথে কেউ একটি কথাও বলেনি। জমিন প্রশস্ত হওয়া সত্ত্বেও তাঁদের জন্য সংকীর্ণ হয়ে গিয়েছিল। ৫০তম দিন ফজরের নামাজের পর সালা পর্বতের চূড়া থেকে এক ঘোষণাকারীর আওয়াজ ভেসে এলো: \"হে কা’ব ইবনে মালিক! সুসংবাদ গ্রহণ করো!\" স্বয়ং আল্লাহ তাআলা তাঁদের সত্যবাদিতার সম্মানে সূরা তাওবার ১১৮ নম্বর আয়াত নাজিল করে তাঁদের তওবা কবুল হওয়ার ঘোষণা দেন।",
    "islamAcceptanceBn": "আকাবার দ্বিতীয় শপথে ইসলাম গ্রহণ করেন এবং উহুদে রাসুলের বর্ম পরে কাফেরদের দৃষ্টি বিভ্রান্ত করেন।",
