    "categoryKey": "ansar",
    "categoryBn": "আনসার সাহাবি ও সহযোগী (#৫৮)",
    "birthAndDeathBn": "জন্ম: মদিনা | ওফাত: ৬০ হিজরি মদিনা",
    "summaryBn": "সা’দ ইবনে উবাদাহর সুযোগ্য পুত্র, যাঁর বুদ্ধি ও রণকৌশল সম্পর্কে বলা হতো \"ইসলাম যদি প্রতারণামূলক কৌশলকে নিষেধ না করত, তবে কায়েস হতো আরবের সবচেয়ে বড় কূটকৌশলী\"; যিনি রাসুলের সার্বক্ষণিক দেহরক্ষী ও মিশরের দূরদর্শী গভর্নর ছিলেন।",
    "detailedBiographyBn": "হযরত কায়েস ইবনে সা’দ (রা.) ছিলেন মদিনার খাযরাজ গোত্রের প্রধান সা’দ ইবনে উবাদার পুত্র। তিনি ছিলেন অত্যন্ত দীর্ঘদেহী, সুদর্শন ও নির্ভীক তরুণ। রাসুলুল্লাহ (সা.) মদিনায় এলে সা’দ তাঁর পুত্র কায়েসকে রাসুলের হাতে তুলে দিয়ে বলেছিলেন: \"হে আল্লাহর রাসুল! কায়েস আপনার আজীবনের খাদেম হয়ে থাকবে।\" রাসুলের কাছে তাঁর অবস্থান ছিল কোনো সেনাপতির প্রধান নিরাপত্তা কমান্ডারের মতো।\n\nকায়েস ছিলেন পিতার মতোই এক অতুলনীয় দানবীর। মদিনায় একবার দুর্ভিক্ষ দেখা দিলে তিনি অভাবী লোকদের বিপুল অর্থ ঋণ দেন। পরবর্তীতে যখন এক ঋণগ্রহীতা টাকা ফেরত দিতে এলো, কায়েস বললেন: \"আমরা যা আল্লাহর রাস্তায় বা মানুষকে দিই, তা কখনো ফেরত নিই না!\"\n\nতিনি ছিলেন অসাধারণ প্রজ্ঞাবান ও কৌশলী। তিনি বলতেন: \"যদি রাসুলুল্লাহ (সা.)-কে বলতে না শুনতাম যে ছলচাতুরী মানুষকে জাহান্নামে নিয়ে যায়, তবে আরবের কেউ আমাকে বুদ্ধিতে হারাতে পারত না!\" আলী (রা.)-এর খেলাফতকালে তিনি মিশরের গভর্নর নিযুক্ত হন এবং কোনো রক্তপাত ছাড়াই মিশরকে নিয়ন্ত্রণে রাখেন। পরবর্তীতে সিফফিনের যুদ্ধে তিনি আলীর পক্ষে বীরবিক্রমে লড়াই করেন। আলী (রা.)-এর শাহাদাতের পর হাসান (রা.) যখন উম্মাহর রক্তপাত বন্ধে মুয়াবিয়া (রা.)-এর সাথে সন্ধি করেন, কায়েসও উম্মাহর ঐক্যের স্বার্থে নিজের সেনাবাহিনীকে নিয়ে শান্তিতে শামিল হন।",
    "islamAcceptanceBn": "পিতার সাথে শৈশবেই রাসুলুল্লাহ (সা.)-এর পবিত্র দরবারে এসে ইসলাম গ্রহণ করেন।",
