    "emotionalStoriesBn": [
      {
        "title": "অসুস্থতায় মানুষের না আসার কারণ ও কায়েসের দান",
        "story": "একবার কায়েস অসুস্থ হয়ে বিছানায় পড়ে রইলেন। কিন্তু লক্ষ্য করলেন মদিনার মানুষেরা তাঁকে দেখতে খুব কম আসছে। তিনি কারণ জানতে চাইলে এক সাথি বললেন: \"হে কায়েস! মদিনার প্রায় প্রতিটি মানুষ আপনার কাছ থেকে ঋণ নিয়েছে। তারা আপনার কাছে আসতে লজ্জা পাচ্ছে পাছে আপনি ঋণের টাকা চেয়ে বসেন!\" এ কথা শোনামাত্র কায়েস কেঁদে ফেলে বললেন: \"এমন ধনের মুখে ছাই যা ভাইদের সাক্ষাতের মাঝে প্রাচীর তৈরি করে!\" এরপর তিনি তৎক্ষণাৎ মদিনার বাজারে লোক পাঠিয়ে ঘোষণা করালেন: \"কায়েসের কাছে যার যত ঋণ রয়েছে, সে সম্পূর্ণ মুক্ত! কায়েস কাউকে একটি পয়সাও ফেরত দিতে হবে না!\" এই ঘোষণার পর সেদিন মদিনার মানুষেরা এত বেশি তাঁকে দেখতে ছুটে এসেছিল যে তাঁর ঘরের দরজার চৌকাঠ ভেঙে গিয়েছিল।"
      }
    ],
