    "birthAndDeathBn": "জন্ম: ৬০২ খ্রি. মক্কা | ওফাত: ৬০ হিজরি দামেশক (৭৮ বছর)",
    "summaryBn": "রাসুলুল্লাহ (সা.)-এর পবিত্র ওহী লেখক সাহাবি, ইসলামের ইতিহাসের সর্বপ্রথম নৌবাহিনীর স্বপ্নদ্রষ্টা ও প্রতিষ্ঠাতা; যাঁর ২০ বছরের শাসনামলে ইসলামি সাম্রাজ্য পশ্চিমে আটলান্টিক মহাসাগর থেকে পূর্বে সিন্ধু ও চীন সীমান্ত পর্যন্ত বিস্তার লাভ করেছিল।",
    "detailedBiographyBn": "হযরত মুয়াবিয়া (রা.) ছিলেন মক্কার কুরাইশ সর্দার আবু সুফিয়ান ও হিন্দের পুত্র এবং উম্মুল মুমিনীন উম্মে হাবিবা (রা.)-এর ভাই। ৮ হিজরিতে মক্কা বিজয়ের সময় তিনি প্রকাশ্যে ইসলাম গ্রহণ করেন, যদিও তিনি হুদায়বিয়ার সন্ধির সময় থেকেই গোপনে অন্তরে ইসলাম লালন করতেন।\n\nতিনি অত্যন্ত সুশিক্ষিত ও সুন্দর হস্তাক্ষরের অধিকারী ছিলেন। রাসুলুল্লাহ (সা.) তাঁকে দরবারে ডেকে ওহী লিপিবদ্ধ করার সম্মানিত দায়িত্ব অর্পণ করেন। রাসুল (সা.) তাঁর জন্য দোয়া করেছিলেন: \"হে আল্লাহ! মুয়াবিয়াকে কিতাব ও গণিতের জ্ঞান দিন এবং তাকে শাস্তি থেকে রক্ষা করুন!\"\n\nখলিফা উমর (রা.)-এর আমলে তিনি সমগ্র সিরিয়ার গভর্নর নিযুক্ত হন। তিনি রোমানদের বিরুদ্ধে ভূমধ্যসাগরে ইসলামের ইতিহাসের সর্বপ্রথম নৌবহর গঠন করেন এবং সাইপ্রাস ও রোডস দ্বীপ জয় করেন। খলিফা আলীর সাথে ঐতিহাসিক রাজনৈতিক সংঘাতের পর ৬০ হিজরি পর্যন্ত তিনি প্রায় ২০ বছর ইসলামি খেলাফতের খলিফা হিসেবে শাসন করেন। তাঁর সময়ে ইসলামি ডাক বিভাগ, প্রশাসনিক নথিপত্র দফতর এবং সুবিশাল নৌবাহিনী গড়ে ওঠে। তাঁর ধৈর্য, সহনশীলতা ও কূটনীতি ইতিহাসে ‘হিলমে মুয়াবিয়া’ (মুয়াবিয়ার সহনশীলতা) নামে বিখ্যাত ছিল।",
    "islamAcceptanceBn": "মক্কা বিজয়ের দিনে পিতা আবু সুফিয়ানের সাথে রাসুলের দরবারে এসে ইসলাম গ্রহণ করেন এবং ওহী লেখক নিযুক্ত হন।",
