        "story": "৬০ হিজরিতে দামেশকে মৃত্যুশয্যায় শুয়ে মুয়াবিয়া (রা.) একান্তে তাঁর পরিবারের লোকদের ডেকে একটি ছোট বাক্স খুলতে বললেন। সেই বাক্সে সযত্নে রাখা ছিল রাসুলুল্লাহ (সা.)-এর একটি বরকতময় চাদর এবং রাসুলের কিছু চুল ও নখ মোবারক। মুয়াবিয়া অশ্রুসজল কণ্ঠে অসিয়ত করলেন: \"যখন আমার প্রাণ বের হয়ে যাবে, তখন রাসুলের এই চাদরটি দিয়ে আমার দেহ কাফন পরাবে। আর রাসুলের এই চুল ও নখ মোবারকগুলো গুঁড়ো করে আমার চোখ, মুখ ও সিজদার অঙ্গগুলোতে লাগিয়ে দেবে! এরপর আমাকে আরশে আজিমের পরম করুণাময় রবের করুণার ওপর ছেড়ে দেবে!\""
