    "detailedBiographyBn": "হযরত হাসান ইবনে আলী (রা.) ছিলেন হযরত আলী (রা.) ও সাইয়্যিদাতু নিসায়িল আলামিন ফাতিমা (রা.)-এর জ্যেষ্ঠ পুত্র। ৩ হিজরির রমজান মাসে তাঁর জন্ম হয়। রাসুলুল্লাহ (সা.) নিজ মুখে খেজুর চিবিয়ে তাঁর মুখে দেন, তাঁর নাম রাখেন ‘হাসান’ (সুন্দর) এবং সপ্তম দিনে আকিকা করে মাথার চুলের ওজন পরিমাণ রূপা সদকা করেন।\n\nহাসান (রা.) দেখতে ছিলেন হুবহু রাসুলুল্লাহ (সা.)-এর মতো। রাসুল (সা.) হাসান ও তাঁর ছোট ভাই হোসাইনকে নিজের বুকের ওপর জড়িয়ে রাখতেন, তাঁদের কাঁধে চড়িয়ে মদিনার রাস্তায় হাঁটতেন। রাসুল বলতেন: \"হে আল্লাহ! আমি এদের দুজনকে ভালোবাসি, আপনিও এদের ভালোবাসুন এবং যে এদের ভালোবাসে তাকেও ভালোবাসুন!\"\n\n৪০ হিজরিতে পিতা আলী (রা.)-এর শাহাদাতের পর কুফাবাসী হাসান (রা.)-এর হাতে খেলাফতের বায়াত গ্রহণ করে। তিনি ছয় মাস খোলাফায়ে রাশেদীনের পঞ্চম খলিফা হিসেবে অত্যন্ত সুনামের সাথে শাসন করেন। কিন্তু মুসলিমদের রক্তপাত এড়াতে এবং উম্মাহকে গৃহযুদ্ধ থেকে রক্ষা করতে তিনি ৪১ হিজরিতে স্বেচ্ছায় মুয়াবিয়া (রা.)-এর অনুকূলে ক্ষমতা হস্তান্তর করেন। ইসলামের ইতিহাসে এই বছরটিকে ‘আমুল জামাআহ’ (ঐক্যের বছর) বলা হয়। রাসুল (সা.) বহুকাল পূর্বেই মিম্বারে বসে হাসানকে কোলে নিয়ে ভবিষ্যদ্বাণী করেছিলেন: \"আমার এই সন্তান একজন সাইয়্যিদ (মহান নেতা), এর মাধ্যমে আল্লাহ মুসলমানদের দুটি বিশাল দলের মাঝে রক্তক্ষয়ী বিবাদ মিটিয়ে শান্তি আনবেন!\" ৫০ হিজরিতে তাঁকে বিষপ্রয়োগ করা হয় এবং তিনি শাহাদাত বরণ করেন।",
    "islamAcceptanceBn": "রাসুলুল্লাহ (সা.)-এর পবিত্র কোলে জন্ম নিয়ে নবুওয়াতের পবিত্র আবহাওয়ায় বেড়ে ওঠেন।",
