        "story": "একদিন রাসুলুল্লাহ (সা.) মসজিদে নববীতে সাহাবিদের নিয়ে এশার সালাত আদায় করছিলেন। সালাতের একটি সিজদা হঠাৎ অত্যন্ত দীর্ঘ হয়ে গেল। সাহাবিদের একজন চিন্তিত হয়ে মাথা তুলে দেখলেন শিশু হাসান রাসুল (সা.)-এর পিঠের ওপর সওয়ার হয়ে বসে আছেন! সালাত শেষে সাহাবিরা বললেন: \"হে আল্লাহর রাসুল! আপনি সিজদা এত দীর্ঘ করলেন যে আমরা ভেবেছিলাম কোনো বিপদ ঘটেছে বা ওহী নাজিল হচ্ছে!\" রাসুলুল্লাহ (সা.) হাসিমুখে বললেন: \"তেমন কিছুই ঘটেনি; আসলে আমার স্নেহের নাতি আমার পিঠের ওপর চড়ে বসেছিল, আমি তাকে জোর করে নামিয়ে তার আনন্দ নষ্ট করতে চাইনি যতক্ষণ না সে নিজে নেমে যায়!\""
